window.DECK = {"categories":{"pap":"Papulosquamous","ecz":"Eczematous","acn":"Acneiform / follicular","bul":"Bullous & blistering","ctd":"Connective tissue","vas":"Vascular & vasculitis","bac":"Bacterial","vir":"Viral","fun":"Fungal","inf":"Infestations & parasites","ben":"Benign tumors & cysts","mal":"Premalignant & malignant","mel":"Melanocytic","pig":"Pigmentary","hair":"Hair","nail":"Nail","gen":"Genodermatoses","drug":"Drug & reactive","gran":"Granulomatous & metabolic","neo":"Pediatric & neonatal","oral":"Oral & mucosal","photo":"Photo-related"},"cards":[{"id":"chronic-plaque-psoriasis","name":"Plaque psoriasis","cat":"pap","lvl":1,"alt":["Psoriasis vulgaris","Psoriasis"],"dx":[{"id":"discoid-eczema"},{"id":"tinea-corporis"},{"id":"mycosis-fungoides"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Auspitz sign, Koebner phenomenon, HLA-Cw6. Flares with lithium, beta-blockers, antimalarials, and abrupt withdrawal of systemic steroids. Screen for psoriatic arthritis and metabolic syndrome. Histology: parakeratosis, Munro microabscesses, regular acanthosis, thinned suprapapillary plates.","images":[{"u":"/assets/Uploads/chronic-plaque-psoriasis-013.jpg","cap":"Well-defined scaly plaque psoriasis on the knee","c":"© DermNet"},{"u":"/assets/Uploads/scaly/plaque-psoriasis/26261a.jpg","cap":"Large plaque psoriasis lesions on the trunk - pink, well-defined with overlying thick scale","c":"© DermNet"},{"u":"/assets/Uploads/scaly/psoriasis-scalp/3563.jpg","cap":"Well-defined scaly patches of psoriasis in the scalp","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/flexural-ps23-s.jpg","cap":"Flexural psoriasis in the natal cleft - note the absence of scale where the skin surfaces are exposed","c":"© Raimo Suhonen"}]},{"id":"guttate-psoriasis","name":"Guttate psoriasis","cat":"pap","lvl":1,"alt":[],"dx":[{"id":"pityriasis-rosea"},{"id":"syphilis"},{"id":"pityriasis-lichenoides"},{"id":"lichen-planus"}],"pearl":"Abrupt \"raindrop\" eruption 2–3 weeks after group A streptococcal pharyngitis, typically in children and young adults. Check for strep; may later evolve to chronic plaque psoriasis.","images":[{"u":"/assets/Uploads/scaly/guttate-psoriasis/2755.jpg","cap":"Guttate psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/guttate-psoriasis/2752.jpg","cap":"Guttate psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/guttate-psoriasis/2764.jpg","cap":"Guttate psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/guttate-psoriasis.jpg","cap":"Guttate psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/psorgutt.jpg","cap":"Guttate psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/psorgutt2.jpg","cap":"Guttate psoriasis","c":"© DermNet"}]},{"id":"generalised-pustular-psoriasis","name":"Generalized pustular psoriasis","cat":"pap","lvl":2,"alt":["von Zumbusch psoriasis","GPP"],"dx":[{"id":"acute-generalised-exanthematous-pustulosis"},{"id":"chronic-plaque-psoriasis"},{"id":"erythroderma"}],"pearl":"IL36RN loss of function (DIRA/DITRA spectrum). Triggers: steroid withdrawal, pregnancy (impetigo herpetiformis), hypocalcemia, infection, drugs. Fever and sterile pustules on erythematous skin; spesolimab (anti-IL-36R) is approved for flares. Main mimic is AGEP, which is drug-induced and resolves in about 2 weeks.","images":[{"u":"/assets/Uploads/gen-pustular-psoriasis-01.jpg","cap":"Generalised pustular psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/gen-pustular-psoriasis-08.jpg","cap":"Generalised pustular psoriasis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/gen-pustular-psoriasis-06.jpg","cap":"Generalised pustular psoriasis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Generalised-pustular-psoriasis/generalised-pustular-psoriasis-0002.jpg","cap":"Pustular psoriasis on a limb in skin of colour","c":"© DermNet"},{"u":"/assets/Uploads/gen-pustular-psoriasis-14.jpg","cap":"Generalised pustular psoriasis","c":"© DermNet"},{"u":"/assets/collection/Generalised-pustular-psoriasis/generalised-pustular-psoriasis-0006.jpg","cap":"Superficial pustules in generalised pustular psoriasis","c":"© Dr Richard Ashton"}]},{"id":"palmoplantar-pustulosis","name":"Palmoplantar pustulosis","cat":"pap","lvl":2,"alt":["Palmoplantar psoriasis pustular"],"dx":[{"id":"tinea-pedis"},{"id":"dyshidrotic-eczema"},{"id":"acrodermatitis-continua-of-hallopeau"}],"pearl":"Strong association with smoking and women in middle age. Sterile pustules that turn brown as they age. Think SAPHO syndrome (synovitis, acne, pustulosis, hyperostosis, osteitis). Always scrape for KOH to exclude tinea.","images":[{"u":"/assets/Uploads/scaly/ps16.jpg","cap":"Pustules and rusty dots in a scaly plaque typical of PPP","c":"© DermNet"},{"u":"/assets/Uploads/scaly/pustular-psoriasis-hand-foot/3584.jpg","cap":"Pustules on the palm due to PPP","c":"© DermNet"},{"u":"/assets/Uploads/scaly/pustular-psoriasis-hand-foot/3592.jpg","cap":"Typical lesions of PPP on the soles - redness, scale, pustules, and rusty red dots","c":"© DermNet"},{"u":"/assets/Uploads/scaly/pustular-psoriasis-hand-foot/3597.jpg","cap":"Florid pustules on the feet due to PPP","c":"© DermNet"},{"u":"/assets/Uploads/scaly/pustulosis.jpg","cap":"Palmoplantar pustulosis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/ps17.jpg","cap":"Palmoplantar pustulosis","c":"© DermNet"}]},{"id":"acrodermatitis-continua-of-hallopeau","name":"Acrodermatitis continua of Hallopeau","cat":"pap","lvl":3,"alt":["Acrodermatitis continua"],"dx":[{"id":"palmoplantar-pustulosis"},{"id":"paronychia"},{"id":"nail-psoriasis"}],"pearl":"Sterile pustules of the distal digits with nail-bed destruction and onycholysis, a localized pustular psoriasis variant. Can lead to anonychia and distal bone resorption.","images":[{"u":"/assets/Uploads/scaly/acropustulosis-03.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© DermNet"},{"u":"/assets/Uploads/scaly/acropustulosis-05.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/hallopeaupeuk.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/scaly/acropustulosis-04.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© DermNet"},{"u":"/assets/Uploads/scaly/acropustulosis-06.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/hallopeau6.jpg","cap":"Acrodermatitis continua of Hallopeau","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/scaly/acropustulosis-01.jpg","cap":"Before treatment","c":"© DermNet"},{"u":"/assets/Uploads/scaly/acropustulosis-02.jpg","cap":"After use of clobetasol for 2 months","c":"© DermNet"}]},{"id":"lichen-planus","name":"Lichen planus","cat":"pap","lvl":1,"alt":[],"dx":[{"id":"lichen-nitidus"},{"id":"lichen-planopilaris"},{"id":"guttate-psoriasis"},{"id":"lichen-sclerosus"}],"pearl":"The 6 Ps: pruritic, purple, polygonal, planar, papules, plaques. Wickham striae, Koebner. Associated with hepatitis C. Hypertrophic form on the shins. Histology: sawtooth acanthosis, wedge-shaped hypergranulosis, band-like lymphocytic infiltrate, Civatte bodies.","images":[{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0001.jpg","cap":"Papular lichen planus coalescing into plaques on the wrist","c":"© DermNet"},{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0002.jpg","cap":"Flat topped, shiny, polygonal papules of lichen planus on the volar wrist","c":"© DermNet"},{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0003.jpg","cap":"A plaque of lichen planus showing Wickham striae","c":"© DermNet"},{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0008.jpg","cap":"Papular lichen planus with Koebner phenomenum in skin of colour","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0005.jpg","cap":"Lichen planus over the ankle and heel","c":"© DermNet"},{"u":"/assets/collection/Papular-lichen-planus/papular-lichen-planus-0006.jpg","cap":"Papular lichen planus with a linear Koebner lesion due to a scratch","c":"© DermNet"},{"u":"/assets/Uploads/hair-loss-02.jpg","cap":"Lichen planopilaris","c":"© DermNet"},{"u":"/assets/collection/Nail-lichen-planus/nail-lichen-planus-0001.jpg","cap":"Complete nail plate destruction due to lichen planus","c":"© DermNet"}]},{"id":"lichen-sclerosus","name":"Lichen sclerosus","cat":"pap","lvl":1,"alt":["Lichen sclerosus et atrophicus"],"dx":[{"id":"morphoea"},{"id":"vitiligo"},{"id":"lichen-planus"}],"pearl":"Porcelain-white atrophic plaques in a figure-of-eight around the vulva and anus, or balanitis xerotica obliterans in males. Hemorrhagic erosions, itch, scarring. Treat with ultrapotent topical steroid (clobetasol). About 3–5% risk of SCC, so long-term follow-up is needed.","images":[{"u":"/assets/Uploads/immune/ls9.jpg","cap":"Lichen Sclerosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/ls11.jpg","cap":"Lichen Sclerosus","c":"© DermNet"},{"u":"/assets/collection-O/Lichen-sclerosus/lichen-sclerosus-00002.jpg","cap":"lichen sclerosus 00002","c":"© DermNet"},{"u":"/assets/collection-O/Lichen-sclerosus-in-skin-of-colour/lichen-sclerosus-00019.jpg","cap":"lichen sclerosus 00019","c":"© DermNet"},{"u":"/assets/Uploads/doctors/scaly-rashes/images/ls1.jpg","cap":"Axillary lichen sclerosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/ls10.jpg","cap":"Lichen Sclerosus","c":"© DermNet"}]},{"id":"pityriasis-rosea","name":"Pityriasis rosea","cat":"pap","lvl":1,"alt":[],"dx":[{"id":"guttate-psoriasis"},{"id":"syphilis"},{"id":"tinea-corporis"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Herald patch followed by oval lesions with collarette scale along Langer lines in a \"Christmas tree\" pattern. Associated with HHV-6/7. Self-limited over 6–8 weeks. Check RPR if palms/soles are involved. Drug-induced pityriasis rosea-like eruptions occur.","images":[{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0003.jpg","cap":"Pityriasis rosea and a herald patch on the torso","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0010.jpg","cap":"A hypopigmented herald patch","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0002.jpg","cap":"Flexural pityriasis rosea and a herald patch in the axilla","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0011.jpg","cap":"Pityriasis rosea on the trunk","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0001.jpg","cap":"Oval scaly patches in pityriasis rosea on the trunk","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-rosea/pityriasis-rosea-0005.jpg","cap":"Hypopigmented pityriasis rosea in skin of colour","c":"© Te Whatu Ora"}]},{"id":"pityriasis-rubra-pilaris","name":"Pityriasis rubra pilaris","cat":"pap","lvl":2,"alt":["PRP"],"dx":[{"id":"chronic-plaque-psoriasis"},{"id":"erythroderma"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Orange-red scaly plaques with islands of sparing, follicular keratotic papules (nutmeg-grater feel on dorsal fingers), and waxy orange keratoderma. Type I (classic adult) is the most common and usually clears within 3 years. Retinoids, methotrexate and biologics are used. Histology: alternating orthokeratosis and parakeratosis in both directions (\"checkerboard\").","images":[{"u":"/assets/Uploads/scaly/prp2.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/prp3.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/prp8.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/prp9.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/prp4.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/prp7.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/prp1.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/prp6.jpg","cap":"Pityriasis rubra pilaris","c":"© DermNet"}]},{"id":"pityriasis-lichenoides","name":"Pityriasis lichenoides","cat":"pap","lvl":3,"alt":["PLEVA","PLC","Pityriasis lichenoides et varioliformis acuta"],"dx":[{"id":"lymphomatoid-papulosis"},{"id":"guttate-psoriasis"},{"id":"chickenpox"}],"pearl":"Acute (PLEVA) has crusted, necrotic, varioliform papules in crops; chronic (PLC) has scaly red-brown papules with a \"mica\" scale. Lymphomatoid papulosis is the main mimic; biopsy distinguishes them. Responds to UVB and tetracyclines.","images":[{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0001.jpg","cap":"Pityriasis lichenoides chronica on the chest","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0005.jpg","cap":"The mica-like scale in pityriasis lichenoides chronica","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0010.jpg","cap":"Widespread truncal pityriasis lichenoides chronica","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0020.jpg","cap":"Mica-like scale in pityriasis lichenoides chronica","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0002.jpg","cap":"Ulcerated pityriasis lichenoides acuta","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0003.jpg","cap":"Pityriasis lichenoides acuta on the arm","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0043.jpg","cap":"Pityriasis lichenoides acuta in a child","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-lichenoides/pityriasis-lichenoides-0044.jpg","cap":"Ulcerated pityriasis lichenoides acuta on the arm","c":"© DermNet"}]},{"id":"lichen-nitidus","name":"Lichen nitidus","cat":"pap","lvl":3,"alt":[],"dx":[{"id":"lichen-planus"},{"id":"keratosis-pilaris"},{"id":"molluscum-contagiosum"}],"pearl":"Tiny, uniform, flesh-colored shiny papules, often on the genitalia, forearms and abdomen; Koebner positive. Histology shows a \"claw-clutching-a-ball\" infiltrate (rete ridges grasping a granuloma).","images":[{"u":"/assets/Uploads/scaly/w/lichen-nitidus1.jpg","cap":"Lichen nitidus","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/lichen-nitidus2.jpg","cap":"Lichen nitidus","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/lichennitid4.jpg","cap":"Lichen nitidus","c":"© DermNet"}]},{"id":"lichen-striatus","name":"Lichen striatus","cat":"pap","lvl":2,"alt":[],"dx":[{"id":"epidermal-naevi"},{"id":"lichen-planus"},{"id":"chronic-plaque-psoriasis"}],"pearl":"Sudden linear band of small flat papules following Blaschko lines in a child, usually on a limb. Self-limited over months to a year; may leave transient hypopigmentation and can cause nail dystrophy.","images":[{"u":"/assets/Uploads/dermatitis/striatus1.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/striatus2.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/pathology/s/striatus2.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/striatus3.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/lichen-striatus-1.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/striatus4.jpg","cap":"Lichen striatus","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/striatus5.jpg","cap":"Lichen striatus","c":"© DermNet"}]},{"id":"seborrhoeic-dermatitis","name":"Seborrheic dermatitis","cat":"pap","lvl":1,"alt":["Seborrhoeic dermatitis"],"dx":[{"id":"chronic-plaque-psoriasis"},{"id":"rosacea"},{"id":"tinea-corporis"},{"id":"discoid-lupus-erythematosus"}],"pearl":"Greasy yellow scale in sebaceous areas: scalp, nasolabial folds, eyebrows, ears, presternal. Malassezia-driven. Severe or abrupt onset suggests HIV; also common in Parkinson disease. Treat with topical antifungals (ketoconazole) and low-potency steroids.","images":[{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0008.jpg","cap":"Seborrhoeic blepharitis and dermatitis on the cheeks","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0009.jpg","cap":"Scale and erythema due to seborrhoeic dermattis on the glabella and brows","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0010.jpg","cap":"Flexural seborrhoeic dermatitis in the axilla","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0007.jpg","cap":"Confluent erythema and scale due to scalp seborrhoeic dermatitis","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0006.jpg","cap":"Presternal seborrhoeic dermatitis and pityrosporum folliculitis","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0005.jpg","cap":"Pigmented paranasal seborrhoeic dermatitis in skin of colour","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0046.jpg","cap":"Infantile seborrhoeic dermatitis - note eczema in the napkin area and axillae and crade cap","c":"© DermNet"},{"u":"/assets/collection/Seborrhoeic-dermatitis/seborrhoeic-dermatitis-0047.jpg","cap":"Thick yellow scale in crade cap","c":"© DermNet"}]},{"id":"atopic-dermatitis","name":"Atopic dermatitis","cat":"ecz","lvl":1,"alt":["Atopic eczema","Eczema"],"dx":[{"id":"allergic-contact-dermatitis"},{"id":"seborrhoeic-dermatitis"},{"id":"scabies"},{"id":"mycosis-fungoides"}],"pearl":"Flexural in adults, face and extensors in infants. FLG loss-of-function, Th2 skew (IL-4/13). Dupilumab can cause conjunctivitis and facial erythema. Eczema herpeticum is the emergency complication. Hanifin–Rajka criteria; Dennie–Morgan lines, keratosis pilaris, ichthyosis vulgaris link.","images":[{"u":"/assets/Uploads/SCORAD/atopic-dryness-3.jpg","cap":"Dry atopic dermatitis in an extensor pattern","c":"© DermNet"},{"u":"/assets/Uploads/SCORAD/atopic-oozy-2.jpg","cap":"Acute flexural atopic dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/atopic-eczema-02.jpg","cap":"Chronic flexural atopic dermatitis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/dermatitis/at-derm7.jpg","cap":"Infantile atopic dermatitis on the cheeks","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/flexural-eczema22.jpg","cap":"Flexural atopic dermatitis in childhood","c":"© DermNet"},{"u":"/assets/Uploads/SCORAD/atopic-excoriation-2.jpg","cap":"Excoriated lichenified atopic dermatitis on the lower back in an adult","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/at-derm1.jpg","cap":"Infantile atopic dermatitis, face","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/s/atopic26.jpg","cap":"Infantile atopic dermatitis, hand","c":"© DermNet"}]},{"id":"allergic-contact-dermatitis","name":"Allergic contact dermatitis","cat":"ecz","lvl":1,"alt":["Contact dermatitis"],"dx":[{"id":"irritant-contact-dermatitis"},{"id":"atopic-dermatitis"},{"id":"herpes-zoster"}],"pearl":"Type IV delayed hypersensitivity. Linear vesicles suggest Toxicodendron (poison ivy). Nickel (earlobes, umbilicus), fragrance, preservatives, neomycin, and rubber accelerators are common allergens. Diagnose by patch testing read at 48 and 96 hours. Topical steroids, not antihistamines, are the treatment.","images":[{"u":"/assets/collection/Allergic-contact-dermatitis/allergic-contact-dermatitis-0004.jpg","cap":"Acute weeping exudative allergic contact dermatitis due to a hair dye used on the beard","c":"© DermNet"},{"u":"/assets/collection/Allergic-contact-dermatitis/allergic-contact-dermatitis-0011.jpg","cap":"Chronic lichenified allergic contact dermatitis due to leather in a sandal","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Allergic-contact-dermatitis/allergic-contact-dermatitis-00002.jpg","cap":"Allergic contact dermatitis due to a rubber accelerator (used in the rubber curing process)","c":"© DermNet"},{"u":"/assets/collection/Allergic-contact-dermatitis/allergic-contact-dermatitis-0029.jpg","cap":"Acute allergic contact dermatitis due to lavender oil used on the pillow case to promote sleep","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/acd-plaster.jpg","cap":"Adhesive plaster reaction","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/acdss.jpg","cap":"Sunscreen reaction","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/acdnic.jpg","cap":"Watch strap reaction","c":"© DermNet"},{"u":"/assets/collection/Allergic-contact-dermatitis/allergic-contact-dermatitis-0152.jpg","cap":"Allergic contact dermatitis due to an adhesive in orthopaedic strapping","c":"© Te Whatu Ora"}]},{"id":"irritant-contact-dermatitis","name":"Irritant contact dermatitis","cat":"ecz","lvl":1,"alt":[],"dx":[{"id":"allergic-contact-dermatitis"},{"id":"atopic-dermatitis"},{"text":"Tinea manuum"}],"pearl":"Non-immune damage from wet work, soaps, solvents; the most common occupational skin disease (hands). Borders are sharp and burning is more prominent than itch. Patch tests are negative. Management is avoidance and barrier repair.","images":[{"u":"/assets/Uploads/reactions/icd3.jpg","cap":"Hand dermatitis due to wet work","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/icd.jpg","cap":"Irritant dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/s/icd5.jpg","cap":"Irritant dermatitis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/doctors/follicular/images/top2.jpg","cap":"Irritant dermatitis due to benzoyl peroxide","c":"© DermNet"},{"u":"/assets/Uploads/toxAtop.jpg","cap":"Atopic irritant hand dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/chemical-burn-107.jpg","cap":"Acute irritant contact dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/icd4.jpg","cap":"Irritant dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/s/icd6.jpg","cap":"Sentinel sign","c":"© DermNet"}]},{"id":"discoid-eczema","name":"Nummular (discoid) eczema","cat":"ecz","lvl":1,"alt":["Nummular eczema","Discoid eczema"],"dx":[{"id":"chronic-plaque-psoriasis"},{"id":"tinea-corporis"},{"id":"mycosis-fungoides"}],"pearl":"Coin-shaped, exudative, pruritic plaques on the lower legs and arms. Often worse in winter and with dry skin; consider contact allergens and stasis. Always scrape out tinea. Isotretinoin is a recognized trigger.","images":[{"u":"/assets/Uploads/discoid-eczema-day-2.jpg","cap":"Discoid eczema day 2","c":"© DermNet"},{"u":"/assets/Uploads/discoid-eczema-day-6.jpg","cap":"Discoid eczema day 6","c":"© DermNet"},{"u":"/assets/Uploads/discoid-eczema-day-14.jpg","cap":"Discoid eczema day 14","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/nummular4.jpg","cap":"Discoid eczema","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/nummular6.jpg","cap":"Discoid eczema","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/s/nummular9.jpg","cap":"Discoid eczema","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/dermatitis/s/eanumm2.jpg","cap":"Infected nummular atopic dermatitis","c":"© Raimo Suhonen"}]},{"id":"dyshidrotic-eczema","name":"Dyshidrotic eczema","cat":"ecz","lvl":1,"alt":["Pompholyx","Dyshidrosis"],"dx":[{"id":"palmoplantar-pustulosis"},{"id":"tinea-pedis"},{"id":"allergic-contact-dermatitis"},{"id":"scabies"}],"pearl":"Deep-seated \"tapioca\" vesicles on the palms, soles and sides of fingers. Look for an id reaction from tinea pedis and for nickel/cobalt allergy; IVIG and some medications can trigger it. Treat with potent topical steroids.","images":[{"u":"/assets/Uploads/dermatitis/pompholyx/3529.jpg","cap":"Discrete vesicles and blisters on the palmar skin","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/dermatitis/pompholyx/3519.jpg","cap":"Vesicles and blisters on the fingers in vesicular eczema","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/dermatitis/pompholyx/3538.jpg","cap":"Extensive vesticulation and blistering on the soles - vesicular eczema is usually symmetrical","c":"© DermNet"}]},{"id":"lichen-simplex","name":"Lichen simplex chronicus","cat":"ecz","lvl":1,"alt":["Neurodermatitis"],"dx":[{"id":"nodular-prurigo"},{"id":"lichen-planus"},{"id":"atopic-dermatitis"}],"pearl":"The itch–scratch cycle produces a lichenified, well-demarcated plaque on accessible sites (nape, ankles, vulva, scrotum). Treat with ultrapotent steroid, occlusion, and break the habit.","images":[{"u":"/assets/collection/Lichen-simplex/lichen-simplex-0003.jpg","cap":"Lichen simplex on the ankles - accentuated skin markings, scale and pigmentation in skin of colour","c":"© DermNet"},{"u":"/assets/Uploads/systemic/w/itchy-skin-15.jpg","cap":"Lichen simplex","c":"© DermNet"}]},{"id":"nodular-prurigo","name":"Prurigo nodularis","cat":"ecz","lvl":2,"alt":["Picker nodules"],"dx":[{"id":"lichen-simplex"},{"text":"Hypertrophic lichen planus"},{"id":"scabies"}],"pearl":"Firm, excoriated nodules on extensor limbs, sparing the mid-upper back (butterfly sign). Look for underlying causes: atopy, renal or liver itch, HIV, hepatitis C. Dupilumab and nemolizumab are approved options.","images":[{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0001.jpg","cap":"Excoriated papules on the arms in nodular prurigo","c":"© DermNet"},{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0008.jpg","cap":"Nodular prurigo on the arms","c":"© DermNet"},{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0004.jpg","cap":"Excoriated prurigo lesions on the legs","c":"© DermNet"},{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0015.jpg","cap":"Pigmentation of prurigo nodules in skin of colour","c":"© DermNet"},{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0026.jpg","cap":"Prurigo on the dorsal hands in skin of colour","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Nodular-prurigo/nodular-prurigo-0027.jpg","cap":"Dome shaped prurigo on the ankles","c":"© Dr Richard Ashton"}]},{"id":"asteatotic-eczema","name":"Asteatotic eczema","cat":"ecz","lvl":1,"alt":["Eczema craquelé","Xerotic eczema"],"dx":[{"id":"ichthyosis-vulgaris"},{"id":"stasis-ulcer"},{"id":"discoid-eczema"}],"pearl":"Cracked \"crazy-paving\" fissures on the shins of an older patient in dry weather. Treat with emollients, reduce over-bathing, and low-to-mid potency steroid.","images":[{"u":"/assets/Uploads/dermatitis/eczema-craquele1.jpg","cap":"Eczema craquelé","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/eczema-craquele2.jpg","cap":"Eczema craquelé","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/eczema-craquele3.jpg","cap":"Eczema craquelé","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/eczema-craquele4.jpg","cap":"Eczema craquelé","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/eczema-craquele5.jpg","cap":"Eczema craquelé","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/eczema-craquele6.jpg","cap":"Eczema craquelé","c":"© DermNet"}]},{"id":"venous-eczema","name":"Stasis dermatitis","cat":"ecz","lvl":1,"alt":["Venous eczema","Gravitational eczema"],"dx":[{"id":"cellulitis"},{"id":"lipodermatosclerosis"},{"id":"asteatotic-eczema"}],"pearl":"Scaly, hemosiderin-stained eczema of the lower legs from venous hypertension. Often misdiagnosed as bilateral cellulitis. Compression is the key therapy; beware of contact sensitization to topicals.","images":[{"u":"/assets/Uploads/grav-derm-alt-v2.jpg","cap":"Venous eczema","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/lipodermatosclerosis.jpg","cap":"Lipodermatosclerosis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/dermatitis/ulcer.jpg","cap":"Venous ulcer","c":"© DermNet"}]},{"id":"periorificial-dermatitis","name":"Perioral dermatitis","cat":"acn","lvl":1,"alt":["Periorificial dermatitis"],"dx":[{"id":"acne-vulgaris"},{"id":"rosacea"},{"id":"seborrhoeic-dermatitis"},{"id":"allergic-contact-dermatitis"}],"pearl":"Papulopustules around the mouth, nose and eyes with a sparing rim next to the vermilion border. Linked to topical (and inhaled) steroids and fluorinated toothpaste. Stop steroids; treat with doxycycline, topical metronidazole or calcineurin inhibitors.","images":[{"u":"/assets/collection/Perioral-dermatitis/perioral-dermatitis-0001.jpg","cap":"Perioral erythematous papules sparing the immediate perivermillion skin in perioral dermatitis","c":"© DermNet"},{"u":"/assets/collection/Perioral-dermatitis/perioral-dermatitis-0008.jpg","cap":"Perioral and nasolabial fold papules sparing the perivermillion skin in perioral dermatitis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/acne/perioral-dermatitis/3403.jpg","cap":"Perioral dermatitis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/acne/perioral-dermatitis/3406.jpg","cap":"Periocular dermatitis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/acne/perioral-dermatitis/3408.jpg","cap":"Perioral dermatitis","c":"© Raimo Suhonen"},{"u":"/assets/collection/Perioral-dermatitis/perioral-dermatitis-0002.jpg","cap":"Perioral dermatitis due to the use of a steroid nebuliser mask","c":"© DermNet"},{"u":"/assets/collection/Perioral-dermatitis/perioral-dermatitis-0006.jpg","cap":"Papules and pustules (an unusual feature) in perioral dermatitis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Perioral-dermatitis/perioral-dermatitis-0007.jpg","cap":"Florid perioral dermatitis due to potent topical steroid use","c":"© Dr Richard Ashton"}]},{"id":"erythroderma","name":"Erythroderma","cat":"ecz","lvl":2,"alt":["Exfoliative dermatitis"],"dx":[{"id":"pityriasis-rubra-pilaris"},{"id":"sezary-syndrome"},{"id":"chronic-plaque-psoriasis"},{"id":"atopic-dermatitis"}],"pearl":">90% BSA erythema. Common causes: psoriasis, eczema, drugs, CTCL (Sézary), PRP, idiopathic. Complications: high-output heart failure, thermoregulation failure, protein loss, infection. Biopsy and drug history are essential.","images":[{"u":"/assets/Uploads/reactions/erythroderma1.jpg","cap":"Erythroderma","c":"© DermNet"},{"u":"/assets/Uploads/reactions/erythroderma2.jpg","cap":"Erythroderma","c":"© DermNet"},{"u":"/assets/Uploads/erythroderma3.jpg","cap":"Erythroderma","c":"© DermNet"}]},{"id":"malassezia-folliculitis","name":"Malassezia (pityrosporum) folliculitis","cat":"acn","lvl":2,"alt":["Pityrosporum folliculitis"],"dx":[{"id":"acne-vulgaris"},{"id":"folliculitis-decalvans"},{"id":"tinea-corporis"}],"pearl":"Monomorphic itchy follicular papules and pustules on the chest and back that do not respond to antibiotics. Yeast on a smear or biopsy; treat with ketoconazole shampoo or oral itraconazole/fluconazole.","images":[{"u":"/assets/Uploads/fungal/pitfol1.jpg","cap":"Malassezia folliculitis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pitfol2.jpg","cap":"Malassezia folliculitis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pitfol3.jpg","cap":"Malassezia folliculitis","c":"© DermNet"}]},{"id":"acne-vulgaris","name":"Acne vulgaris","cat":"acn","lvl":1,"alt":["Acne"],"dx":[{"id":"rosacea"},{"id":"periorificial-dermatitis"},{"id":"malassezia-folliculitis"}],"pearl":"Comedones are the primitive lesion; Cutibacterium acnes and follicular hyperkeratinization drive it. Isotretinoin requires iPLEDGE, and monitoring of lipids and LFTs; teratogenic. Spironolactone helps hormonal acne in women. Avoid monotherapy with antibiotics.","images":[{"u":"/assets/Uploads/acne/acne1.jpg","cap":"Acne vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/acne/acne3.jpg","cap":"Acne vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/acne/acne5.jpg","cap":"Acne vulgaris","c":"© DermNet"},{"u":"/assets/collection-O/Acne-with-post-inflammatory-pigmentation/acne-00067.jpg","cap":"Acne","c":"© DermNet"},{"u":"/assets/Uploads/acne/w/acne-mild.jpg","cap":"Mild acne","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/acne/acne4.jpg","cap":"Moderate acne","c":"© DermNet"},{"u":"/assets/Uploads/acne/s/acne6.jpg","cap":"Severe acne","c":"© Raimo Suhonen"}]},{"id":"rosacea","name":"Rosacea","cat":"acn","lvl":1,"alt":["Acne rosacea"],"dx":[{"id":"acne-vulgaris"},{"id":"seborrhoeic-dermatitis"},{"id":"periorificial-dermatitis"},{"id":"discoid-lupus-erythematosus"}],"pearl":"Central face erythema, papules/pustules and telangiectasia with no comedones. Subtypes: erythematotelangiectatic, papulopustular, phymatous (rhinophyma), ocular. Treatments: metronidazole, ivermectin, azelaic acid, brimonidine, doxycycline.","images":[{"u":"/assets/collection/Rosacea/rosacea-0004.jpg","cap":"Papulopustular rosacea on the cheeks","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0022.jpg","cap":"Erythematotelangiectatic and papulopustular rosacea on the cheeks","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0003.jpg","cap":"Papular rosacea on the cheeks","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0010.jpg","cap":"Rhinophyma and papular rosacea on the chin","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0001.jpg","cap":"Papulopustular and ocular rosacea","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0002.jpg","cap":"Rhinophyma","c":"© DermNet"},{"u":"/assets/collection/Rosacea/rosacea-0009.jpg","cap":"Rhinophyma showing swelling and sebeceous gland openings","c":"© DermNet"},{"u":"/assets/collection/Steroid-rosacea/steroid-rosacea-0001.jpg","cap":"Steroid induced papulopustular rosacea","c":"© DermNet"}]},{"id":"hidradenitis-suppurativa","name":"Hidradenitis suppurativa","cat":"acn","lvl":1,"alt":["Acne inversa"],"dx":[{"id":"boil"},{"text":"Pilonidal"},{"id":"erythrasma"}],"pearl":"Part of the follicular occlusion tetrad (HS, acne conglomerata, dissecting cellulitis of the scalp, pilonidal sinus). Double-ended comedones, sinus tracts, scarring. Hurley staging; adalimumab, secukinumab and bimekizumab are approved; surgery for chronic tunnels. Associated with smoking, obesity and SCC in chronic lesions.","images":[{"u":"/assets/Uploads/hidradenitis-suppurativa-019.jpg","cap":"Mild axillary HS showing scars and post-inflammatory erythema","c":"© DermNet"},{"u":"/assets/Uploads/hidradenitis-comedones.jpg","cap":"Marked comedones in axillary HS","c":"© DermNet"},{"u":"/assets/Uploads/hidradenitis-suppurativa-001.jpg","cap":"Nodules and sinus formation in axillary HS","c":"© DermNet"},{"u":"/assets/Uploads/doctors/follicular/images/hidrad4.jpg","cap":"HS in the groins spreading down to the upper thighs","c":"© DermNet"},{"u":"/assets/Uploads/acne/hidradenitis-nodule.jpg","cap":"An acute painful inflammatory nodule in axillary HS","c":"© DermNet"},{"u":"/assets/Uploads/acne/hidradenitis7.jpg","cap":"Severe axillary HS with scars and sinus formation","c":"© DermNet"},{"u":"/assets/Uploads/hs-breast-082.jpg","cap":"Submammary HS","c":"© DermNet"},{"u":"/assets/Uploads/hs-inflammatory-115.jpg","cap":"Inflammatory HS in the groin with multiple painful nodules","c":"© DermNet"}]},{"id":"pseudofolliculitis-barbae","name":"Pseudofolliculitis barbae","cat":"acn","lvl":1,"alt":["Razor bumps"],"dx":[{"id":"folliculitis-keloidalis"},{"id":"acne-vulgaris"},{"text":"Tinea barbae"}],"pearl":"Ingrown curly hairs after shaving, most commonly in men of African descent (curved follicle). Stop close shaving, use depilatories or laser hair removal (Nd:YAG for dark skin).","images":[{"u":"/assets/Uploads/pseudofolliculitis-6.jpg","cap":"Pseudofolliculitis barbae","c":"© DermNet"},{"u":"/assets/Uploads/pseudofolliculitis-8.jpg","cap":"Pseudofolliculitis barbae","c":"© DermNet"},{"u":"/assets/Uploads/pseudofolliculitis-1.jpg","cap":"Ingrowing beard hair","c":"© DermNet"},{"u":"/assets/Uploads/pseudofolliculitis-7.jpg","cap":"Pseudofolliculitis barbae","c":"© DermNet"},{"u":"/assets/Uploads/doctors/bacterial-infections/images/folliculitis11.jpg","cap":"Pseudofolliculitis","c":"© DermNet"},{"u":"/assets/collection/Pseudofolliculitis-barbae/pseudofolliculitis-barbae-0001.jpg","cap":"Rounded pigmented papules in the beard area in pseudofolliculitis barbae","c":"© DermNet"}]},{"id":"folliculitis-keloidalis","name":"Acne keloidalis nuchae","cat":"acn","lvl":2,"alt":["Folliculitis keloidalis nuchae","Acne keloidalis"],"dx":[{"id":"pseudofolliculitis-barbae"},{"id":"folliculitis-decalvans"},{"id":"keloid-and-hypertrophic-scar"}],"pearl":"Firm keloidal papules and plaques on the occipital scalp and nape in men, often of African descent; a scarring (primary lymphocytic) folliculitis. Early disease: potent steroids and doxycycline; established lesions may need surgical excision.","images":[{"u":"/assets/collection/Folliculitis-keloidalis/folliculitis-keloidalis-0019.jpg","cap":"Small papules and nodules with overlying alopecia due to FKN","c":"© DermNet"},{"u":"/assets/collection/Folliculitis-keloidalis/folliculitis-keloidalis-0021.jpg","cap":"A pustule evident within an area of FKN","c":"© DermNet"},{"u":"/assets/collection/Folliculitis-keloidalis/folliculitis-keloidalis-0020.jpg","cap":"Papules and alopecia on the nape of the neck in FKN","c":"© DermNet"},{"u":"/assets/collection/Folliculitis-keloidalis/folliculitis-keloidalis-0022.jpg","cap":"Papules, nodules and keloid like scars on the nape","c":"© Te Whatu Ora"},{"u":"/assets/collection/Folliculitis-keloidalis/folliculitis-keloidalis-0023.jpg","cap":"Dense scarring alopecia and tufting over the nape in advanced FKN","c":"© Te Whatu Ora"}]},{"id":"folliculitis-decalvans","name":"Folliculitis decalvans","cat":"acn","lvl":2,"alt":[],"dx":[{"id":"folliculitis-keloidalis"},{"id":"lichen-planopilaris"},{"id":"tinea-capitis"}],"pearl":"Neutrophilic scarring alopecia with tufted hairs (polytrichia) and pustules. Chronic S. aureus colonization; rifampin plus clindamycin, or long-term doxycycline.","images":[{"u":"/assets/Uploads/hair-nails-sweat/follic-decalv3.jpg","cap":"Folliculitis decalvans","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/follic-decalv5.jpg","cap":"Folliculitis decalvans","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/follic-decalv.jpg","cap":"Folliculitis decalvans","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/w/folliculitis-decalvans-29.jpg","cap":"Perifollicular crusting and scale","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/hair-nails-sweat/follic-decalv1.jpg","cap":"Tufted hairs and perifollicular crusting","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/follic-decalv4.jpg","cap":"Tufted hairs and perifollicular erythema","c":"© DermNet"}]},{"id":"perifolliculitis-capitis-abscedens-et-suffodiens","name":"Dissecting cellulitis of the scalp","cat":"acn","lvl":3,"alt":["Perifolliculitis capitis abscedens et suffodiens"],"dx":[{"id":"folliculitis-decalvans"},{"id":"tinea-capitis"},{"id":"hidradenitis-suppurativa"}],"pearl":"Boggy, interconnected abscesses and sinuses on the vertex/occiput with scarring alopecia. Part of the follicular occlusion tetrad. Isotretinoin is first line; TNF-inhibitors for recalcitrant disease.","images":[{"u":"/assets/perifollicultis5.jpg","cap":"perifollicultis5","c":"© DermNet"},{"u":"/assets/perifolliculitis4.jpg","cap":"perifolliculitis4","c":"© DermNet"},{"u":"/assets/perifolliculitis6.jpg","cap":"perifolliculitis6","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/dissecting-cellulitis-32.jpg","cap":"Dissecting cellulitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/dissecting-cellulitis-31.jpg","cap":"Dissecting cellulitis","c":"© DermNet"},{"u":"/assets/Uploads/acne/perifolliculitis3.jpg","cap":"Dissecting cellulitis","c":"© DermNet"}]},{"id":"keratosis-pilaris","name":"Keratosis pilaris","cat":"acn","lvl":1,"alt":[],"dx":[{"id":"lichen-nitidus"},{"id":"pityriasis-rubra-pilaris"},{"id":"scurvy"}],"pearl":"Rough follicular papules on the extensor arms and thighs; associated with atopy and ichthyosis vulgaris. Variants: KP rubra faciei, atrophicans (ulerythema ophryogenes).","images":[{"u":"/assets/Uploads/acne/keratosis-pilaris/3013.jpg","cap":"Keratosis pilaris","c":"© DermNet"},{"u":"/assets/Uploads/acne/keratosis-pilaris/3016.jpg","cap":"Keratosis pilaris","c":"© DermNet"},{"u":"/assets/Uploads/acne/keratosis-pilaris/3024.jpg","cap":"Keratosis pilaris","c":"© DermNet"},{"u":"/assets/Uploads/acne/s/kerapil2.jpg","cap":"Keratosis pilaris rubra faciei","c":"© DermNet"},{"u":"/assets/Uploads/acne/keratosis-pilaris-2.jpg","cap":"Ulerythema ophryogenes","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/acne/keratosis-pilaris-3.jpg","cap":"Atrophoderma vermiculata","c":"© DermNet"}]},{"id":"miliaria","name":"Miliaria","cat":"acn","lvl":2,"alt":["Heat rash","Sweat rash"],"dx":[{"text":"Folliculitis"},{"text":"Erythema toxicum"},{"id":"acne-vulgaris"}],"pearl":"Eccrine duct obstruction: crystallina (superficial, clear vesicles), rubra (deeper, erythematous, itchy), profunda (deeper, flesh-colored). Occurs in neonates and in hot, humid conditions or occlusion.","images":[{"u":"/assets/Uploads/hair-nails-sweat/miliaria1.jpg","cap":"Miliaria","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/miliaria2.jpg","cap":"Miliaria","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/miliaria3.jpg","cap":"Miliaria","c":"© DermNet"}]},{"id":"transient-acantholytic-dermatosis","name":"Grover disease","cat":"acn","lvl":2,"alt":["Transient acantholytic dermatosis"],"dx":[{"id":"darier-disease"},{"id":"malassezia-folliculitis"},{"id":"atopic-dermatitis"}],"pearl":"Itchy, discrete red papules on the trunk of older men, triggered by heat, sweating, or sun and bed rest. Histology shows focal acantholysis mimicking Darier, Hailey–Hailey or pemphigus. Responds to cooling, emollients, topical steroids, and phototherapy.","images":[{"u":"/assets/Uploads/scaly/grover1.jpg","cap":"Grovers disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/grover2.jpg","cap":"Grovers disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/grover5.jpg","cap":"Grovers disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/grover3.jpg","cap":"Grovers disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/grover4.jpg","cap":"Grovers disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/grover6.jpg","cap":"Grovers disease","c":"© DermNet"}]},{"id":"bullous-pemphigoid","name":"Bullous pemphigoid","cat":"bul","lvl":1,"alt":[],"dx":[{"id":"pemphigus-vulgaris"},{"id":"dermatitis-herpetiformis"},{"id":"mucous-membrane-pemphigoid"},{"id":"epidermolysis-bullosa-acquisita"}],"pearl":"Tense bullae on an urticarial base in older adults; antibodies to BP180 (NC16A) and BP230 at the hemidesmosome. DIF: linear IgG and C3 at the BMZ; salt-split skin shows binding on the epidermal (roof) side. Associated with gliptins, loop diuretics and neurologic disease. Treat with topical clobetasol or doxycycline; dupilumab is a newer targeted option.","images":[{"u":"/assets/Uploads/immune/bulpem4.jpg","cap":"Bullous pemphigoid","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/bulpem6.jpg","cap":"Bullous pemphigoid","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/immune/s/bulpem5.jpg","cap":"Bullous pemphigoid","c":"© Raimo Suhonen"},{"u":"/assets/collection-O/Bullous-pemphigoid/bullous-pemphigoid-00095.jpg","cap":"Blisters of bullous pemphigoid on foot, skin of colour","c":"© DermNet"},{"u":"/assets/Uploads/immune/bulpem1.jpg","cap":"Bullous pemphigoid","c":"© DermNet"},{"u":"/assets/Uploads/immune/bulpem2.jpg","cap":"Bullous pemphigoid","c":"© DermNet"}]},{"id":"pemphigus-vulgaris","name":"Pemphigus vulgaris","cat":"bul","lvl":1,"alt":[],"dx":[{"id":"pemphigus-foliaceus"},{"id":"bullous-pemphigoid"},{"id":"mucous-membrane-pemphigoid"},{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"}],"pearl":"Flaccid bullae, painful oral erosions that often precede skin disease, and a positive Nikolsky sign. Antibodies to desmoglein 3 (mucosal) ± desmoglein 1. DIF: intercellular IgG and C3 (\"fishnet\"). Histology: suprabasal acantholysis with a \"tombstone\" row of basal cells. Rituximab is first-line.","images":[{"u":"/assets/Uploads/immune/pgus4.jpg","cap":"Pemphigus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/immune/pgus3.jpg","cap":"Pemphigus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/immune/pgus5.jpg","cap":"Pemphigus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/pgus7.jpg","cap":"Pemphigus vulgaris","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/immune/pgus8.jpg","cap":"Pemphigus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/pgus9.jpg","cap":"Pemphigus vulgaris","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/immune/pgus1.jpg","cap":"Oral pemphigus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/immune/pgus6.jpg","cap":"Ocular pemphigus vulgaris","c":"© DermNet"}]},{"id":"pemphigus-foliaceus","name":"Pemphigus foliaceus","cat":"bul","lvl":2,"alt":[],"dx":[{"id":"pemphigus-vulgaris"},{"id":"seborrhoeic-dermatitis"},{"id":"impetigo"},{"id":"discoid-lupus-erythematosus"}],"pearl":"Superficial erosions with scale-crust on a seborrheic distribution; no mucosal involvement. Anti-desmoglein 1 (subcorneal split). Endemic form: fogo selvagem in Brazil. Drug-induced triggers include penicillamine and captopril (thiol drugs).","images":[{"u":"/assets/Uploads/immune/pfol1.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"},{"u":"/assets/Uploads/immune/pfol2.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"},{"u":"/assets/Uploads/immune/pfol3.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"},{"u":"/assets/Uploads/immune/pfol4.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"},{"u":"/assets/Uploads/immune/pfol5.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/pfol6.jpg","cap":"Pemphigus foliaceus","c":"© DermNet"}]},{"id":"dermatitis-herpetiformis","name":"Dermatitis herpetiformis","cat":"bul","lvl":1,"alt":[],"dx":[{"id":"bullous-pemphigoid"},{"id":"linear-iga-bullous-disease"},{"id":"scabies"},{"id":"atopic-dermatitis"}],"pearl":"Intensely itchy grouped vesicles on the elbows, knees and buttocks, often excoriated. Gluten-sensitive enteropathy (HLA-DQ2/DQ8). DIF of perilesional skin: granular IgA in the dermal papillae; autoantigen epidermal transglutaminase. Treat with a gluten-free diet and dapsone (check G6PD).","images":[{"u":"/assets/collection/Dermatitis-herpetiformis/dermatitis-herpetiformis-0001.jpg","cap":"Clustered vesicles have been excoriated on the elbows in dermatitis herpetiformis","c":"© DermNet"},{"u":"/assets/collection/Dermatitis-herpetiformis/dermatitis-herpetiformis-0032.jpg","cap":"Elbow, sacral and buttock lesions - the classical distribution of dermatitis herpetiformis","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Dermatitis-herpetiformis/dermatitis-herpetiformis-0004.jpg","cap":"Excoriated vesicles on the buttocks and sacrum in dermatitis herpetiformis","c":"© DermNet"},{"u":"/assets/Uploads/immune/dh3.jpg","cap":"Dermatitis herpetiformis","c":"© DermNet"},{"u":"/assets/collection/Dermatitis-herpetiformis/dermatitis-herpetiformis-0022.jpg","cap":"Hairline lesions in dermatitis herpetiformis","c":"© Dr Richard Ashton"},{"u":"/assets/Uploads/immune/s/dh4.jpg","cap":"Dermatitis herpetiformis","c":"© Raimo Suhonen"}]},{"id":"linear-iga-bullous-disease","name":"Linear IgA bullous dermatosis","cat":"bul","lvl":2,"alt":["Linear IgA disease","Chronic bullous disease of childhood"],"dx":[{"id":"dermatitis-herpetiformis"},{"id":"bullous-pemphigoid"},{"id":"impetigo"}],"pearl":"\"String of pearls\" or \"crown of jewels\" annular blisters. Linear IgA at the BMZ on DIF; target is the BP180 ectodomain (LAD-1, 120 kDa, and LABD97, 97 kDa). Vancomycin is the classic drug trigger. Dapsone/sulfapyridine responsive.","images":[{"u":"/assets/collection/Linear-IgA-bullous-disease/linear-IgA-bullous-disease-00008.jpg","cap":"Blisters on the leg in Linear IgA disease","c":"© DermNet"},{"u":"/assets/collection/Linear-IgA-bullous-disease/linear-IgA-bullous-disease-00002.jpg","cap":"'String of beads' sign in a child with linear IgA disease","c":"© DermNet"},{"u":"/assets/collection/Linear-IgA-bullous-disease/linear-IgA-bullous-disease-00001.jpg","cap":"Symblepharon in linear IgA disease","c":"© DermNet"},{"u":"/assets/Uploads/immune/liga6.jpg","cap":"Linear IgA","c":"© DermNet"},{"u":"/assets/Uploads/immune/liga7.jpg","cap":"Linear IgA","c":"© DermNet"},{"u":"/assets/Uploads/immune/liga8.jpg","cap":"Linear IgA","c":"© DermNet"},{"u":"/assets/Uploads/immune/liga4.jpg","cap":"Palmar blisters","c":"© DermNet"},{"u":"/assets/Uploads/immune/liga5.jpg","cap":"String of beads sign","c":"© DermNet"}]},{"id":"epidermolysis-bullosa-acquisita","name":"Epidermolysis bullosa acquisita","cat":"bul","lvl":3,"alt":["EBA"],"dx":[{"id":"bullous-pemphigoid"},{"id":"porphyria-cutanea-tarda"},{"id":"epidermolysis-bullosa"}],"pearl":"Autoantibodies to type VII collagen (anchoring fibrils). Trauma-induced bullae with scarring and milia on acral sites (mechanobullous) or an inflammatory BP-like variant. Associated with Crohn disease. DIF: linear IgG; floor (dermal) side of salt-split skin.","images":[{"u":"/assets/Uploads/immune/s/eba3.jpg","cap":"Epidermolysis bullosa acquisita","c":"© Raimo Suhonen"},{"u":"/assets/collection/Epidermolysis-bullosa-acquisita/epidermolysis-bullosa-acquisita-0004.jpg","cap":"Atrophic scars on the pressure points of the knees due to epidermolysis bullosa acquisita","c":"© DermNet"},{"u":"/assets/collection/Epidermolysis-bullosa-acquisita/epidermolysis-bullosa-acquisita-0001.jpg","cap":"Milia on the arms due to epidermolysis bullosa acquisita","c":"© DermNet"},{"u":"/assets/Uploads/doctors/emergencies/images/blist-eba.jpg","cap":"Blisters milia and scars due to EBA - they may mimic porphyria cutanea tarda","c":"© DermNet"}]},{"id":"mucous-membrane-pemphigoid","name":"Mucous membrane pemphigoid","cat":"bul","lvl":2,"alt":["Cicatricial pemphigoid"],"dx":[{"id":"pemphigus-vulgaris"},{"id":"oral-lichen-planus"},{"id":"bullous-pemphigoid"}],"pearl":"Scarring erosive disease of oral, ocular (symblepharon), nasal, laryngeal and esophageal mucosa; ophthalmology review is mandatory to prevent blindness. Anti-laminin 332 subtype is linked with internal malignancy.","images":[{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0011.jpg","cap":"Gingival erosions due to MMP","c":"© DermNet"},{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0010.jpg","cap":"A palatal erosion due to MMP","c":"© DermNet"},{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0003.jpg","cap":"A synaechia of the conjunctiva due to MMP","c":"© DermNet"},{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0019.jpg","cap":"Conjunctival symblepharon due to MMP","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0002.jpg","cap":"Cutaneous blisters in MMP - the mouth and eye were also affected","c":"© DermNet"},{"u":"/assets/collection/Mucous-membrane-pemphigoid/mucous-membrane-pemphigoid-0009.jpg","cap":"Penile erosions and scarring due to MMP","c":"© DermNet"}]},{"id":"pemphigoid-gestationis","name":"Pemphigoid gestationis","cat":"bul","lvl":2,"alt":["Herpes gestationis"],"dx":[{"id":"polymorphic-eruption-of-pregnancy"},{"id":"bullous-pemphigoid"},{"text":"Prurigo of pregnancy"}],"pearl":"Periumbilical urticarial plaques and bullae in late pregnancy/postpartum; anti-BP180 antibodies. Associated with prematurity and small-for-gestational-age infants; can recur earlier in later pregnancies. Differentiated from PUPPP by periumbilical involvement.","images":[{"u":"/assets/Uploads/immune/pemgest1.jpg","cap":"Pemphigoid gestationis","c":"© DermNet"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00017.jpg","cap":"pemphigoid gestationis 00017","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00019.jpg","cap":"pemphigoid gestationis 00019","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00018.jpg","cap":"pemphigoid gestationis 00018","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00020.jpg","cap":"Pemphigoid gestationis","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00003.jpg","cap":"pemphigoid gestationis 00003","c":"© Dr Richard Ashton"},{"u":"/assets/Uploads/pemgest6.jpg","cap":"Pemphigoid gestationis","c":"© DermNet"},{"u":"/assets/collection/Pemphigoid-gestationis/pemphigoid-gestationis-00004.jpg","cap":"pemphigoid gestationis 00004","c":"© Dr Richard Ashton"}]},{"id":"polymorphic-eruption-of-pregnancy","name":"Polymorphic eruption of pregnancy (PUPPP)","cat":"neo","lvl":2,"alt":["PUPPP","Pruritic urticarial papules and plaques of pregnancy"],"dx":[{"id":"pemphigoid-gestationis"},{"text":"Prurigo of pregnancy"},{"id":"atopic-dermatitis"}],"pearl":"Starts in the abdominal striae and spares the umbilicus; most often in primigravidas in the third trimester. Benign for the fetus; treat with topical steroids and antihistamines.","images":[{"u":"/assets/Uploads/reactions/puppp1.jpg","cap":"Polymorphic eruption of pregnancy PUPPP","c":"© DermNet"},{"u":"/assets/Uploads/polymorphic-pregnancy.jpg","cap":"Polymorphic eruption of pregnancy","c":"© DermNet"},{"u":"/assets/Uploads/pupp4.jpg","cap":"Polymorphic eruption of pregnancy","c":"© DermNet"}]},{"id":"paraneoplastic-pemphigus","name":"Paraneoplastic pemphigus","cat":"bul","lvl":3,"alt":["Paraneoplastic autoimmune multiorgan syndrome"],"dx":[{"id":"pemphigus-vulgaris"},{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"},{"id":"erythema-multiforme"}],"pearl":"Severe stomatitis (hallmark) with polymorphous cutaneous lesions. Associated with non-Hodgkin lymphoma, CLL, Castleman disease, thymoma. Antibodies to envoplakin/periplakin and desmoplakins; can cause bronchiolitis obliterans.","images":[{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0001.jpg","cap":"Severe oral paraneoplastic pemphigus due to an underlying Castleman tumour","c":"© DermNet"},{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0021.jpg","cap":"Lichenoid lesions on the hand in paraneoplastic pemphigus associated with Castleman disease","c":"© DermNet"},{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0022.jpg","cap":"Palmar changes in paraneoplastic pemphigus associated with Castleman disease","c":"© DermNet"},{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0002.jpg","cap":"Facial paraneoplastic pemphigus due to tonsil lymphoma","c":"© DermNet"},{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0007.jpg","cap":"Erosions over the torso in paraneoplastic pemphigus","c":"© Te Whatu Ora"},{"u":"/assets/collection/Paraneoplastic-pemphigus/paraneoplastic-pemphigus-0003.jpg","cap":"Scalp crusting and erosions in paraneoplastic pemphigus","c":"© Te Whatu Ora"}]},{"id":"porphyria-cutanea-tarda","name":"Porphyria cutanea tarda","cat":"bul","lvl":2,"alt":["PCT"],"dx":[{"id":"epidermolysis-bullosa-acquisita"},{"text":"Pseudoporphyria"},{"id":"erythropoietic-protoporphyria"}],"pearl":"Uroporphyrinogen decarboxylase deficiency causing blisters, fragility, milia and hypertrichosis on sun-exposed skin; urine is coral-pink/Wood lamp positive. Associated with hepatitis C, HIV, hemochromatosis, alcohol, estrogens. Treat with phlebotomy or low-dose hydroxychloroquine.","images":[{"u":"/assets/Uploads/systemic/s/pct5.jpg","cap":"Porphyria cutanea tarda","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pct7.jpg","cap":"Porphyria cutanea tarda","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pct6.jpg","cap":"Porphyria cutanea tarda","c":"Open access image"},{"u":"/assets/Uploads/systemic/pct2.jpg","cap":"Porphyria cutanea tarda","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pct3.jpg","cap":"Porphyria cutanea tarda","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pct4.jpg","cap":"Porphyria cutanea tarda","c":"© DermNet"}]},{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis","name":"Stevens–Johnson syndrome / TEN","cat":"drug","lvl":1,"alt":["SJS","TEN","Toxic epidermal necrolysis"],"dx":[{"id":"erythema-multiforme"},{"id":"staphylococcal-scalded-skin-syndrome"},{"id":"pemphigus-vulgaris"},{"id":"acute-generalised-exanthematous-pustulosis"}],"pearl":"Mucocutaneous emergency with epidermal detachment (<10% SJS, 10–30% overlap, >30% TEN). Drugs: allopurinol (HLA-B*58:01), carbamazepine (HLA-B*15:02), lamotrigine, sulfonamides, nevirapine, NSAIDs. Granulysin/FasL-mediated keratinocyte apoptosis. Stop the culprit, send to a burn/ICU unit; cyclosporine or etanercept have supportive data.","images":[{"u":"/assets/Uploads/reactions/ten1.jpg","cap":"Toxic epidermal necrolysis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/ten2.jpg","cap":"Toxic epidermal necrolysis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/ten4.jpg","cap":"Toxic epidermal necrolysis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/s/sjs3.jpg","cap":"Toxic epidermal necrolysis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/reactions/sjs6.jpg","cap":"Stevens Johnson Syndrome","c":"© DermNet"},{"u":"/assets/Uploads/reactions/s/sjs4.jpg","cap":"Stevens Johnson Syndrome","c":"© DermNet"},{"u":"/assets/Uploads/reactions/dyspigmentation.jpg","cap":"Dyspigmentation","c":"© DermNet"},{"u":"/assets/Uploads/reactions/nail-loss.jpg","cap":"Nail shedding","c":"© DermNet"}]},{"id":"erythema-multiforme","name":"Erythema multiforme","cat":"drug","lvl":1,"alt":[],"dx":[{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"},{"id":"chronic-urticaria"},{"id":"bullous-pemphigoid"}],"pearl":"Fixed target lesions with three zones, acral predominance. Most often caused by HSV (recurrent EM) and Mycoplasma pneumoniae; contrasts with SJS, which is drug-induced. Prophylactic acyclovir for recurrent HSV-associated EM.","images":[{"u":"/assets/Uploads/reactions/ac-em.jpg","cap":"Cutaneous adverse reaction to anticonvulsant, erythema multiforme target lesions","c":"© DermNet"},{"u":"/assets/Uploads/doctors/systemic/images/em2.jpg","cap":"Erythema multiforme minor","c":"© DermNet"},{"u":"/assets/Uploads/reactions/ermulti1.jpg","cap":"Erythema multiforme","c":"© DermNet"},{"u":"/assets/manualthumbnails/erythema-multiforme-034.jpg","cap":"Erythema multiforme","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/em-lips4.jpg","cap":"Lip involvement in erythema multiforme","c":"© DermNet"}]},{"id":"staphylococcal-scalded-skin-syndrome","name":"Staphylococcal scalded skin syndrome","cat":"bac","lvl":2,"alt":["SSSS"],"dx":[{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"},{"id":"pemphigus-foliaceus"},{"id":"impetigo"}],"pearl":"Exfoliative toxins A/B cleave desmoglein 1 → superficial (subcorneal/granular layer) peeling with perioral crusting and sparing of mucosa; children under 5 or adults with renal failure. Treat with IV anti-staph antibiotics. Mucosal sparing distinguishes it from TEN.","images":[{"u":"/assets/collection/Staphylococcal-scalded-skin-syndrome/staphylococcal-scalded-skin-syndrome-0002.jpg","cap":"Superficial blistering over the axillae, face and chest due to staphylococcal scalded skin sydrome","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Staphylococcal-scalded-skin-syndrome/staphylococcal-scalded-skin-syndrome-0013.jpg","cap":"Superficial erosions in the napkin area and widespread erythema in staphylococcal scalded skin syndrome","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Staphylococcal-scalded-skin-syndrome/staphylococcal-scalded-skin-syndrome-0016.jpg","cap":"Erythema and wrinkling of the necrotic epidermis in staphylococcal scalded skin syndrome","c":"© Te Whatu Ora"},{"u":"/assets/collection/Staphylococcal-scalded-skin-syndrome/staphylococcal-scalded-skin-syndrome-0001.jpg","cap":"A post-operative Staphylococcal wound infection was followed by this eruption - widespread partial thickess epidermal necrosis with normal mucous membranes due to staphylococcal scalded skin syndrome","c":"© DermNet"},{"u":"/assets/Uploads/ssss-039.jpg","cap":"Staphylococcal scalded skin syndrome","c":"© DermNet"},{"u":"/assets/collection/Staphylococcal-scalded-skin-syndrome/staphylococcal-scalded-skin-syndrome-0004.jpg","cap":"Erythema, scaling and crusting in an infant with staphylococcal scalded skin syndrome","c":"© Dr Lawrence Meyerson"}]},{"id":"epidermolysis-bullosa","name":"Epidermolysis bullosa","cat":"gen","lvl":2,"alt":["EB"],"dx":[{"id":"epidermolysis-bullosa-acquisita"},{"id":"staphylococcal-scalded-skin-syndrome"},{"id":"impetigo"}],"pearl":"Level of split guides type: simplex (KRT5/14, intraepidermal), junctional (laminin 332, COL17A1, plantar scarring, enamel hypoplasia), dystrophic (COL7A1, sub-lamina densa, mitten deformity, SCC risk), Kindler (FERMT1, photosensitivity, poikiloderma). Gene therapy: beremagene geperpavec (B-VEC), prademagene zamikeracel.","images":[{"u":"/assets/Uploads/systemic/eb1.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb2.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb3.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb4.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb5.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb6.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb7.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eb8.jpg","cap":"Epidermolysis bullosa","c":"© DermNet"}]},{"id":"discoid-lupus-erythematosus","name":"Discoid lupus erythematosus","cat":"ctd","lvl":1,"alt":["DLE","Chronic cutaneous lupus"],"dx":[{"id":"subacute-cutaneous-lupus-erythematosus"},{"id":"lichen-planopilaris"},{"id":"chronic-plaque-psoriasis"},{"id":"sarcoidosis"}],"pearl":"Scarring, atrophic plaques with follicular plugging, dyspigmentation and scarring alopecia on the face, scalp and ears. About 5–10% progress to SLE. Histology: interface dermatitis, follicular plugging, thickened BMZ, dermal mucin. Hydroxychloroquine (dose 5 mg/kg actual weight, regular eye screening); smoking reduces response.","images":[{"u":"/assets/collection/Discoid-lupus-erythematosus/discoid-lupus-erythematosus-0015.jpg","cap":"Conchal bowl discoid lupus erythematosus (Shuster sign)","c":"© Te Whatu Ora"},{"u":"/assets/collection/Discoid-lupus-erythematosus/discoid-lupus-erythematosus-0029.jpg","cap":"Active inflammatory discoid lupus erythematosus with hypopigmented scarred areas on the cheek","c":"© Te Whatu Ora"},{"u":"/assets/collection/Discoid-lupus-erythematosus/discoid-lupus-erythematosus-0033.jpg","cap":"Well circumscribed scarred ear lobe due to discoid lupus erythematosus","c":"© Te Whatu Ora"},{"u":"/assets/collection/Discoid-lupus-erythematosus/discoid-lupus-erythematosus-0018.jpg","cap":"Scarring alopecia due to discoid lupus erythematosus","c":"© Te Whatu Ora"},{"u":"/assets/collection/Discoid-lupus-erythematosus/discoid-lupus-erythematosus-0019.jpg","cap":"erythematosus Discoid lupus erythematosus Scarring alopecia with follicular plugging in discoid lupus erythematosus","c":"© Te Whatu Ora"}]},{"id":"subacute-cutaneous-lupus-erythematosus","name":"Subacute cutaneous lupus erythematosus","cat":"ctd","lvl":1,"alt":["SCLE"],"dx":[{"id":"discoid-lupus-erythematosus"},{"id":"chronic-plaque-psoriasis"},{"id":"tinea-corporis"},{"id":"polymorphic-light-eruption"}],"pearl":"Photodistributed annular or papulosquamous plaques that heal without scarring. Anti-Ro/SSA positive; neonatal lupus risk. Drug triggers: hydrochlorothiazide, terbinafine, PPIs, ACE-inhibitors, calcium channel blockers.","images":[{"u":"/assets/Uploads/reactions/scle2.jpg","cap":"Drug-induced subacute lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/subacute-lupus-01-s.jpg","cap":"Subacute lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/subacute-lupus-03-s.jpg","cap":"Subacute lupus erythematosus","c":"© DermNet"}]},{"id":"systemic-lupus-erythematosus","name":"Systemic lupus erythematosus (acute cutaneous lupus)","cat":"ctd","lvl":1,"alt":["SLE","Malar rash","Acute cutaneous lupus erythematosus"],"dx":[{"id":"rosacea"},{"id":"adult-onset-dermatomyositis"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Malar rash spares the nasolabial folds (contrast with dermatomyositis and seborrheic dermatitis, which involve them). Anti-dsDNA, anti-Sm, low complement; photosensitivity. Bullous SLE has anti-type VII collagen antibodies and responds to dapsone.","images":[{"u":"/assets/Uploads/immune/sle-05.jpg","cap":"Butterfly rash","c":"© DermNet"},{"u":"/assets/Uploads/immune/w/sle-23.jpg","cap":"Bullous LE","c":"© DermNet"},{"u":"/assets/Uploads/immune/w/sle-01.jpg","cap":"Mucosal ulceration","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/immune/w/sle-28.jpg","cap":"Diffuse hair loss","c":"© DermNet"},{"u":"/assets/Uploads/immune/subacute-lupus-01.jpg","cap":"Systemic lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/subacute-lupus-02.jpg","cap":"Systemic lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/subacute-lupus-03.jpg","cap":"Systemic lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/sle-13.jpg","cap":"Systemic lupus erythematosus","c":"© DermNet"}]},{"id":"chilblain-lupus-erythematosus","name":"Chilblain lupus","cat":"ctd","lvl":3,"alt":["Chilblain lupus erythematosus"],"dx":[{"id":"chilblains"},{"id":"systemic-sclerosis"},{"id":"livedoid-vasculopathy"}],"pearl":"Painful violaceous plaques on the toes, fingers, nose and ears in cold weather with histology of lupus. Familial form linked to TREX1 mutations (type I interferonopathy). Associated with Aicardi–Goutières syndrome.","images":[{"u":"/assets/Uploads/immune/s/lupus-chilb.jpg","cap":"Chilblain lupus","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/chilblains-018-v2.jpg","cap":"Lupus chilblains","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/chilblains-016-v2.jpg","cap":"Lupus chilblains","c":"© Te Whatu Ora"}]},{"id":"neonatal-lupus-erythematosus","name":"Neonatal lupus erythematosus","cat":"ctd","lvl":2,"alt":[],"dx":[{"id":"subacute-cutaneous-lupus-erythematosus"},{"id":"tinea-corporis"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Maternal anti-Ro/SSA (± La/SSB) cross the placenta: periorbital \"raccoon-eye\" annular erythema, congenital heart block (permanent), cytopenias, and hepatic involvement. Cutaneous lesions resolve by about 6–8 months; heart block needs pacing.","images":[{"u":"/assets/Uploads/immune/lupus-neon2-s.jpg","cap":"neonatal lupus","c":"© DermNet"},{"u":"/assets/Uploads/immune/lupus-neon1.jpg","cap":"Neonatal lupus erythematosus","c":"© DermNet"},{"u":"/assets/Uploads/immune/lupus-neon.jpg","cap":"Periocular rash","c":"© DermNet"},{"u":"/assets/Uploads/immune/lupus-neon3.jpg","cap":"Annular SCLE-like rash","c":"© DermNet"}]},{"id":"adult-onset-dermatomyositis","name":"Dermatomyositis","cat":"ctd","lvl":1,"alt":["Adult dermatomyositis"],"dx":[{"id":"systemic-lupus-erythematosus"},{"text":"Psoriasis"},{"id":"chronic-plaque-psoriasis"}],"pearl":"Heliotrope rash, Gottron papules (over joints) and sign (over extensor surfaces), shawl and V signs, holster sign, mechanic hands, ragged cuticles with dilated capillary loops. Adult malignancy risk, especially with anti-TIF1-γ and anti-NXP2 antibodies. Anti-MDA5 → rapidly progressive ILD with amyopathic disease and palmar ulcers; anti-Mi-2 favors the classic phenotype; anti-synthetase (Jo-1) → ILD, mechanic hands.","images":[{"u":"/assets/Uploads/dermatomyositis-eyelids-02.jpg","cap":"Heliotrope rash","c":"© DermNet"},{"u":"/assets/Uploads/doctors/systemic/images/conn-dm1.jpg","cap":"Heliotrope rash","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-eyelids-01.jpg","cap":"Heliotrope rash","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-trunk-20.jpg","cap":"Shawl sign over the shoulder","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-arm-08.jpg","cap":"Shawl sign over the upper back","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-arm-12.jpg","cap":"Photosensitive rash on the upper arm","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/dermatomyositis-closeup-29.jpg","cap":"Photosensitive rash on the V of chest","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-hand-2.jpg","cap":"Gottron papules over the joints of the hands","c":"© DermNet"}]},{"id":"morphoea","name":"Morphea","cat":"ctd","lvl":1,"alt":["Localized scleroderma","Morphoea"],"dx":[{"id":"lichen-sclerosus"},{"id":"systemic-sclerosis"},{"id":"eosinophilic-fasciitis"}],"pearl":"Indurated ivory plaques with a lilac border; no Raynaud, sclerodactyly or visceral involvement. Subtypes include linear (en coup de sabre, Parry–Romberg), generalized and deep. Methotrexate ± steroids, UVA1 phototherapy. Borrelia is a historical association in Europe.","images":[{"u":"/assets/Uploads/immune/morph2.jpg","cap":"Morphoea","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/morph7.jpg","cap":"Morphoea","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/morph8.jpg","cap":"Morphoea","c":"© DermNet"},{"u":"/assets/Uploads/immune/morph1.jpg","cap":"Morphoea","c":"© DermNet"},{"u":"/assets/Uploads/immune/s/morph6.jpg","cap":"Morphoea","c":"© DermNet"},{"u":"/assets/Uploads/immune/morph5.jpg","cap":"Morphoea","c":"© DermNet"}]},{"id":"systemic-sclerosis","name":"Systemic sclerosis","cat":"ctd","lvl":1,"alt":["Scleroderma","CREST syndrome"],"dx":[{"id":"morphoea"},{"id":"eosinophilic-fasciitis"},{"id":"lichen-myxoedematosus"}],"pearl":"Raynaud, sclerodactyly, digital pitted scars, calcinosis, telangiectasia. Limited (anti-centromere; pulmonary hypertension) vs diffuse (anti-Scl-70/topoisomerase I; ILD) vs anti-RNA polymerase III (scleroderma renal crisis, treat with ACE inhibitor, avoid high-dose steroids, link with cancer).","images":[{"u":"/assets/Uploads/immune/ss4.jpg","cap":"Sclerodactyly","c":"© DermNet"},{"u":"/assets/Uploads/immune/ss5.jpg","cap":"Microstomia and telangiectases","c":"© DermNet"},{"u":"/assets/Uploads/puffy-hand.jpg","cap":"Puffy hand","c":"© DermNet"},{"u":"/assets/Uploads/immune/w/ss-pigmentation-1.jpg","cap":"Salt and pepper pigmentation","c":"© DermNet"},{"u":"/assets/Uploads/immune/ss3.jpg","cap":"Digital ulcers","c":"© DermNet"},{"u":"/assets/Uploads/immune/ss12.jpg","cap":"Digital calcinosis","c":"© DermNet"}]},{"id":"eosinophilic-fasciitis","name":"Eosinophilic fasciitis","cat":"ctd","lvl":3,"alt":["Shulman syndrome"],"dx":[{"id":"systemic-sclerosis"},{"id":"morphoea"},{"text":"Scleromyxoedema"}],"pearl":"Sudden, symmetric woody induration of the limbs after strenuous exercise, with a \"groove sign\" along veins and \"peau d'orange\"; Raynaud and sclerodactyly are absent. Eosinophilia, hypergammaglobulinemia, fascial thickening on MRI/full-thickness biopsy. Associated with hematologic malignancy; steroids ± methotrexate.","images":[{"u":"/assets/Uploads/dermal-infiltrative/eos-fasc.jpg","cap":"Indurated skin thickening causing limited joint mobility due to eosinophilic fasciitis","c":"© DermNet"},{"u":"/assets/Uploads/groove-sign-ef.jpg","cap":"Induration of the skin and the” groove sign” - an indentation along the course of a superficial vein","c":"© DermNet"},{"u":"/assets/Uploads/peau-dorange-ef.jpg","cap":"“Orange skin” thickening and a “groove sign”","c":"© DermNet"}]},{"id":"lichen-myxoedematosus","name":"Scleromyxedema","cat":"ctd","lvl":3,"alt":["Lichen myxoedematosus","Papular mucinosis"],"dx":[{"id":"systemic-sclerosis"},{"id":"eosinophilic-fasciitis"},{"id":"granuloma-annulare"}],"pearl":"Waxy 2–3 mm papules in linear arrangement with a \"Shar-Pei\" glabellar furrowing, and an IgG-λ paraprotein. Systemic features include neuromuscular and neurologic dermato-neuro syndrome. IVIG is the best-supported therapy.","images":[{"u":"/assets/Uploads/immune/scleromyxoedema1.jpg","cap":"Scleromyxoedema","c":"© DermNet"},{"u":"/assets/Uploads/immune/scleromyxoedema2.jpg","cap":"Scleromyxoedema","c":"© DermNet"},{"u":"/assets/Uploads/immune/scleromyxoedema3.jpg","cap":"Scleromyxoedema","c":"© DermNet"},{"u":"/assets/Uploads/immune/scleromyxoedema4.jpg","cap":"Scleromyxoedema","c":"© DermNet"},{"u":"/assets/Uploads/immune/scleromyxoedema5.jpg","cap":"Scleromyxoedema","c":"© DermNet"},{"u":"/assets/Uploads/immune/scleromyxoedema6.jpg","cap":"Scleromyxoedema","c":"© DermNet"}]},{"id":"calcinosis-cutis","name":"Calcinosis cutis","cat":"ctd","lvl":2,"alt":[],"dx":[{"id":"gout"},{"id":"epidermoid-cyst"},{"id":"pilomatricoma"}],"pearl":"Dystrophic (damaged tissue, normal Ca/P: dermatomyositis, scleroderma, lupus), metastatic (high Ca×P: renal failure, hyperparathyroidism, sarcoidosis), idiopathic (scrotum), iatrogenic. Calcinosis of dermatomyositis is more common in juvenile disease.","images":[{"u":"/assets/Uploads/systemic/calcinosis.jpg","cap":"Systemic sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calcinosis1.jpg","cap":"Systemic sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/dermatomyositis-calcinosis-45.jpg","cap":"Dermatomyositis","c":"© DermNet"}]},{"id":"cutaneous-small-vessel-vasculitis","name":"Cutaneous small vessel vasculitis","cat":"vas","lvl":1,"alt":["Leukocytoclastic vasculitis","Hypersensitivity vasculitis"],"dx":[{"id":"henoch-schoenlein-purpura"},{"text":"Pigmented purpuric dermatosis"},{"id":"chronic-urticaria"}],"pearl":"Palpable purpura on the lower legs, 7–10 days after drug (penicillins, sulfonamides, NSAIDs) or infection. Biopsy a lesion <48 hours old for H&E, and a second lesion for DIF. Check for systemic involvement: urinalysis (renal), hepatitis B/C, ANCA, cryoglobulins and complement levels.","images":[{"u":"/assets/Uploads/vascular/vasc7.jpg","cap":"Cutaneous vasculitis","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vasc6.jpg","cap":"Cutaneous vasculitis","c":"© DermNet"},{"u":"/assets/Uploads/hypersensitivity-vasculitis-v2.jpg","cap":"Hypersensitivity vasculitis","c":"© Te Whatu Ora"}]},{"id":"henoch-schoenlein-purpura","name":"IgA vasculitis (Henoch–Schönlein purpura)","cat":"vas","lvl":1,"alt":["HSP","Henoch-Schonlein purpura","IgA vasculitis"],"dx":[{"id":"cutaneous-small-vessel-vasculitis"},{"text":"Meningococcaemia"},{"id":"purpura-fulminans"}],"pearl":"Palpable purpura on the buttocks and legs, arthralgia, abdominal pain (intussusception risk) and nephritis in children after an upper respiratory infection. Perivascular IgA on DIF. In adults, renal disease is more severe and malignancy should be considered.","images":[{"u":"/assets/Uploads/vascular/hsp1.jpg","cap":"Classical purpura","c":"© DermNet"},{"u":"/assets/Uploads/vascular/hsp3.jpg","cap":"Ankle swelling (arthritis)","c":"© DermNet"},{"u":"/assets/Uploads/vascular/hsp2.jpg","cap":"Close-up of purpuric rash with vesicle (blister) formation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/hsp4.jpg","cap":"Henoch-Schönlein purpura","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/hsp5.jpg","cap":"Henoch-Schönlein purpura","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/hsp6.jpg","cap":"Henoch-Schönlein purpura","c":"© DermNet"}]},{"id":"cutaneous-polyarteritis-nodosa","name":"Cutaneous polyarteritis nodosa","cat":"vas","lvl":3,"alt":["PAN"],"dx":[{"id":"erythema-nodosum"},{"id":"livedoid-vasculopathy"},{"id":"cutaneous-small-vessel-vasculitis"}],"pearl":"Tender subcutaneous nodules and livedo racemosa on the legs without systemic organ involvement; associated with streptococcal infection. Systemic PAN: medium-vessel vasculitis with HBV, mononeuritis multiplex, renal and GI involvement, spares the lungs (ANCA negative). Biopsy deep to include medium-sized arteries.","images":[{"u":"/assets/manualthumbnails/vascular/img/pan2.jpg","cap":"Cutaneous polyarteritis nodosa","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pan1.jpg","cap":"Cutaneous polyarteritis nodosa","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/vascular/pan3.jpg","cap":"Cutaneous polyarteritis nodosa","c":"© DermNet"}]},{"id":"granulomatosis-with-polyangiitis","name":"Granulomatosis with polyangiitis","cat":"vas","lvl":2,"alt":["GPA","Wegener granulomatosis"],"dx":[{"id":"pyoderma-gangrenosum"},{"id":"sarcoidosis"},{"id":"cutaneous-small-vessel-vasculitis"}],"pearl":"Upper airway (saddle-nose), pulmonary and renal disease; c-ANCA / PR3. Skin: palpable purpura, ulcers resembling pyoderma gangrenosum and oral gingival hyperplasia (strawberry gums). Granulomatous necrotizing vasculitis; treat with rituximab or cyclophosphamide.","images":[{"u":"/assets/Uploads/systemic/wegener-lip.jpg","cap":"Lip ulceration due to granulomatosis with polyangiitis","c":"© DermNet"}]},{"id":"chronic-urticaria","name":"Chronic urticaria","cat":"vas","lvl":1,"alt":["Urticaria","Hives"],"dx":[{"text":"Urticarial vasculitis"},{"id":"erythema-multiforme"},{"id":"bullous-pemphigoid"}],"pearl":"Wheals last <24 hours and leave no marks; chronic spontaneous urticaria lasts >6 weeks. Autoimmune in about half (IgG anti-FcεRI / IgE). Step-up: second-generation antihistamines up to 4×, omalizumab, cyclosporine; dupilumab is a newer option. Lesions persisting >24 hours, tender or purpuric suggest urticarial vasculitis (biopsy).","images":[{"u":"/assets/Uploads/reactions/w/urticaria-12.jpg","cap":"Dermographism: inducible urticaria","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/urticaria-13.jpg","cap":"Spontaneous urticaria","c":"© DermNet"},{"u":"/assets/Uploads/urticaria-14.jpg","cap":"Spontaneous urticaria","c":"© DermNet"},{"u":"/assets/Uploads/doctors/wound-healing/images/excor-urt.jpg","cap":"Urticaria","c":"© DermNet"},{"u":"/assets/collection-O/Urticaria/urticaria-00002.jpg","cap":"Urticaria in skin of colour","c":"© Te Whatu Ora"},{"u":"/assets/collection-O/Urticaria/urticaria-00006.jpg","cap":"Urticarial rash in skin of colour","c":"© DermNet"}]},{"id":"pyogenic-granuloma","name":"Pyogenic granuloma","cat":"vas","lvl":1,"alt":["Lobular capillary haemangioma"],"dx":[{"id":"amelanotic-melanoma"},{"id":"kaposi-sarcoma"},{"text":"Bacillary angiomatosis"}],"pearl":"Rapidly growing, friable red papule with a collarette that bleeds easily; more common in children, pregnancy (oral), and with retinoids or EGFR inhibitors. A lobular capillary hemangioma. Amelanotic melanoma is the key mimic, so histology should be checked after shave and cautery.","images":[{"u":"/assets/Uploads/doctors/lesions/images/pg1.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/pg2.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/pg4.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pyo-gran1.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pyo-gran3.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pyo-gran2.jpg","cap":"Pyogenic granuloma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pyogenic-granuloma-2.jpg","cap":"New lesion","c":"© DermNet"},{"u":"/assets/Uploads/vascular/pyogenic-granuloma-3.jpg","cap":"2 weeks later","c":"© DermNet"}]},{"id":"capillary-vascular-malformation","name":"Port-wine stain (capillary malformation)","cat":"vas","lvl":1,"alt":["Port wine stain","Capillary malformation","Naevus flammeus"],"dx":[{"id":"infantile-haemangioma-complications-and-treatment"},{"id":"sturgeweber-syndrome"},{"id":"cherry-angioma"}],"pearl":"Persistent, non-involuting, pink-to-purple macule that darkens and thickens with age; GNAQ somatic mutation. V1/V2 involvement → Sturge–Weber (leptomeningeal angioma, glaucoma, seizures); check ophthalmology and MRI. Pulsed dye laser is the treatment.","images":[{"u":"/assets/Uploads/vascular/retic1.jpg","cap":"Reticular vascular naevus","c":"© DermNet"},{"u":"/assets/Uploads/vascular/retic2.jpg","cap":"Reticular vascular naevus","c":"© DermNet"},{"u":"/assets/Uploads/vascular/retic3.jpg","cap":"Reticular vascular naevus","c":"© DermNet"},{"u":"/assets/Uploads/vascular/ak-circum.jpg","cap":"Angiokeratoma","c":"© DermNet"}]},{"id":"infantile-haemangioma-complications-and-treatment","name":"Infantile hemangioma","cat":"neo","lvl":1,"alt":["Infantile haemangioma","Strawberry hemangioma"],"dx":[{"id":"capillary-vascular-malformation"},{"id":"pyogenic-granuloma"},{"id":"vascular-malformation"}],"pearl":"GLUT-1-positive tumor that appears in the first weeks of life, proliferates for 6–12 months, then involutes over years. Propranolol is first-line for complicated lesions. PHACE (posterior fossa, hemangioma, arterial, cardiac, eye) with large segmental facial hemangiomas; LUMBAR/SACRAL with lumbosacral lesions; beard distribution → airway hemangioma.","images":[{"u":"/assets/Uploads/vascular/cap-haem4-s.jpg","cap":"Infantile haemangioma, face","c":"© DermNet"},{"u":"/assets/Uploads/vascular/cap-haem2-s.jpg","cap":"Regressing infantile haemangioma, scalp","c":"© DermNet"},{"u":"/assets/Uploads/vascular/haeman1.jpg","cap":"Infantile haemangioma, buttock","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/cap-haem5.jpg","cap":"Infantile haemangioma, ulcerated","c":"© DermNet"},{"u":"/assets/Uploads/vascular/cap-haem1-s.jpg","cap":"Infantile haemangioma, scalp","c":"© DermNet"},{"u":"/assets/Uploads/phaces-3.jpg","cap":"Cervicofacial infantile haemangioma","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/ear/proliferative-haemangioma.jpg","cap":"Preauricular infantile haemangioma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vascular-malformation06.jpg","cap":"Vascular malformation","c":"© DermNet"}]},{"id":"vascular-malformation","name":"Venous / lymphatic vascular malformation","cat":"vas","lvl":3,"alt":["Vascular malformation"],"dx":[{"id":"infantile-haemangioma-complications-and-treatment"},{"id":"capillary-vascular-malformation"},{"id":"lipoma"}],"pearl":"Present at birth, grow proportionally with the child, never regress, and are GLUT-1 negative. Slow-flow lesions are venous, capillary, or lymphatic; fast-flow are arteriovenous. Klippel–Trénaunay is a capillary-venous-lymphatic malformation with limb overgrowth (PIK3CA). Sirolimus helps for some.","images":[{"u":"/assets/Uploads/vascular/s/vascular-malformation02.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/vascular-malformation03.jpg","cap":"Vascular malformation","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/vascular/s/vascular-malformation04.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/vascular-malformation05.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vascular-malformation01.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vascular-malformation07.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vascular-malformation08.jpg","cap":"Vascular malformation","c":"© DermNet"},{"u":"/assets/Uploads/vascular/vascular-malformation09.jpg","cap":"Vascular malformation","c":"© DermNet"}]},{"id":"kaposi-sarcoma","name":"Kaposi sarcoma","cat":"mal","lvl":2,"alt":[],"dx":[{"text":"Bacillary angiomatosis"},{"id":"angiosarcoma"},{"id":"dermatofibroma"},{"id":"pyogenic-granuloma"}],"pearl":"HHV-8-driven vascular neoplasm; violaceous patches, plaques and nodules. Four types: classic (older Mediterranean/Jewish men), endemic (African), epidemic (HIV, CD4 <200), iatrogenic (transplant). Histology: spindle cells, promontory sign, hyaline globules, LANA-1 stain. Treat the immune deficiency first.","images":[{"u":"/assets/Uploads/lesions/patch2.jpg","cap":"Patch stage KS","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ks7.jpg","cap":"Plaque stage KS","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ks9.jpg","cap":"Classic KS","c":"© DermNet"},{"u":"/assets/Uploads/lesions/oral.jpg","cap":"Palatal KS","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ks4.jpg","cap":"Plaque stage KS","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ks.jpg","cap":"Tumour stage KS","c":"© DermNet"}]},{"id":"angiosarcoma","name":"Cutaneous angiosarcoma","cat":"mal","lvl":3,"alt":["Angiosarcoma"],"dx":[{"id":"kaposi-sarcoma"},{"id":"rosacea"},{"text":"Bruise"}],"pearl":"Bruise-like violaceous plaque on the head and scalp of an elderly man, with edema and satellite nodules; aggressive. Stewart–Treves is angiosarcoma in chronic lymphedema (post-mastectomy); also arises in irradiated skin. Stains: CD31, CD34, ERG.","images":[{"u":"/assets/collection/Angiosarcoma/angiosarcoma-0001.jpg","cap":"Speading bruise like lesion on the forehead due to angiosarcoma","c":"© DermNet"},{"u":"/assets/Uploads/vascular/angiosarcoma2.jpg","cap":"Angiosarcoma","c":"© DermNet"}]},{"id":"livedoid-vasculopathy","name":"Livedoid vasculopathy","cat":"vas","lvl":3,"alt":["Atrophie blanche","Livedoid vasculitis"],"dx":[{"id":"stasis-ulcer"},{"id":"cutaneous-polyarteritis-nodosa"},{"id":"calciphylaxis"}],"pearl":"Recurrent painful ulcers on the ankles/feet that heal as porcelain-white stellate scars with surrounding telangiectasia and hyperpigmentation (atrophie blanche). A thrombo-occlusive, non-inflammatory vasculopathy; work up for hypercoagulability (factor V Leiden, antiphospholipid antibodies). Treat with anticoagulation/antiplatelet agents.","images":[{"u":"/assets/collection/Atrophie-blanche/atrophie-blanche-0007.jpg","cap":"Atrophie blanche","c":"© DermNet"},{"u":"/assets/collection/Atrophie-blanche/atrophie-blanche-0008.jpg","cap":"Atrophie blanche","c":"© DermNet"}]},{"id":"calciphylaxis","name":"Calciphylaxis","cat":"vas","lvl":2,"alt":["Calcific uraemic arteriolopathy"],"dx":[{"text":"Warfarin-induced skin necrosis"},{"id":"pyoderma-gangrenosum"},{"id":"cutaneous-polyarteritis-nodosa"}],"pearl":"Painful retiform purpura and non-healing necrotic ulcers on the thighs/abdomen in patients with end-stage renal disease; high mortality due to sepsis. Risk factors: warfarin, obesity, diabetes, hyperphosphatemia. Treat with sodium thiosulfate, wound care and by avoiding warfarin and calcium.","images":[{"u":"/assets/Uploads/systemic/calciphylaxis1.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calciphylaxis2.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calciphylaxis3.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calciphylaxis4.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calciphylaxis5.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calciphylaxis6.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/w/calciphylaxis7.jpg","cap":"Calciphylaxis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/w/calciphylaxis8.jpg","cap":"Calciphylaxis","c":"© DermNet"}]},{"id":"purpura-fulminans","name":"Purpura fulminans","cat":"vas","lvl":2,"alt":[],"dx":[{"id":"henoch-schoenlein-purpura"},{"text":"Warfarin-induced skin necrosis"},{"text":"Meningococcaemia"}],"pearl":"Rapidly progressive hemorrhagic necrosis with DIC; causes include meningococcemia, pneumococcal sepsis, and acquired/inherited protein C or S deficiency. Medical emergency requiring antibiotics, supportive care and protein C replacement.","images":[{"u":"/assets/collection/Purpura-fulminans/purpura-fulminans-0008.jpg","cap":"Purpura, incipient necrosis, and blistering due to purpura fulminans","c":"© Raimo Suhonen"},{"u":"/assets/collection/Purpura-fulminans/purpura-fulminans-0001.jpg","cap":"Haemorrhagic necrosis of the skin due to purpura fulminans - the marker lines have been added to assess extension","c":"© DermNet"},{"u":"/assets/collection/Purpura-fulminans/purpura-fulminans-0004.jpg","cap":"Extensive purpura with necrotic blistering over the toes due to purpura fulminans","c":"© DermNet"},{"u":"/assets/collection/Purpura-fulminans/purpura-fulminans-0005.jpg","cap":"Skin necrosis resulting from purpura fulminans","c":"© DermNet"}]},{"id":"erythema-ab-igne","name":"Erythema ab igne","cat":"vas","lvl":2,"alt":[],"dx":[{"text":"Livedo reticularis"},{"text":"Cutis marmorata"},{"id":"confluent-and-reticulated-papillomatosis"}],"pearl":"Reticulated erythema/hyperpigmentation from chronic infrared exposure (laptops, heating pads, space heaters). Increased risk of SCC and Merkel cell carcinoma in the long term. Remove heat source.","images":[{"u":"/assets/Uploads/reactions/igne1.jpg","cap":"Erythema ab igne","c":"© DermNet"},{"u":"/assets/Uploads/vascular/igne2.jpg","cap":"Erythema ab igne","c":"© DermNet"},{"u":"/assets/Uploads/vascular/igne3.jpg","cap":"Erythema ab igne","c":"© DermNet"},{"u":"/assets/Uploads/vascular/igne4.jpg","cap":"Erythema ab igne","c":"© DermNet"}]},{"id":"chilblains","name":"Chilblains (pernio)","cat":"vas","lvl":2,"alt":["Pernio","Perniosis"],"dx":[{"id":"chilblain-lupus-erythematosus"},{"text":"Raynaud"},{"text":"Erythromelalgia"}],"pearl":"Tender violaceous papules on acral sites 12–24 hours after cold, damp exposure. COVID toes have the same morphology. Check for lupus, cryoglobulins, and cold agglutinins in chronic cases. Nifedipine for prevention.","images":[{"u":"/assets/Uploads/reactions/pernio2.jpg","cap":"Perniosis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/pernio1.jpg","cap":"Perniosis","c":"© DermNet"},{"u":"/assets/Uploads/covid-4.jpg","cap":"Suspected COVID-19 rash","c":"© DermNet"},{"u":"/assets/Uploads/reactions/pernio3.jpg","cap":"Perniosis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/chilblains1.jpg","cap":"Chilblains","c":"© DermNet"},{"u":"/assets/Uploads/reactions/pernio5.jpg","cap":"Perniosis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/pernio4.jpg","cap":"Microgeodic disease","c":"© DermNet"}]},{"id":"angiokeratoma","name":"Angiokeratoma","cat":"vas","lvl":2,"alt":["Fabry disease angiokeratomas"],"dx":[{"id":"cherry-angioma"},{"id":"venous-lake"},{"id":"melanoma"}],"pearl":"Small dark red-blue hyperkeratotic papules. Angiokeratoma corporis diffusum is Fabry disease (α-galactosidase A deficiency, X-linked): bathing-trunk distribution, acroparesthesias, corneal verticillata, hypohidrosis, renal and cardiac disease. Fordyce angiokeratomas occur on the scrotum.","images":[{"u":"/assets/collection-O/Angiokeratoma/angiokeratoma-00001.jpg","cap":"angiokeratoma 00001","c":"© DermNet"},{"u":"/assets/collection-O/Angiokeratoma/angiokeratoma-00005.jpg","cap":"angiokeratoma 00005","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/angiokeratoma-56.jpg","cap":"Angiokeratoma","c":"© DermNet"},{"u":"/assets/Uploads/angiokeratoma-mibelli-2.jpg","cap":"Angiokeratoma of Mibelli","c":"© DermNet"},{"u":"/assets/Uploads/0046.jpg","cap":"Angiokeratoma circumscriptum","c":"© DermNet"},{"u":"/assets/Uploads/angiokeratoma-06.jpg","cap":"Angiokeratoma of Fordyce on scrotum","c":"© DermNet"}]},{"id":"cherry-angioma","name":"Cherry angioma","cat":"ben","lvl":1,"alt":["Campbell de Morgan spots","Senile angioma"],"dx":[{"id":"angiokeratoma"},{"id":"pyogenic-granuloma"},{"id":"venous-lake"}],"pearl":"Common, asymptomatic bright red papules that increase with age. Eruptive onset has been reported with bromides, cyclosporine and mustard gas.","images":[{"u":"/assets/Uploads/vascular/haeman3.jpg","cap":"Cherry angiomas","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/hemangioma2.jpg","cap":"Cherry angioma","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/vascular/s/angioma1.jpg","cap":"Cherry angioma","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/doctors/lesions/images/cherry5.jpg","cap":"Cherry angioma","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/cherry6.jpg","cap":"Cherry angioma","c":"© DermNet"}]},{"id":"venous-lake","name":"Venous lake","cat":"ben","lvl":2,"alt":[],"dx":[{"id":"melanoma"},{"id":"blue-naevus"},{"id":"cherry-angioma"}],"pearl":"Compressible dark blue papule on the lip, ear or face of an older sun-damaged person; blanches with diascopy. Treat with laser or cryosurgery for cosmesis.","images":[{"u":"/assets/Uploads/vascular/ven-lake.jpg","cap":"Venous lake","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/ven-lake2.jpg","cap":"Venous lake","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/ven-lake3.jpg","cap":"Venous lake","c":"© DermNet"},{"u":"/assets/Uploads/ectasia-compression-1.jpg","cap":"Venous lake","c":"© DermNet"},{"u":"/assets/Uploads/ectasia-compression-2.jpg","cap":"Compressing a venous lake","c":"© DermNet"},{"u":"/assets/Uploads/ectasia-compression-3.jpg","cap":"Venous lake after compression","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/ven-lake4.jpg","cap":"Venous lake","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/ven-lake5.jpg","cap":"Venous lake","c":"© DermNet"}]},{"id":"hereditary-haemorrhagic-telangiectasia","name":"Hereditary hemorrhagic telangiectasia","cat":"gen","lvl":2,"alt":["Osler–Weber–Rendu syndrome","HHT"],"dx":[{"id":"cherry-angioma"},{"id":"systemic-sclerosis"},{"id":"cafe-au-lait-macule"}],"pearl":"Autosomal dominant ENG/ACVRL1/SMAD4. Curaçao criteria: recurrent epistaxis, mucocutaneous telangiectasias (lips, tongue, fingertips), visceral AVMs (lung, brain, liver), family history. Check for pulmonary AVMs (paradoxical emboli) and SMAD4 (juvenile polyposis).","images":[{"u":"/assets/Uploads/vascular/hht1.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© DermNet"},{"u":"/assets/Uploads/vascular/hht2.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© DermNet"},{"u":"/assets/Uploads/vascular/hht3.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/hht4.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/vascular/hht5.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© DermNet"},{"u":"/assets/Uploads/vascular/hht6.jpg","cap":"Hereditary haemorrhagic telangiectasia","c":"© DermNet"}]},{"id":"impetigo","name":"Impetigo","cat":"bac","lvl":1,"alt":["Bullous impetigo"],"dx":[{"id":"herpes-simplex"},{"id":"staphylococcal-scalded-skin-syndrome"},{"id":"tinea-corporis"},{"id":"pemphigus-foliaceus"}],"pearl":"Honey-colored crusts (non-bullous: S. aureus ± GAS) or flaccid bullae (S. aureus exfoliative toxin; bullous). Poststreptococcal glomerulonephritis can follow GAS impetigo, but not rheumatic fever. Topical mupirocin or retapamulin; oral therapy for extensive disease.","images":[{"u":"/assets/collection/Impetigo/impetigo-0010.jpg","cap":"Honey-coloured crusts on the chin in impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0004.jpg","cap":"'Kissing lesions' on both sides of the axilla in impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0009.jpg","cap":"Perioral honey-coloured crusts in impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0002.jpg","cap":"Widespread bullous impetigo over the back","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0003.jpg","cap":"An intact blister and erosions in bullous impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0008.jpg","cap":"Honey-coloured crusted lesions in facial impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0006.jpg","cap":"Crusted weepy lesions in facial impetigo","c":"© DermNet"},{"u":"/assets/collection/Impetigo/impetigo-0005.jpg","cap":"Impetigo on the leg","c":"© DermNet"}]},{"id":"cellulitis","name":"Cellulitis","cat":"bac","lvl":1,"alt":[],"dx":[{"id":"venous-eczema"},{"id":"erysipelas"},{"id":"necrotising-fasciitis"},{"id":"allergic-contact-dermatitis"}],"pearl":"Deep dermal/subcutaneous infection by strep or staph; ill-defined erythema, warmth, tenderness. Look for tinea pedis or lymphedema as a portal and the risk for recurrence. Pain out of proportion + rapid progression = necrotizing fasciitis.","images":[{"u":"/assets/Uploads/cellulitis-012.jpg","cap":"Cellulitis of the left leg","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/s/cellulitis2.jpg","cap":"Cellulitis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/bacterial/cellulitis4.jpg","cap":"Cellulitis","c":"© DermNet"}]},{"id":"erysipelas","name":"Erysipelas","cat":"bac","lvl":1,"alt":[],"dx":[{"id":"cellulitis"},{"id":"herpes-zoster"},{"id":"allergic-contact-dermatitis"}],"pearl":"Sharply demarcated, raised, bright-red superficial infection of the dermis and lymphatics, with GAS the usual cause; classically on the face or lower legs. Penicillin is the drug of choice.","images":[{"u":"/assets/Uploads/bacterial/erysipelas2.jpg","cap":"Erysipelas","c":"© DermNet"},{"u":"/assets/Uploads/doctors/bacterial-infections/images/erysipelas3.jpg","cap":"Erysipelas","c":"© DermNet"},{"u":"/assets/Uploads/doctors/bacterial-infections/images/erysipelas2.jpg","cap":"erysipelas","c":"© DermNet"}]},{"id":"necrotising-fasciitis","name":"Necrotizing fasciitis","cat":"bac","lvl":2,"alt":["Necrotising fasciitis"],"dx":[{"id":"cellulitis"},{"id":"calciphylaxis"},{"text":"Warfarin-induced skin necrosis"}],"pearl":"Pain out of proportion, rapidly spreading erythema → dusky skin, bullae, crepitus, and systemic toxicity. Type I polymicrobial, type II group A strep (± staph; toxic shock). Urgent surgical debridement; imaging should not delay surgery. LRINEC is not sensitive enough to rule it out.","images":[{"u":"/assets/Uploads/bacterial/nec-fas1.jpg","cap":"Necrotising fasciitis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/nec-fas2.jpg","cap":"Necrotising fasciitis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/bacterial/nec-fas3.jpg","cap":"Necrotising fasciitis","c":"© DermNet"}]},{"id":"erythrasma","name":"Erythrasma","cat":"bac","lvl":1,"alt":[],"dx":[{"id":"tinea-cruris"},{"id":"candida"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Well-demarcated red-brown patches in the groin and axillae with fine scale caused by Corynebacterium minutissimum. Coral-red fluorescence under Wood lamp (porphyrins). Treat with topical erythromycin or clindamycin; oral erythromycin/clarithromycin if widespread.","images":[{"u":"/assets/Uploads/bacterial/erythrasma.jpg","cap":"Erythrasma","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/erythrasma13.jpg","cap":"Erythrasma","c":"© DermNet"}]},{"id":"pitted-keratolysis","name":"Pitted keratolysis","cat":"bac","lvl":2,"alt":[],"dx":[{"text":"Plantar warts"},{"id":"tinea-pedis"},{"id":"palmoplantar-pustulosis"}],"pearl":"Crateriform pits on the weight-bearing soles with malodor and hyperhidrosis; Kytococcus sedentarius, Corynebacterium, and Dermatophilus congolensis. Topical antibiotics (erythromycin, clindamycin) and antiperspirants.","images":[{"u":"/assets/collection/Pitted-keratolysis/pitted-keratolysis-0003.jpg","cap":"Pits and maceration in pitted keratolysis on the heel","c":"© DermNet"},{"u":"/assets/collection/Pitted-keratolysis/pitted-keratolysis-0001.jpg","cap":"Interdigital and toe pitted keratolysis","c":"© DermNet"},{"u":"/assets/collection/Pitted-keratolysis/pitted-keratolysis-0019.jpg","cap":"Close up of plantar pits in pitted keratolysis","c":"© Raimo Suhonen"},{"u":"/assets/collection/Pitted-keratolysis/pitted-keratolysis-0002.jpg","cap":"White macerated and pitting plantar skin in pitted keratolysis","c":"© DermNet"},{"u":"/assets/collection/Pitted-keratolysis/pitted-keratolysis-0011.jpg","cap":"Heel maceration and pits in pitted keratolysis","c":"© DermNet"}]},{"id":"leprosy","name":"Leprosy","cat":"bac","lvl":2,"alt":["Hansen's disease"],"dx":[{"id":"sarcoidosis"},{"id":"granuloma-annulare"},{"id":"tinea-corporis"},{"id":"cutaneous-tuberculosis"}],"pearl":"Mycobacterium leprae (armadillo reservoir; cool tissues, peripheral nerves). Tuberculoid: few hypoesthetic plaques, enlarged nerves, Th1, few bacilli. Lepromatous: many symmetric lesions, leonine facies, loss of lateral eyebrows, Th2, abundant bacilli. Lucio phenomenon in diffuse lepromatous. Type 1 (reversal) and type 2 (ENL) reactions. Treat with dapsone, rifampin, clofazimine.","images":[{"u":"/assets/collection-O/Leprosy/leprosy-tuberculoid-00001.jpg","cap":"Well-defined erythematous plaque on the cheek in skin of colour","c":"© DermNet"},{"u":"/assets/Uploads/doctors/bacterial-infections/images/leprosy1.jpg","cap":"leprosy","c":"© DermNet"},{"u":"/assets/Uploads/doctors/bacterial-infections/images/leprosy2.jpg","cap":"leprosy","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/leprosy3.jpg","cap":"BT leprosy with type 1 reaction","c":"© DermNet"},{"u":"/assets/collection-O/Leprosy/leprosy-borderline-borderline-00001.jpg","cap":"Red lesions of variable size. Characteristic 'Swiss cheese' appearance (black arrows)","c":"© DermNet"},{"u":"/assets/collection-O/Leprosy/leprosy-borderline-lepromatous-00001.jpg","cap":"Asymmetrical distribution of erythematous infiltrated plaques in skin of colour","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/leprosy4.jpg","cap":"Lepromatous leprosy","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/leprosy5.jpg","cap":"Lepromatous leprosy","c":"© DermNet"}]},{"id":"cutaneous-tuberculosis","name":"Cutaneous tuberculosis","cat":"bac","lvl":3,"alt":["Lupus vulgaris","Scrofuloderma"],"dx":[{"id":"sarcoidosis"},{"id":"leprosy"},{"text":"Sporotrichosis"},{"id":"leishmaniasis"}],"pearl":"Apple-jelly nodules on diascopy = lupus vulgaris (common in a previously sensitized host); scrofuloderma = contiguous extension from a lymph node/bone; tuberculosis verrucosa cutis = inoculation in a sensitized host. Histology: caseating or tuberculoid granulomas, with few organisms; use PCR.","images":[{"u":"/assets/Uploads/bacterial/lupus-vulgaris.jpg","cap":"Lupus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/tb1.jpg","cap":"Lupus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/tb2.jpg","cap":"Lupus vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/warty-tb.jpg","cap":"Cutaneous tuberculosis/warty tuberculosis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/tb3.jpg","cap":"Lupus vulgaris/looks like tuberculosis verrucosa cutis to me","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/miliary-tb.jpg","cap":"Cutaneous miliary tuberculosis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/tb-gumma.jpg","cap":"Tuberculous gumma","c":"© DermNet"},{"u":"/assets/Uploads/scrofuloderma-2-v2.jpg","cap":"Scrofuloderma","c":"© DermNet"}]},{"id":"syphilis","name":"Secondary syphilis","cat":"bac","lvl":1,"alt":["Syphilis","Treponema pallidum"],"dx":[{"id":"pityriasis-rosea"},{"id":"guttate-psoriasis"},{"id":"lichen-planus"},{"id":"morbilliform-drug-reaction"}],"pearl":"The great imitator: non-itchy symmetric copper-colored macules/papules on the trunk, palms and soles; condylomata lata, mucous patches, moth-eaten alopecia, generalized lymphadenopathy. Histology: plasma cells, endothelial swelling. Treat with benzathine penicillin G; Jarisch–Herxheimer reaction. Lues maligna in HIV. Congenital: Hutchinson teeth, saddle nose, rhagades.","images":[{"u":"/assets/Uploads/bacterial/syph6.jpg","cap":"Primary syphilis","c":"© DermNet"},{"u":"/assets/Uploads/syphilis-28.jpg","cap":"Secondary syphilis","c":"© DermNet"},{"u":"/assets/Uploads/syphilis-43.jpg","cap":"Syphilis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/s/syph4.jpg","cap":"Syphilis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/syph5.jpg","cap":"Syphilis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/syph12.jpg","cap":"Syphilis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/syph9.jpg","cap":"Syphilis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/s/syph3.jpg","cap":"Syphilis","c":"© DermNet"}]},{"id":"lyme-disease","name":"Erythema migrans (Lyme disease)","cat":"bac","lvl":1,"alt":["Lyme disease","Erythema chronicum migrans"],"dx":[{"id":"cellulitis"},{"id":"tinea-corporis"},{"id":"erythema-multiforme"}],"pearl":"Expanding annular erythema (≥5 cm) at the tick-bite site 3–30 days after Ixodes bite, usually with a central clearing. Borrelia burgdorferi. Treat with doxycycline (amoxicillin in children and pregnancy). Late disease: acrodermatitis chronica atrophicans, Borrelia lymphocytoma (ear lobe, nipple). Do not test serology for a classic EM.","images":[{"u":"/assets/Uploads/bacterial/s/ecm1.jpg","cap":"Erythema chronicum migrans","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/bacterial/s/ecm3.jpg","cap":"Erythema chronicum migrans","c":"© Raimo Suhonen"}]},{"id":"scarlet-fever","name":"Scarlet fever","cat":"bac","lvl":2,"alt":["Scarlatina"],"dx":[{"text":"Kawasaki disease"},{"id":"measles"},{"id":"staphylococcal-scalded-skin-syndrome"}],"pearl":"Group A strep pyrogenic exotoxin: sandpaper-textured blanching rash, Pastia lines in the flexures, circumoral pallor, strawberry tongue, and desquamation in the second week. Treat with penicillin.","images":[{"u":"/assets/Uploads/bacterial/scarlet-fever.jpg","cap":"Scarlet fever","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/scarlatina2.jpg","cap":"Scarlet fever","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/scarlet-arm.jpg","cap":"Scarlet fever","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/scarlatina3.jpg","cap":"Scarlet fever","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/toxic-erythema.jpg","cap":"Scarlet fever","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/scarlatina1.jpg","cap":"Peeling toes after scarlet fever","c":"© DermNet"}]},{"id":"anthrax","name":"Cutaneous anthrax","cat":"bac","lvl":3,"alt":["Anthrax"],"dx":[{"id":"orf"},{"id":"herpes-simplex"},{"id":"cellulitis"}],"pearl":"Painless black eschar with surrounding edema from Bacillus anthracis (gram-positive spore-forming rods with a \"boxcar\" shape; capsule is poly-D-glutamic acid). Ciprofloxacin or doxycycline.","images":[{"u":"/assets/Uploads/anthrax-01.jpg","cap":"At diagnosis","c":"© DermNet"},{"u":"/assets/Uploads/anthrax-02.jpg","cap":"6 days later","c":"© DermNet"},{"u":"/assets/Uploads/anthrax-03.jpg","cap":"4 weeks after diagnosis","c":"© DermNet"},{"u":"/assets/Uploads/anthrax-04.jpg","cap":"Lymphangiitis due to anthrax","c":"© DermNet"}]},{"id":"boil","name":"Furuncle (boil)","cat":"bac","lvl":1,"alt":["Abscess","Carbuncle"],"dx":[{"id":"hidradenitis-suppurativa"},{"id":"epidermoid-cyst"},{"id":"pseudofolliculitis-barbae"}],"pearl":"Deep follicular S. aureus infection; carbuncle is a coalescence of furuncles with multiple drainage points. Incision and drainage is the main therapy; decolonization with mupirocin and chlorhexidine in recurrent disease. Panton–Valentine leukocidin and MRSA.","images":[{"u":"/assets/Uploads/bacterial/boil1.jpg","cap":"Boil","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/boil2.jpg","cap":"Boil","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/boil5.jpg","cap":"Boil in axilla","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/s/boil6.jpg","cap":"Surrounding cellulitis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/bacterial/carbuncle01.jpg","cap":"Carbuncle","c":"© DermNet"},{"u":"/assets/Uploads/carbuncle-02.jpg","cap":"Carbuncle","c":"© DermNet"}]},{"id":"pseudomonas-skin-infections","name":"Pseudomonas skin infection","cat":"bac","lvl":3,"alt":["Green nail syndrome","Hot tub folliculitis","Ecthyma gangrenosum"],"dx":[{"id":"calciphylaxis"},{"id":"pyoderma-gangrenosum"},{"id":"necrotising-fasciitis"}],"pearl":"Ecthyma gangrenosum: painless hemorrhagic pustule → black eschar with a red halo in neutropenic patients (bacteremia, Pseudomonas aeruginosa). Hot tub folliculitis and green nail syndrome (chloronychia; pyocyanin) are the benign forms.","images":[{"u":"/assets/Uploads/bacterial/pseudomonas-01.jpg","cap":"Ecthyma gangrenosum","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/pseudomonas-02.jpg","cap":"Green-tinged maceration in the toeweb space","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/pseudomonas-03.jpg","cap":"Pseudomonas folliculitis","c":"© DermNet"},{"u":"/assets/Uploads/bacterial/s/pseudomonas-04.jpg","cap":"Pseudomonas infection","c":"© DermNet"},{"u":"/assets/Uploads/green-nail.jpg","cap":"Green nail due to pseudomonas infection with paronychia","c":"© DermNet"},{"u":"/assets/Uploads/green-nail2.jpg","cap":"Green nail due to pseudomonas infection","c":"© DermNet"}]},{"id":"molluscum-contagiosum","name":"Molluscum contagiosum","cat":"vir","lvl":1,"alt":[],"dx":[{"id":"viral-wart"},{"id":"lichen-nitidus"},{"id":"basal-cell-carcinoma"}],"pearl":"Poxvirus; umbilicated, dome-shaped pearly papules. Henderson–Paterson bodies on histology. Self-limited in children; giant or numerous lesions in adults suggest HIV. Treat with curettage, cantharidin or cryotherapy.","images":[{"u":"/assets/collection/Molluscum-contagiosum/molluscum-contagiosum-0016.jpg","cap":"Pseudo-koebnerisation in a scratch","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/viral/w/molluscum-contagiosum-eyelid.jpg","cap":"Shiny umbilicated papules","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/molluscum5.jpg","cap":"Typical umbilicated papules","c":"© DermNet"},{"u":"/assets/Uploads/viral/moll-ecz.jpg","cap":"Associated with eczema","c":"© DermNet"},{"u":"/assets/Uploads/viral/moll-scar.jpg","cap":"Molluscum contagiosum","c":"© DermNet"},{"u":"/assets/Uploads/Molluscum-dermatoscopy.jpg","cap":"Molluscum contagiosum","c":"© DermNet"},{"u":"/assets/Uploads/viral/molluscum57.jpg","cap":"Molluscum contagiosum","c":"© DermNet"},{"u":"/assets/Uploads/rosettes-in-molluscum-contagiosum.jpg","cap":"Typical rosettes","c":"© DermNet"}]},{"id":"viral-wart","name":"Common wart","cat":"vir","lvl":1,"alt":["Verruca vulgaris","Viral warts"],"dx":[{"id":"seborrhoeic-keratosis"},{"id":"molluscum-contagiosum"},{"text":"Squamous cell carcinoma"}],"pearl":"HPV 1, 2, 4 on the hands/feet (common, plantar), HPV 3/10 for flat warts. Thrombosed capillaries (black dots) and interruption of skin lines; mosaic warts. Cryotherapy, salicylic acid, imiquimod, candida antigen injection.","images":[{"u":"/assets/Uploads/viral/viral-wart-07.jpg","cap":"Common warts","c":"© DermNet"},{"u":"/assets/Uploads/viral/plane-warts.jpg","cap":"Plane warts","c":"© DermNet"},{"u":"/assets/Uploads/viral/viral-wart-22.jpg","cap":"Filliform wart","c":"© DermNet"},{"u":"/assets/Uploads/viral/wart27.jpg","cap":"Pseudo-koebnerisation of warts","c":"© DermNet"},{"u":"/assets/Uploads/viral/subung-wart.jpg","cap":"Subungual wart","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/wart24.jpg","cap":"Subungual wart","c":"© DermNet"},{"u":"/assets/Uploads/verrucous.jpg","cap":"Viral warts","c":"© DermNet"},{"u":"/assets/Uploads/viral/viral-wart-15.jpg","cap":"Verruca vulgaris on a thumb","c":"© DermNet"}]},{"id":"herpes-simplex","name":"Herpes simplex","cat":"vir","lvl":1,"alt":["HSV","Herpes labialis"],"dx":[{"id":"impetigo"},{"id":"herpes-zoster"},{"id":"aphthous-ulcer"}],"pearl":"HSV-1 (orofacial) and HSV-2 (genital) cause grouped vesicles on an erythematous base that erode. Tzanck smear shows multinucleated giant cells (Cowdry A inclusions, \"molded\" nuclei). Confirm with PCR. Triggers EM. Valacyclovir for recurrence.","images":[{"u":"/assets/collection-O/Herpes-simplex-SOC/herpes-simplex-00019.jpg","cap":"Herpes labialis","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/viral/hsimplex.jpg","cap":"Herpes simplex on the cheek","c":"© DermNet"},{"u":"/assets/Uploads/viral/hsimplex2.jpg","cap":"Herpetic whitlow","c":"© DermNet"},{"u":"/assets/Uploads/viral/hsimpl2.jpg","cap":"Herpes simplex","c":"© DermNet"},{"u":"/assets/Uploads/herpes-simplex-vesicles-1.jpg","cap":"Pustule due to herpes simplex","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/hair-nails-sweat/a/herpes-simplex-paronychia.jpg","cap":"Clustered vesicles, due to HSV, have broken down into erosions on the proximal nail fold","c":"© DermNet"},{"u":"/assets/Uploads/reactions/ermulti1.jpg","cap":"Erythema multiforme","c":"© DermNet"}]},{"id":"eczema-herpeticum","name":"Eczema herpeticum","cat":"vir","lvl":1,"alt":["Kaposi varicelliform eruption"],"dx":[{"id":"impetigo"},{"id":"atopic-dermatitis"},{"id":"chickenpox"}],"pearl":"Monomorphic punched-out erosions and vesicles on atopic skin, with fever. Dermatologic emergency: start IV acyclovir promptly; risk of herpetic keratitis (ophthalmology) and sepsis.","images":[{"u":"/assets/Uploads/dermatitis/ecz-herp1.jpg","cap":"Eczema herpeticum","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/ecz-herp2.jpg","cap":"Eczema herpeticum","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/ecz-herp3.jpg","cap":"Eczema herpeticum","c":"© DermNet"}]},{"id":"herpes-zoster","name":"Herpes zoster","cat":"vir","lvl":1,"alt":["Shingles"],"dx":[{"id":"herpes-simplex"},{"id":"allergic-contact-dermatitis"},{"id":"impetigo"}],"pearl":"Unilateral dermatomal vesicles; Hutchinson sign (nasociliary involvement) predicts ocular disease; Ramsay Hunt syndrome (geniculate ganglion) causes facial palsy. Treat within 72 hours with valacyclovir. Recombinant zoster vaccine (Shingrix) is recommended for adults ≥50.","images":[{"u":"/assets/Uploads/viral/zoster-13.jpg","cap":"Herpes zoster","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/hz2.jpg","cap":"Herpes Zoster","c":"© DermNet"},{"u":"/assets/Uploads/viral/zoster-12.jpg","cap":"Herpes zoster","c":"© DermNet"},{"u":"/assets/Uploads/doctors/viral-infections/images/hvz2.jpg","cap":"Herpes zoster","c":"© DermNet"},{"u":"/assets/Uploads/viral/zoster-14.jpg","cap":"Herpes zoster","c":"© DermNet"},{"u":"/assets/Uploads/viral/zoster3.jpg","cap":"Shingles","c":"© DermNet"}]},{"id":"chickenpox","name":"Varicella (chickenpox)","cat":"vir","lvl":1,"alt":["Chickenpox"],"dx":[{"id":"pityriasis-lichenoides"},{"id":"hand-foot-and-mouth-disease"},{"id":"herpes-zoster"}],"pearl":"Lesions in different stages (\"dewdrop on a rose petal\") in crops. Complications: bacterial superinfection, pneumonia (adults), Reye syndrome (aspirin), congenital varicella syndrome. Vaccinate; acyclovir for high-risk patients.","images":[{"u":"/assets/collection-O/Chickenpox/chickenpox-00044.jpg","cap":"Chickenpox on back","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/viral/w/varicella120.jpg","cap":"Chickenpox","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/viral/w/varicella106.jpg","cap":"Chickenpox","c":"© DermNet"},{"u":"/assets/collection-O/Chickenpox/chickenpox-00045.jpg","cap":"Chickenpox on face","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/viral/w/varicella123.jpg","cap":"Chickenpox","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/viral/s/varicella2.jpg","cap":"Chickenpox","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/viral/w/varicella111.jpg","cap":"Chickenpox","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/viral/w/varicella126.jpg","cap":"Chickenpox","c":"© Te Whatu Ora"}]},{"id":"hand-foot-and-mouth-disease","name":"Hand, foot and mouth disease","cat":"vir","lvl":1,"alt":["HFMD"],"dx":[{"id":"herpes-simplex"},{"id":"chickenpox"},{"id":"erythema-multiforme"}],"pearl":"Coxsackie A16 and enterovirus 71: oval gray vesicles on palms/soles and oral erosions. Coxsackie A6 causes an atypical widespread eruption in eczematous areas and nail shedding (onychomadesis) weeks later.","images":[{"u":"/assets/Uploads/enteroviral-hand-051.jpg","cap":"Hand, foot, and mouth disease","c":"© DermNet"},{"u":"/assets/Uploads/enteroviral-stomatitis-003.jpg","cap":"Stomatitis in HFMD","c":"© Raimo Suhonen"},{"u":"/assets/collection/Hand-foot-and-mouth-disease/hand-foot-and-mouth-disease-0010.jpg","cap":"Oval vesicles on the sole in hand, foot and mouth disease","c":"© DermNet"},{"u":"/assets/Uploads/handfootmouthdisese-001.jpg","cap":"Nail changes noted 6 weeks after hand and mouth blister resolution","c":"© DermNet"},{"u":"/assets/Uploads/hfm-003.jpg","cap":"Oral hand, foot, and mouth disease","c":"© DermNet"}]},{"id":"measles","name":"Measles","cat":"vir","lvl":2,"alt":["Rubeola"],"dx":[{"text":"Rocky Mountain spotted fever"},{"text":"Kawasaki disease"},{"id":"scarlet-fever"}],"pearl":"Cough, coryza, conjunctivitis, then Koplik spots (buccal mucosa) and a maculopapular rash spreading cephalocaudally from the hairline. Complications: pneumonia, encephalitis, SSPE. Vitamin A reduces mortality in children.","images":[{"u":"/assets/Uploads/viral/measles01.jpg","cap":"Koplik spots Day 1","c":"© DermNet"},{"u":"/assets/Uploads/viral/measles03.jpg","cap":"Measles","c":"© DermNet"},{"u":"/assets/Uploads/viral/measles08.jpg","cap":"Rash Day 3","c":"© DermNet"},{"u":"/assets/Uploads/viral/w/measles-28.jpg","cap":"Measles","c":"© DermNet"},{"u":"/assets/Uploads/viral/w/measles-29.jpg","cap":"Measles","c":"© DermNet"},{"u":"/assets/Uploads/viral/measles04.jpg","cap":"Measles","c":"© DermNet"}]},{"id":"erythema-infectiosum","name":"Erythema infectiosum (Fifth disease)","cat":"vir","lvl":1,"alt":["Fifth disease","Parvovirus B19"],"dx":[{"id":"systemic-lupus-erythematosus"},{"id":"scarlet-fever"},{"id":"morbilliform-drug-reaction"}],"pearl":"Parvovirus B19: \"slapped cheeks\" followed by a lacy reticulate rash on the limbs. Arthropathy in adults, aplastic crisis in hemolytic anemia/sickle cell, hydrops fetalis in pregnancy. Papular-purpuric \"gloves and socks\" syndrome is another B19 manifestation.","images":[{"u":"/assets/Uploads/viral/fifth1.jpg","cap":"Fifth disease","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/slap-cheek.jpg","cap":"Fifth disease","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/viral/fifth3.jpg","cap":"Fifth disease","c":"© DermNet"}]},{"id":"orf","name":"Orf","cat":"vir","lvl":2,"alt":["Ecthyma contagiosum"],"dx":[{"id":"milkers-nodule"},{"id":"pyogenic-granuloma"},{"id":"anthrax"}],"pearl":"Parapoxvirus from sheep/goats; solitary target-like nodule on the hand/finger with 6 stages (maculopapular, target, acute weeping, regenerative, papillomatous, regression) over ~6 weeks. Milker's nodule is clinically identical (cattle).","images":[{"u":"/assets/Uploads/orf02.jpg","cap":"Orf","c":"© DermNet"},{"u":"/assets/Uploads/viral/orf-nose.jpg","cap":"Orf","c":"© DermNet"},{"u":"/assets/Uploads/orf2.jpg","cap":"Orf","c":"© DermNet"},{"u":"/assets/Uploads/viral/orf2.jpg","cap":"Orf","c":"© DermNet"},{"u":"/assets/Uploads/reactions/em-orf1.jpg","cap":"Orf and EM","c":"© DermNet"},{"u":"/assets/Uploads/reactions/em-orf2.jpg","cap":"Orf and EM","c":"© DermNet"}]},{"id":"mpox","name":"Mpox","cat":"vir","lvl":2,"alt":["Monkeypox"],"dx":[{"id":"chickenpox"},{"id":"herpes-simplex"},{"id":"syphilis"},{"id":"molluscum-contagiosum"}],"pearl":"Orthopoxvirus with synchronous umbilicated pustules, painful lymphadenopathy, and often anogenital involvement in the 2022 outbreak. Tecovirimat for severe disease; JYNNEOS vaccine protects.","images":[{"u":"/assets/collection/Monkeypox/monkeypox-0030.jpg","cap":"Extensive umbilicated vesicles on the forehead due to mpox in a child from an endemic area","c":"© DermNet"},{"u":"/assets/collection/Monkeypox/monkeypox-0029.jpg","cap":"Extensive umbilicated vesicles on the trunk due to mpox in a child from an endemic area","c":"© DermNet"},{"u":"/assets/collection/Monkeypox/monkeypox-0028.jpg","cap":"Extensive umbilicated vesicles on the knee due to mpox in a child from an endemic area","c":"© DermNet"},{"u":"/assets/collection/Monkeypox/monkeypox-0001.jpg","cap":"Umbilicated vesicles at day 4 of infection","c":"© DermNet"},{"u":"/assets/collection/Monkeypox/monkeypox-0002.jpg","cap":"Umbilicated vesicle at day 4 of infection","c":"© DermNet"},{"u":"/assets/collection/Monkeypox/monkeypox-0007.jpg","cap":"Umbilicated vesicle on lip at day 4 of infection","c":"© DermNet"}]},{"id":"papular-acrodermatitis-of-childhood","name":"Gianotti–Crosti syndrome","cat":"vir","lvl":2,"alt":["Papular acrodermatitis of childhood","Gianotti-Crosti"],"dx":[{"id":"atopic-dermatitis"},{"id":"lichen-planus"},{"id":"hand-foot-and-mouth-disease"}],"pearl":"Symmetric, monomorphic flesh-colored to pink papules on the cheeks, buttocks and extensor limbs of a child, sparing the trunk. EBV, hepatitis B, CMV, and others; self-limited over 3–8 weeks.","images":[{"u":"/assets/Uploads/viral/gcs07.jpg","cap":"Gianotti-Crosti syndrome","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/gcs4.jpg","cap":"Infantile papular acrodermatitis","c":"© DermNet"},{"u":"/assets/Uploads/viral/gcs29.jpg","cap":"Gianotti-Crosti syndrome","c":"© DermNet"},{"u":"/assets/Uploads/viral/gcs22.jpg","cap":"Gianotti-Crosti syndrome","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/gcs59.jpg","cap":"Gianotti-Crosti syndrome","c":"© DermNet"},{"u":"/assets/Uploads/viral/gcs40.jpg","cap":"Gianotti-Crosti syndrome","c":"© DermNet"}]},{"id":"milkers-nodule","name":"Milker's nodule","cat":"vir","lvl":3,"alt":["Paravaccinia"],"dx":[{"id":"orf"},{"id":"pyogenic-granuloma"},{"id":"anthrax"}],"pearl":"Parapoxvirus from the udders of infected cows; purple-red nodule on the hands that self-resolves in 4–8 weeks. Identical to orf; ask about animal exposure.","images":[{"u":"/assets/Uploads/viral/s/milkers2.jpg","cap":"Milker's nodule","c":"© DermNet"},{"u":"/assets/Uploads/viral/s/milkers3.jpg","cap":"Milker's nodule","c":"© DermNet"}]},{"id":"tinea-corporis","name":"Tinea corporis","cat":"fun","lvl":1,"alt":["Ringworm"],"dx":[{"id":"discoid-eczema"},{"id":"chronic-plaque-psoriasis"},{"id":"granuloma-annulare"},{"id":"subacute-cutaneous-lupus-erythematosus"}],"pearl":"Annular plaque with an advancing, scaly, active border and central clearing; KOH shows branching septate hyphae. Trichophyton rubrum is the most common; oral terbinafine for extensive lesions. Tinea incognito follows topical steroid use.","images":[{"u":"/assets/Uploads/fungal/s/tincorp8.jpg","cap":"Tinea corporis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tincorp9-v2.jpg","cap":"tincorp9 v2","c":"© Raimo Suhonen"},{"u":"/assets/collection/Tinea-corporis/tinea-corporis-00019.jpg","cap":"tinea corporis 00019","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/fungal/tincorp16.jpg","cap":"Sharp red scaly margin of tinea corporis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tincorp18.jpg","cap":"Papules and pustules of tinea corporis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tincorp15.jpg","cap":"Asymmetry of tinea corporis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tiimsu.jpg","cap":"Tinea incognito","c":"© DermNet"}]},{"id":"tinea-incognito","name":"Tinea incognito","cat":"fun","lvl":2,"alt":[],"dx":[{"id":"tinea-corporis"},{"id":"discoid-eczema"},{"id":"rosacea"}],"pearl":"Dermatophyte infection modified by topical steroids: loss of the raised scaly border, pustules, and extension; Majocchi granuloma may result. Always KOH before prescribing steroids.","images":[{"u":"/assets/Uploads/fungal/tifoo.jpg","cap":"Tinea incognita - foot","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tiimsu.jpg","cap":"Tinea incognita - foot","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tintin1.jpg","cap":"Tinea incognita - groin","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tister.jpg","cap":"Tinea incognita - limb","c":"© DermNet"},{"u":"/assets/Uploads/fungal/titin.jpg","cap":"Tinea incognita - limb","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tintin2.jpg","cap":"Tinea incognita - face","c":"© DermNet"}]},{"id":"tinea-pedis","name":"Tinea pedis","cat":"fun","lvl":1,"alt":["Athlete's foot"],"dx":[{"id":"dyshidrotic-eczema"},{"id":"palmoplantar-pustulosis"},{"id":"allergic-contact-dermatitis"}],"pearl":"Interdigital, moccasin (dry, scaly) and vesiculobullous types. \"One hand, two feet\" pattern for tinea manuum. Gram-negative toe web infections complicate maceration; id reaction on the hands.","images":[{"u":"/assets/Uploads/fungal/s/tinped1.jpg","cap":"Moccasin tinea pedis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tpsev.jpg","cap":"Tinea pedis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tpto.jpg","cap":"Tinea pedis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tinped4.jpg","cap":"Tinea pedis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tinped2.jpg","cap":"Tinea pedis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tinped3.jpg","cap":"Tinea pedis","c":"© DermNet"}]},{"id":"tinea-cruris","name":"Tinea cruris","cat":"fun","lvl":1,"alt":["Jock itch"],"dx":[{"id":"erythrasma"},{"id":"candida"},{"id":"seborrhoeic-dermatitis"}],"pearl":"Red-brown, scaly plaque with a raised border extending from the groin crease onto the inner thigh; the scrotum is typically spared (spared in tinea; involved in candidiasis).","images":[{"u":"/assets/Uploads/doctors/fungal-infections/images/t-cruris2.jpg","cap":"Unilateral rash in groin","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tccru.jpg","cap":"Raised border and central clearing","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/tineacrur3.jpg","cap":"Well-defined plaque","c":"© DermNet"},{"u":"/assets/collection-O/Tinea/tinea-cruris-0001.jpg","cap":"Scaly rash in inguinal skin fold","c":"© DermNet"},{"u":"/assets/manualthumbnails/fungal/img/s/tineacrur2.jpg","cap":"Bilateral but asymmetrical rash","c":"© Raimo Suhonen"},{"u":"/assets/collection-O/Tinea/tinea-cruris-0002.jpg","cap":"Raised border, central clearing","c":"© DermNet"},{"u":"/assets/collection-O/Hailey-Hailey-disease/benign-familial-pemphigus-00029.jpg","cap":"Benign familial pemphigus","c":"© DermNet"}]},{"id":"tinea-capitis","name":"Tinea capitis","cat":"fun","lvl":1,"alt":[],"dx":[{"id":"seborrhoeic-dermatitis"},{"id":"alopecia-areata"},{"id":"folliculitis-decalvans"},{"id":"trichotillomania"}],"pearl":"Black-dot (T. tonsurans), gray patch (Microsporum), kerion and favus. Needs systemic therapy: griseofulvin or terbinafine (higher dose for Microsporum). Posterior cervical/occipital lymphadenopathy. Wood lamp: Microsporum fluoresces green; Trichophyton tonsurans does not.","images":[{"u":"/assets/Uploads/tinea-capitis-001.jpg","cap":"Tinea Capitis","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/tinea-capitis.jpg","cap":"Tinea Capitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/tinea-capitis-4.jpg","cap":"Tinea Capitis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tincap3.jpg","cap":"Grey patch scalp ringworm","c":"© DermNet"},{"u":"/assets/Uploads/fungal/blackdot-tinea-1.jpg","cap":"Black dot scalp ringworm","c":"© DermNet"},{"u":"/assets/Uploads/fungal/inflm.jpg","cap":"Tinea capitis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/tcuvl.jpg","cap":"Tinea capitis","c":"© DermNet"},{"u":"/assets/Uploads/tinea-capitis-ectothrix-hair.jpg","cap":"Ectothrix invasion by fungal hyphae in a hair shaft","c":"Open access image"}]},{"id":"pityriasis-versicolor","name":"Pityriasis (tinea) versicolor","cat":"fun","lvl":1,"alt":["Tinea versicolor"],"dx":[{"id":"vitiligo"},{"id":"pityriasis-alba"},{"id":"seborrhoeic-dermatitis"},{"id":"pityriasis-rosea"}],"pearl":"Malassezia globosa/furfur; hypo- or hyperpigmented fine-scaling macules on the trunk. \"Spaghetti and meatballs\" on KOH. Wood lamp: yellow-green fluorescence. Azole shampoo or topical selenium sulfide; oral fluconazole or itraconazole.","images":[{"u":"/assets/Uploads/fungal/pitver1.jpg","cap":"Pityriasis versicolor","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pitver4.jpg","cap":"Pityriasis versicolor","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/pitver12.jpg","cap":"Pityriasis versicolor","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pityriasis-versicolor/3481.jpg","cap":"Pityriasis versicolor","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pversic.jpg","cap":"Pityriasis versicolor","c":"© DermNet"},{"u":"/assets/Uploads/fungal/pityriasis-versicolor/3505.jpg","cap":"Pityriasis versicolor","c":"© DermNet"}]},{"id":"fungal-nail-infections","name":"Onychomycosis","cat":"fun","lvl":1,"alt":["Tinea unguium","Fungal nail infection"],"dx":[{"id":"nail-psoriasis"},{"id":"lichen-planus"},{"id":"yellow-nail-syndrome"}],"pearl":"Distal lateral subungual (T. rubrum), white superficial (T. mentagrophytes), proximal subungual (HIV; T. rubrum), and candidal. Confirm with PAS/KOH before systemic therapy: terbinafine (check LFTs; CYP2D6 interactions) or itraconazole.","images":[{"u":"/assets/collection/Onychomycosis/onychomycosis-0034.jpg","cap":"Total fingernail onychomycosis in type 6 skin","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/lat-om2.jpg","cap":"Onychomycosis","c":"© DermNet"},{"u":"/assets/collection/Onychomycosis/onychomycosis-0001.jpg","cap":"White discolouration of the distal nail plate in superficial white onychomycosis","c":"© DermNet"},{"u":"/assets/collection/Onychomycosis/onychomycosis-0004.jpg","cap":"Proximal onychomycosis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/tin-ung1-v2.jpg","cap":"Tinea unguium, toenails","c":"© DermNet"},{"u":"/assets/collection/Onychomycosis/onychomycosis-0037.jpg","cap":"Total onychomycosis due to Fusarium species","c":"© DermNet"}]},{"id":"candida","name":"Cutaneous candidiasis","cat":"fun","lvl":1,"alt":["Candidiasis","Intertrigo"],"dx":[{"id":"erythrasma"},{"id":"tinea-cruris"},{"id":"seborrhoeic-dermatitis"},{"id":"chronic-plaque-psoriasis"}],"pearl":"Beefy-red, macerated intertrigo with satellite pustules; Candida albicans. Risk: diabetes, obesity, immunosuppression, antibiotics and inhaled steroids. Treat with topical nystatin/azoles; fluconazole for refractory disease.","images":[{"u":"/assets/Uploads/fungal/canp.jpg","cap":"Candida infection","c":"© DermNet"},{"u":"/assets/Uploads/fungal/can-web.jpg","cap":"Candida infection","c":"© DermNet"},{"u":"/assets/Uploads/fungal/cfsmam.jpg","cap":"Intertrigo","c":"© DermNet"},{"u":"/assets/Uploads/fungal/canpust.jpg","cap":"Candida infection","c":"© DermNet"},{"u":"/assets/Uploads/fungal/closeup.jpg","cap":"Candida infection","c":"© DermNet"}]},{"id":"oral-candidiasis","name":"Oral candidiasis","cat":"oral","lvl":1,"alt":["Oral thrush","Thrush"],"dx":[{"id":"oral-lichen-planus"},{"id":"oral-hairy-leukoplakia"},{"text":"Oral leukoplakia"}],"pearl":"White plaques that scrape off leaving an erythematous base (pseudomembranous); other forms are erythematous, hyperplastic and angular cheilitis. Risk factors: inhaled steroids, antibiotics, diabetes, HIV, dentures. Persistent plaques that do not scrape off suggest leukoplakia, hairy leukoplakia or lichen planus.","images":[{"u":"/assets/Uploads/fungal/oral-thrush.jpg","cap":"Oral thrush","c":"© DermNet"},{"u":"/assets/Uploads/fungal/candor.jpg","cap":"Oral candidiasis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/ocan1.jpg","cap":"Angular cheilitis","c":"© DermNet"}]},{"id":"chromoblastomycosis","name":"Chromoblastomycosis","cat":"fun","lvl":3,"alt":["Chromomycosis"],"dx":[{"id":"cutaneous-tuberculosis"},{"text":"Squamous cell carcinoma"},{"id":"mycetoma"}],"pearl":"Verrucous plaques on the leg following traumatic inoculation in tropical regions; histology shows Medlar bodies (\"copper pennies\", sclerotic bodies). Itraconazole ± cryosurgery.","images":[{"u":"/assets/Uploads/fungal/chrobla.jpg","cap":"Chromoblastomycosis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/chroclo.jpg","cap":"Chromoblastomycosis","c":"© DermNet"},{"u":"/assets/Uploads/fungal/chrotoe.jpg","cap":"Chromoblastomycosis","c":"© DermNet"},{"u":"/assets/Uploads/chromoblastomycosis-01.jpg","cap":"Macro image of chromoblastomycosis","c":"© DermNet"},{"u":"/assets/Uploads/chromoblastomycosis-02.jpg","cap":"Chromoblastomycosis","c":"© DermNet"},{"u":"/assets/Uploads/chromoblastomycosis-04.jpg","cap":"chromoblastomycosis 04","c":"© DermNet"}]},{"id":"cryptococcosis","name":"Cryptococcosis","cat":"fun","lvl":3,"alt":[],"dx":[{"id":"molluscum-contagiosum"},{"text":"Histoplasmosis"},{"id":"basal-cell-carcinoma"}],"pearl":"Cryptococcus neoformans (pigeon droppings): molluscum-like umbilicated papules in HIV with meningitis; encapsulated budding yeast stained by mucicarmine; India ink; serum antigen.","images":[{"u":"/assets/collection/Cryptococcosis/cryptococcosis-0001.jpg","cap":"A haemorrhagic cellulitis-like eruption due to cryptococcosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Cryptococcosis/cryptococcosis-0004.jpg","cap":"An ulcerated area due to cryptococcosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Cryptococcosis/cryptococcosis-0005.jpg","cap":"Spreading erythema due to disseminated cryptococcosis","c":"© Te Whatu Ora"}]},{"id":"mycetoma","name":"Mycetoma","cat":"fun","lvl":3,"alt":["Madura foot"],"dx":[{"id":"chromoblastomycosis"},{"id":"cutaneous-tuberculosis"},{"text":"Sporotrichosis"}],"pearl":"Triad: swelling, draining sinuses and grains. Eumycetoma (fungal; black grains, no response to antibiotics) vs actinomycetoma (Nocardia, Actinomadura; red/white grains; sulfonamides).","images":[{"u":"/assets/Uploads/mycetoma-foot.jpg","cap":"Mycetoma foot","c":"© DermNet"},{"u":"/assets/Uploads/Mycetoma-foot-2.jpg","cap":"Courtesy Dr. Sriyani Samaraweera","c":"© DermNet"},{"u":"/assets/Uploads/fungal/mycfoot.jpg","cap":"Actinomycetoma due to nocardia","c":"© DermNet"},{"u":"/assets/Uploads/actinomycetoma-foot-and-legs-v2.jpg","cap":"Actinomycetoma foot and legs","c":"© DermNet"}]},{"id":"scabies","name":"Scabies","cat":"inf","lvl":1,"alt":[],"dx":[{"id":"atopic-dermatitis"},{"id":"dermatitis-herpetiformis"},{"id":"nodular-prurigo"},{"id":"dyshidrotic-eczema"}],"pearl":"Sarcoptes scabiei: nocturnal itch, burrows on the finger webs and wrists, genital nodules, and household contacts. Crusted (Norwegian) in the immunosuppressed. Permethrin 5% (whole body, repeat in 1–2 weeks) or oral ivermectin; treat all contacts and wash linens. Itch may persist weeks after cure.","images":[{"u":"/assets/collection/Scabies/scabies-0043.jpg","cap":"A scabies burrow on the toe","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0042.jpg","cap":"A burrow on the palm - the mite can just be seen adjacent to the vesicle","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0001.jpg","cap":"Numerous palmar scabies burrows in an elderly lady","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0016.jpg","cap":"Scabies burrows on the palm","c":"© Te Whatu Ora"},{"u":"/assets/collection/Scabies/scabies-0044.jpg","cap":"Scabies burrows on a babies foot","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0002.jpg","cap":"Interdigital scaling in the first web space of the hand","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0048.jpg","cap":"Thick crusted plaques on the thumb and palm due to crusted scabies in an elderly woman","c":"© DermNet"},{"u":"/assets/collection/Scabies/scabies-0029.jpg","cap":"Scabies with superadded streptococcal infection","c":"© Te Whatu Ora"}]},{"id":"head-lice","name":"Pediculosis capitis","cat":"inf","lvl":1,"alt":["Head lice"],"dx":[{"id":"seborrhoeic-dermatitis"},{"id":"tinea-capitis"},{"id":"impetigo"}],"pearl":"Pediculus humanus capitis; nits glued to hair shafts within 1 cm of the scalp. Posterior scalp and retroauricular papules/excoriations, occipital lymphadenopathy. Permethrin, malathion, spinosad, ivermectin lotion; comb wet hair.","images":[{"u":"/assets/Uploads/arthropods/headlouse.jpg","cap":"Louse","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/hdls.jpg","cap":"Louse","c":"Open access image"}]},{"id":"cutaneous-larva-migrans","name":"Cutaneous larva migrans","cat":"inf","lvl":1,"alt":["Creeping eruption"],"dx":[{"text":"Sporotrichosis"},{"id":"tinea-corporis"},{"id":"scabies"}],"pearl":"Serpiginous, raised, intensely itchy tracks on the feet or buttocks after walking barefoot on tropical beaches (dog/cat hookworm Ancylostoma braziliense). Treat with ivermectin or albendazole.","images":[{"u":"/assets/Uploads/arthropods/larva-mig1.jpg","cap":"Cutaneous larva migrans","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/larva-migrans.jpg","cap":"Cutaneous larva migrans","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/larva-mig2.jpg","cap":"Cutaneous larva migrans","c":"© DermNet"}]},{"id":"leishmaniasis","name":"Cutaneous leishmaniasis","cat":"inf","lvl":2,"alt":[],"dx":[{"text":"Sporotrichosis"},{"id":"cutaneous-tuberculosis"},{"text":"Squamous cell carcinoma"},{"id":"pyoderma-gangrenosum"}],"pearl":"Sandfly-borne ulcer with a raised, rolled border. Giemsa-stained smear shows amastigotes with kinetoplasts in macrophages (Leishman–Donovan bodies). Old World (L. major, tropica) vs New World (L. braziliensis → mucocutaneous espundia).","images":[{"u":"/assets/Uploads/cutaneous-leishmaniasis-12.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/cutaneous-leishmaniasis-14.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/cutaneous-leishmaniasis-19.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/cutaneous-leishmaniasis-07-v3.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/leishmaniasis4.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/leishmaniasis6.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/leishmaniasis7.jpg","cap":"Leishmaniasis","c":"© DermNet"},{"u":"/assets/Uploads/arthropods/leishmaniasis2.jpg","cap":"Leishmaniasis","c":"© DermNet"}]},{"id":"bed-bugs","name":"Bed bug bites","cat":"inf","lvl":2,"alt":["Cimex lectularius"],"dx":[{"id":"scabies"},{"id":"chronic-urticaria"},{"id":"impetigo"}],"pearl":"Linear or clustered \"breakfast, lunch and dinner\" pruritic papules/wheals or bullae on exposed areas at night. Examine bedding; treat symptomatically and eradicate the infestation.","images":[{"u":"/assets/Uploads/640px-Bed-bug-Cimex-lectularius.jpg","cap":"Fed adult","c":"Open access image"},{"u":"/assets/Uploads/13532005812243.jpg","cap":"Unfed adult","c":"Open access image"},{"u":"/assets/collection/Bed-bug-infestation/bed-bug-infestation-0003.jpg","cap":"Bed bug bites on the calf","c":"© DermNet"},{"u":"/assets/collection/Bed-bug-infestation/bed-bug-infestation-0005.jpg","cap":"Bed bug bites on the calf","c":"© DermNet"},{"u":"/assets/collection/Bed-bug-infestation/bed-bug-infestation-0004.jpg","cap":"Bed bug bite on the calf - note the central punctum","c":"© DermNet"}]},{"id":"seborrhoeic-keratosis","name":"Seborrheic keratosis","cat":"ben","lvl":1,"alt":["Seborrhoeic keratosis"],"dx":[{"id":"melanoma"},{"id":"viral-wart"},{"id":"actinic-keratosis"},{"id":"solar-lentigo"}],"pearl":"\"Stuck-on\" waxy papules with horn cysts, comedo-like openings and fissures (dermoscopy: milia-like cysts, brain-like gyri). Sign of Leser–Trélat (sudden eruptive SKs) is associated with GI adenocarcinoma. Irritated SKs may mimic melanoma or SCC.","images":[{"u":"/assets/Uploads/lesions/bcp2.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/bcp8.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/pigmented-lesion-06.jpg","cap":"Pigmented seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/bcp1.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/seborrh-k.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/bcp4.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/bcp7.jpg","cap":"Irritated seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/lichenoid-keratosis3.jpg","cap":"Lichenoid keratosis","c":"© DermNet"}]},{"id":"dermatofibroma","name":"Dermatofibroma","cat":"ben","lvl":1,"alt":["Fibrous histiocytoma"],"dx":[{"id":"melanoma"},{"id":"dermatofibrosarcoma-protuberans"},{"id":"keloid-and-hypertrophic-scar"}],"pearl":"Firm brown nodule on the leg of a woman that dimples when pinched (dimple/Fitzpatrick sign). Dermoscopy: central white scar-like patch with a peripheral delicate pigment network. Histology: spindled fibroblasts, hyperplastic epidermis with basal pigmentation and Grenz zone; factor XIIIa positive. Multiple eruptive DFs in immunosuppression (SLE, HIV).","images":[{"u":"/assets/Uploads/lesions/dermfib3.jpg","cap":"Dermatofibroma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dermfib1.jpg","cap":"Dermatofibroma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/df6.jpg","cap":"Dermatofibroma","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/lesions/df5.jpg","cap":"Dermatofibroma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/df4.jpg","cap":"Pinch sign of dermatofibroma","c":"© DermNet"}]},{"id":"lipoma","name":"Lipoma","cat":"ben","lvl":1,"alt":[],"dx":[{"id":"epidermoid-cyst"},{"id":"vascular-malformation"},{"id":"solitary-neurofibroma"}],"pearl":"Soft, mobile, painless subcutaneous mass; multiple in familial multiple lipomatosis and Dercum disease (painful; adiposis dolorosa). Angiolipomas are tender; MEN1 and Gardner syndrome have lipomas.","images":[{"u":"/assets/collection/Lipoma/lipoma-0016.jpg","cap":"A lipoma on the shoulder","c":"© DermNet"},{"u":"/assets/collection/Spindle-cell-lipoma/spindle-cell-lipoma-0001.jpg","cap":"A spindle cell lipoma on the neck - a slowly growing benign tumour more common on the neck in older individuals","c":"© Te Whatu Ora"},{"u":"/assets/collection/Lipoma/lipoma-0001.jpg","cap":"A typical lipoma on the back","c":"© DermNet"},{"u":"/assets/collection/Lipoma/lipoma-0008.jpg","cap":"A large forehead lipoma - in this situation they are often subgaleal","c":"© Te Whatu Ora"}]},{"id":"epidermoid-cyst","name":"Epidermoid cyst","cat":"ben","lvl":1,"alt":["Epidermal inclusion cyst","Sebaceous cyst"],"dx":[{"id":"trichilemmal-cyst"},{"id":"lipoma"},{"id":"boil"},{"id":"pilomatricoma"}],"pearl":"Cyst with a central punctum filled with cheesy keratin; lined by stratified squamous epithelium with a granular layer. Inflammation when it ruptures. Multiple cysts, jaw osteomas, and desmoid tumors → Gardner syndrome (APC).","images":[{"u":"/assets/Uploads/cyst2.jpg","cap":"Epidermoid cyst","c":"© DermNet"},{"u":"/assets/Uploads/ateroma.jpg","cap":"Epidermoid cyst with an obvious punctum","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/lesions/cyst10.jpg","cap":"The contents of a s small lid epidermoid cyst incised with a green needle","c":"© DermNet"},{"u":"/assets/Uploads/lesions/cyst39.jpg","cap":"A recurrent epidermoid cyst - note the scar from a previous incomplete excision","c":"© DermNet"},{"u":"/assets/Uploads/lesions/cyst14.jpg","cap":"An inflamed cyst on the lid","c":"© DermNet"},{"u":"/assets/Uploads/lesions/cyst11.jpg","cap":"An inflamed cyst accentuating the punctum","c":"© DermNet"}]},{"id":"trichilemmal-cyst","name":"Trichilemmal (pilar) cyst","cat":"ben","lvl":1,"alt":["Pilar cyst","Wen"],"dx":[{"id":"epidermoid-cyst"},{"id":"lipoma"},{"id":"pilomatricoma"}],"pearl":"Smooth, firm, mobile scalp cysts without a punctum, often multiple and familial; lined by epithelium with trichilemmal keratinization (no granular layer) and calcification. Proliferating trichilemmal tumors can rarely become malignant.","images":[{"u":"/assets/Uploads/lesions/pilar-cyst-2.jpg","cap":"Image from Dr Calum Lyon","c":"© DermNet"},{"u":"/assets/Uploads/lesions/pilar-cyst.jpg","cap":"Pilar cysts","c":"© DermNet"},{"u":"/assets/Uploads/cyst1.jpg","cap":"Pilar cyst","c":"© DermNet"}]},{"id":"milia-images","name":"Milia","cat":"ben","lvl":1,"alt":[],"dx":[{"id":"syringoma"},{"id":"sebaceous-hyperplasia"},{"id":"molluscum-contagiosum"}],"pearl":"Tiny white keratin cysts on the face of newborns and adults. Secondary milia follow blistering diseases (epidermolysis bullosa acquisita, PCT, dystrophic EB) and burns or dermabrasion.","images":[{"u":"/assets/Uploads/lesions/milia04.jpg","cap":"Neonatal milia","c":"© DermNet"},{"u":"/assets/Uploads/lesions/milia05.jpg","cap":"Eruptive milia","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/milia10.jpg","cap":"Childhood milia","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/milia09.jpg","cap":"Milia en plaque","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/milia11.jpg","cap":"Milia en plaque","c":"© DermNet"},{"u":"/assets/Uploads/lesions/milia02.jpg","cap":"Following injury","c":"© DermNet"},{"u":"/assets/Uploads/lesions/milia06.jpg","cap":"Following bullous pemphigoid","c":"© DermNet"},{"u":"/assets/Uploads/lesions/milia07.jpg","cap":"Following bullous pemphigoid","c":"© DermNet"}]},{"id":"syringoma","name":"Syringoma","cat":"ben","lvl":2,"alt":[],"dx":[{"id":"milia-images"},{"id":"trichoepithelioma"},{"id":"xanthelasma-images"},{"id":"sebaceous-hyperplasia"}],"pearl":"Multiple small flesh-colored papules on the lower eyelids of women; benign eccrine duct tumor with \"tadpole\" comma-shaped tails. Increased in Down syndrome; eruptive variant on the trunk.","images":[{"u":"/assets/collection/Syringoma/syringoma-0001.jpg","cap":"The typical 2-3mm flesh-coloured lid and cheek papules of syringomas","c":"© Dr Lawrence Meyerson"},{"u":"/assets/Uploads/site-age-specific/s/eyelid-12.jpg","cap":"Close-up image of lid syringomas","c":"© Raimo Suhonen"},{"u":"/assets/collection/Syringoma/syringoma-0009.jpg","cap":"Symmetrical syringomas on the lids - they are larger than normal","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Syringoma/syringoma-0017.jpg","cap":"Lightly pigmented eruptive syringomas on the neck","c":"© Raimo Suhonen"}]},{"id":"trichoepithelioma","name":"Trichoepithelioma","cat":"ben","lvl":2,"alt":["Brooke–Spiegler syndrome"],"dx":[{"id":"basal-cell-carcinoma"},{"id":"syringoma"},{"text":"Angiofibroma"}],"pearl":"Multiple familial trichoepitheliomas (CYLD, Brooke–Spiegler syndrome with cylindroma and spiradenoma) occur on the nasolabial folds. Histology: papillary mesenchymal bodies, horn cysts. Mimic of BCC; immunostains (CK20 Merkel cells, PHLDA1) help.","images":[{"u":"/assets/collection/Trichoepithelioma/trichoepithelioma-0010.jpg","cap":"A solitary trichoepithelioma on the nose","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Trichoepithelioma/trichoepithelioma-0015.jpg","cap":"Multiple trichoepitheliomata — his mother and sister are similarly affected","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Trichoepithelioma/trichoepithelioma-0002.jpg","cap":"A solitary desmoplastic trichoepithelioma","c":"© DermNet"},{"u":"/assets/collection/Trichoepithelioma/trichoepithelioma-0012.jpg","cap":"Multiple familial trichoepitheliomata in skin of colour","c":"© Dr Richard Ashton"}]},{"id":"pilomatricoma","name":"Pilomatricoma","cat":"ben","lvl":2,"alt":["Calcifying epithelioma of Malherbe","Pilomatrixoma"],"dx":[{"id":"epidermoid-cyst"},{"id":"calcinosis-cutis"},{"id":"trichilemmal-cyst"}],"pearl":"Firm, calcified, \"tent sign\" nodule of the head/neck/arms in children. Beta-catenin (CTNNB1) mutation; ghost and shadow cells on histology. Multiple lesions in myotonic dystrophy and Gardner syndrome.","images":[{"u":"/assets/Uploads/lesions/pilomatricoma.jpg","cap":"Pilomatricoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/pilomatricoma2.jpg","cap":"Pilomatricoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/pilomatricoma3.jpg","cap":"Pilomatricoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/giant-pilomatricoma.jpg","cap":"Giant pilomatricoma","c":"© DermNet"},{"u":"/assets/Uploads/pilomatricoma-01.jpg","cap":"Pilomatricoma","c":"© DermNet"},{"u":"/assets/Uploads/pilomatricoma-macro.jpg","cap":"Pilomatricoma","c":"© DermNet"}]},{"id":"solitary-neurofibroma","name":"Neurofibroma","cat":"ben","lvl":1,"alt":["Solitary neurofibroma"],"dx":[{"id":"dermatofibroma"},{"id":"lipoma"},{"id":"epidermoid-cyst"}],"pearl":"Soft papule with \"buttonhole\" invagination sign. Multiple neurofibromas indicate NF1; plexiform neurofibroma is pathognomonic for NF1 and may undergo malignant transformation (MPNST). S-100 positive.","images":[{"u":"/assets/Uploads/neurofibroma-06.jpg","cap":"Solitary neurofibroma","c":"© DermNet"},{"u":"/assets/Uploads/neurofibroma-07.jpg","cap":"Solitary neurofibroma","c":"© DermNet"},{"u":"/assets/Uploads/neurofibroma-08.jpg","cap":"Solitary neurofibroma","c":"© DermNet"}]},{"id":"keloid-and-hypertrophic-scar","name":"Keloid","cat":"ben","lvl":1,"alt":["Keloid scar","Hypertrophic scar"],"dx":[{"id":"dermatofibrosarcoma-protuberans"},{"id":"dermatofibroma"},{"id":"folliculitis-keloidalis"}],"pearl":"Scar tissue extending beyond the original wound margin, unlike a hypertrophic scar, which stays within it and regresses. Common in skin of color, on earlobes, chest and shoulders. Treat with intralesional triamcinolone, silicone, cryotherapy, and excision with adjuvant radiation/steroid.","images":[{"u":"/assets/collection/Keloid-scar/keloid-scar-0003.jpg","cap":"A large keloid on the deltoid area after smallpox vaccination","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Keloid-scar/keloid-scar-0011.jpg","cap":"A large 'dumbbell' keloid on the earlobe","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Keloid-scar/keloid-scar-0017.jpg","cap":"Post-acne keloid scars","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Keloid-scar/keloid-scar-0020.jpg","cap":"Keloid scarring after skin grafting","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Keloid-scar/keloid-scar-0023.jpg","cap":"Keloids over the upper back","c":"© DermNet"}]},{"id":"skin-tag","name":"Skin tag","cat":"ben","lvl":1,"alt":["Acrochordon"],"dx":[{"id":"solitary-neurofibroma"},{"id":"viral-wart"},{"id":"seborrhoeic-keratosis"}],"pearl":"Soft, pedunculated papules in the neck, axillae and groin. Associated with obesity, diabetes, insulin resistance and acromegaly; multiple tags may be a sign of Birt–Hogg–Dubé syndrome (fibrofolliculomas).","images":[{"u":"/assets/Uploads/lesions/tag1.jpg","cap":"Skin tags","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/tag2.jpg","cap":"Skin tag","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/tag6.jpg","cap":"Skin tag","c":"© DermNet"},{"u":"/assets/Uploads/lesions/tag3.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/sebk-skintag.jpg","cap":"Seborrhoeic keratosis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/tag4.jpg","cap":"Molluscum contagiosum","c":"© DermNet"}]},{"id":"sebaceous-hyperplasia","name":"Sebaceous hyperplasia","cat":"ben","lvl":1,"alt":[],"dx":[{"id":"basal-cell-carcinoma"},{"id":"syringoma"},{"id":"molluscum-contagiosum"}],"pearl":"Yellowish papules with central umbilication and fine telangiectasia on the forehead/cheeks of older adults; crown-vessels on dermoscopy. Can mimic BCC. Cyclosporine can induce them. Muir–Torre syndrome has sebaceous neoplasms, not simple hyperplasia.","images":[{"u":"/assets/Uploads/acne/sebhpl3.jpg","cap":"Sebaceous hyperplasia","c":"© DermNet"},{"u":"/assets/Uploads/acne/s/sebhpl2.jpg","cap":"Sebaceous hyperplasia","c":"© DermNet"}]},{"id":"xanthelasma-images","name":"Xanthelasma","cat":"ben","lvl":1,"alt":["Xanthelasma palpebrarum"],"dx":[{"id":"syringoma"},{"id":"xanthoma"},{"id":"sebaceous-hyperplasia"}],"pearl":"Yellow plaques on the eyelids; half of patients have normal lipids, but check lipid panel, especially under age 40 or with PBC. Treat with TCA, laser or excision; recurrences common.","images":[{"u":"/assets/Uploads/dermal-infiltrative/s/xanthelasma01.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/s/xanthelasma02.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma03.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma04.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma05.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma06.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma07.jpg","cap":"Xanthelasma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/xanthelasma08.jpg","cap":"Xanthelasma","c":"© DermNet"}]},{"id":"xanthoma","name":"Xanthoma","cat":"gran","lvl":2,"alt":["Eruptive xanthoma","Tendinous xanthoma"],"dx":[{"id":"xanthelasma-images"},{"id":"juvenile-xanthogranuloma"},{"id":"granuloma-annulare"}],"pearl":"Eruptive: hypertriglyceridemia (type I, IV, V); tendinous (Achilles/extensor fingers): familial hypercholesterolemia (type IIa); tuberous: dysbetalipoproteinemia (type III); palmar crease: type III; planar: associated with monoclonal gammopathy. Check lipid panel and treat the metabolic cause.","images":[{"u":"/assets/Uploads/dermal-infiltrative/w/xanth-tub3.jpg","cap":"Tuberous xanthomas","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/xanth-tub1.jpg","cap":"Tuberous xanthomas","c":"© DermNet"},{"u":"/assets/Uploads/systemic/xanth-tend.jpg","cap":"Tendinous xanthoma","c":"© DermNet"},{"u":"/assets/Uploads/systemic/xantherupt3.jpg","cap":"Eruptive xanthomas","c":"© DermNet"},{"u":"/assets/Uploads/systemic/xantherupt2.jpg","cap":"Eruptive xanthomas","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/systemic/s/xantherupt.jpg","cap":"Eruptive xanthomas","c":"© DermNet"},{"u":"/assets/Uploads/systemic/tca-before.jpg","cap":"Before trichloroacetic acid treatment","c":"© DermNet"},{"u":"/assets/Uploads/systemic/tca-during.jpg","cap":"During trichloroacetic acid treatment","c":"© DermNet"}]},{"id":"juvenile-xanthogranuloma","name":"Juvenile xanthogranuloma","cat":"neo","lvl":2,"alt":["JXG"],"dx":[{"id":"xanthoma"},{"id":"mastocytosis"},{"id":"spitz-naevus"}],"pearl":"Yellow-orange dome-shaped papule in infants/young children that involutes over years. Touton giant cells, non-Langerhans histiocytes (CD68+, factor XIIIa+, S100−, CD1a−). Check for ocular (iris) involvement. NF1 + JXG → risk of juvenile myelomonocytic leukemia.","images":[{"u":"/assets/Uploads/lesions/jxg1.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/jxg4.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/jxg5.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/jxg2.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/jxg6.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/jxg3.jpg","cap":"Juvenile xanthogranuloma","c":"© DermNet"}]},{"id":"mastocytosis","name":"Cutaneous mastocytosis (urticaria pigmentosa)","cat":"neo","lvl":2,"alt":["Urticaria pigmentosa","Mastocytosis","Mastocytoma"],"dx":[{"id":"juvenile-xanthogranuloma"},{"id":"spitz-naevus"},{"id":"cafe-au-lait-macule"}],"pearl":"Brown macules/papules that urticate on stroking (Darier sign). Children: usually resolves by adolescence; adults: systemic involvement is more likely — check serum tryptase, and KIT D816V. Avoid mast cell triggers (opiates, NSAIDs, alcohol). Histology: Giemsa/toluidine blue, CD117 (c-kit).","images":[{"u":"/assets/Uploads/colour/w/mastocytosis-10.jpg","cap":"Cutaneous mastocytosis in an infant - yellow-brown macules over the chest and back. The chest lesion has urticated 5 minutes after rubbing (Darier sign)","c":"© DermNet"},{"u":"/assets/Uploads/systemic/w/mastocytosis-6.jpg","cap":"Extensive diffuse mastocytosis in an infant","c":"© DermNet"},{"u":"/assets/Uploads/colour/urt-pig1.jpg","cap":"Maculopapular cutaneous mastocytosis (urticaria pigmentosa); red-brown maculopapular lesions on the leg","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/telang5.jpg","cap":"Telangiectasia in maculopapular cutaneous mastocytosis","c":"© DermNet"},{"u":"/assets/Uploads/mastocytoma-hand.jpg","cap":"Solitary mastocytoma on a toddler’s hand","c":"© DermNet"}]},{"id":"epidermal-naevi","name":"Epidermal nevus","cat":"ben","lvl":2,"alt":["Verrucous epidermal naevus","Epidermal naevus"],"dx":[{"id":"lichen-striatus"},{"id":"seborrhoeic-keratosis"},{"id":"viral-wart"}],"pearl":"Linear verrucous plaques along Blaschko lines. Epidermal nevus syndromes with neurologic/skeletal anomalies are caused by mosaic mutations (FGFR3, PIK3CA, HRAS). ILVEN is intensely pruritic and often resistant to therapy.","images":[{"u":"/assets/Uploads/doctors/lesions/images/ep-n1.jpg","cap":"Epidermal naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ep-n4.jpg","cap":"Epidermal naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ep-n6.jpg","cap":"Epidermal naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ep-n5.jpg","cap":"Epidermal naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ep-n3.jpg","cap":"Epidermal naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ep-n2.jpg","cap":"Epidermal naevus","c":"© DermNet"}]},{"id":"sebaceous-naevus","name":"Nevus sebaceus","cat":"ben","lvl":1,"alt":["Sebaceous naevus","Organoid nevus of Jadassohn"],"dx":[{"id":"epidermal-naevi"},{"id":"congenital-melanocytic-naevi"},{"id":"aplasia-cutis"}],"pearl":"Yellow-orange hairless plaque on the scalp present at birth, becomes verrucous in puberty. HRAS/KRAS mosaicism. Secondary tumors in adulthood: usually trichoblastoma (not BCC) and syringocystadenoma papilliferum; Schimmelpenning syndrome with CNS and ocular features. Consider excision.","images":[{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0010.jpg","cap":"A hairless occipital patch in a child - the nevus sebaceous may become thicker and verrucous at puberty","c":"© DermNet"},{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0002.jpg","cap":"A nevus sebaceous on the occiput, which occasionally bleeds","c":"© DermNet"},{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0001.jpg","cap":"Nevus sebaceous, present since birth, slowly become rough and has developed a benign cyst within it","c":"© DermNet"},{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0003.jpg","cap":"Apocrine hidrocystoma developing within a sebaceous nevus on the cheek","c":"© DermNet"},{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0015.jpg","cap":"A nevus sebaceous in skin of colour - the typical yellow colour cannot be appreciated in darker skin types","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Naevus-sebaceous/naevus-sebaceous-0004.jpg","cap":"A crusted area has developed at the edge of this nevus sebaceous - biopsy is needed to exclude either a benign or malignant lesion arising within","c":"© DermNet"}]},{"id":"porokeratosis","name":"Porokeratosis","cat":"mal","lvl":2,"alt":["Porokeratosis of Mibelli","Disseminated superficial actinic porokeratosis"],"dx":[{"id":"actinic-keratosis"},{"id":"tinea-corporis"},{"id":"granuloma-annulare"}],"pearl":"Annular plaques with a raised keratotic ridge; histology shows the cornoid lamella (column of parakeratosis). Disseminated superficial actinic porokeratosis (DSAP) is most common; risk of SCC; mevalonate pathway mutations (MVK, PMVK, MVD, FDPS).","images":[{"u":"/assets/Uploads/porokeratosis-mibelli-02.jpg","cap":"Porokeratosis of Mibelli","c":"© DermNet"},{"u":"/assets/Uploads/dsap-3.jpg","cap":"DSAP","c":"© DermNet"}]},{"id":"glomus-tumour","name":"Glomus tumor","cat":"ben","lvl":3,"alt":["Glomus tumour"],"dx":[{"text":"Subungual exostosis"},{"id":"melanoma"},{"id":"leiomyoma"}],"pearl":"Triad of paroxysmal pain, pinpoint tenderness and cold sensitivity; blue-red subungual nodule. Love test and Hildreth sign. Multiple glomus tumors are inherited (glomulin) and non-painful. Surgical excision is curative.","images":[{"u":"/assets/Uploads/vascular/glomus.jpg","cap":"Glomus tumour","c":"© DermNet"},{"u":"/assets/Uploads/vascular/glomus-tumour-3.jpg","cap":"Glomus tumour","c":"© DermNet"},{"u":"/assets/Uploads/vascular/glomus-tumour-1.jpg","cap":"Glomus tumour","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/a/glomus-tumor.jpg","cap":"Glomus tumour","c":"© Dr Ph Abimelec - dermatologue"}]},{"id":"leiomyoma","name":"Cutaneous leiomyoma","cat":"ben","lvl":3,"alt":["Piloleiomyoma"],"dx":[{"id":"dermatofibroma"},{"id":"glomus-tumour"},{"id":"solitary-neurofibroma"}],"pearl":"Grouped, painful pink-brown papules that are tender with cold (arrector pili origin). Multiple lesions → Reed syndrome (hereditary leiomyomatosis and renal cell carcinoma; fumarate hydratase mutation): screen for renal cancer and uterine fibroids.","images":[{"u":"/assets/Uploads/leiomyoma-1.jpg","cap":"Leiomyoma","c":"© DermNet"},{"u":"/assets/Uploads/leiomyoma-2.jpg","cap":"Leiomyoma","c":"© DermNet"},{"u":"/assets/Uploads/leiomyoma-3.jpg","cap":"Leiomyomas","c":"© DermNet"}]},{"id":"dermatosis-papulosa-nigra","name":"Dermatosis papulosa nigra","cat":"ben","lvl":1,"alt":["DPN"],"dx":[{"id":"seborrhoeic-keratosis"},{"id":"syringoma"},{"id":"viral-wart"}],"pearl":"Multiple small, dark, smooth papules on the cheeks and temples in skin of color; histologically identical to seborrheic keratoses.","images":[{"u":"/assets/Uploads/lesions/dpn1.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dpn2.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dpn3.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dpn5.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dpn6.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"},{"u":"/assets/Uploads/lesions/dpn4.jpg","cap":"Dermatosis papulosa nigra","c":"© DermNet"}]},{"id":"actinic-keratosis","name":"Actinic keratosis","cat":"mal","lvl":1,"alt":["Solar keratosis"],"dx":[{"id":"seborrhoeic-keratosis"},{"id":"cutaneous-squamous-cell-carcinoma"},{"id":"discoid-lupus-erythematosus"},{"id":"porokeratosis"}],"pearl":"Rough, erythematous, sand-paper-like scaly macules/papules on sun-exposed skin. ~0.1–10% progress to SCC per year. Field therapy options: 5-FU, imiquimod, ingenol, tirbanibulin, PDT; liquid nitrogen for isolated lesions. Histology: atypia confined to the lower epidermis, \"flag sign\" (alternating ortho/parakeratosis), sparing of adnexa.","images":[{"u":"/assets/Uploads/lesions/ak-face/235.jpg","cap":"A pink base with a hyperkeratotic top on the nasal bridge - a common site for actinic keratoses","c":"© Raimo Suhonen"},{"u":"/assets/collection/Actinic-keratosis/actinic-keratosis-00002.jpg","cap":"An actinic keratosis on the nose","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/sk6.jpg","cap":"Field change over the forehead with multiple superficial actinic keratoses","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/sk2.jpg","cap":"Thicker actinic keratoses on the dorsal hand","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ak-face/282.jpg","cap":"Hyperkeratotic actinic keratoses on the forehead","c":"© DermNet"}]},{"id":"actinic-cheilitis","name":"Actinic cheilitis","cat":"oral","lvl":2,"alt":[],"dx":[{"text":"Oral leukoplakia"},{"id":"herpes-simplex"},{"id":"oral-lichen-planus"}],"pearl":"Scaly, atrophic lower lip with a blurred vermilion border from chronic UV exposure; precursor of SCC (lip SCC metastasizes more readily). Treat with 5-FU, cryotherapy, or vermilionectomy.","images":[{"u":"/assets/Uploads/site-age-specific/cheilitis1.jpg","cap":"Actinic cheilitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/cheilitis2.jpg","cap":"Actinic cheilitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/cheilitis3.jpg","cap":"Actinic cheilitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/cheilitis4.jpg","cap":"Actinic cheilitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/cheilitis5.jpg","cap":"Actinic cheilitis","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/cheilitis6.jpg","cap":"Actinic cheilitis","c":"© DermNet"}]},{"id":"cutaneous-squamous-cell-carcinoma","name":"Squamous cell carcinoma","cat":"mal","lvl":1,"alt":["SCC","Cutaneous SCC"],"dx":[{"id":"keratoacanthoma"},{"id":"actinic-keratosis"},{"id":"viral-wart"},{"id":"basal-cell-carcinoma"}],"pearl":"Firm, keratotic, ulcerated nodule on a sun-exposed site. High-risk features: diameter >2 cm, thickness >2 mm (NCCN) or >6 mm (AJCC), poor differentiation, perineural invasion, ear/lip/genital location, immunosuppression, and arising in scars or chronic wounds (Marjolin ulcer). Mohs for high-risk sites. Cemiplimab is for advanced disease. Transplant recipients have 65–250× SCC risk (voriconazole and hydrochlorothiazide add risk).","images":[{"u":"/assets/Uploads/lesions/scc2.jpg","cap":"Squamous cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/scc8.jpg","cap":"Squamous cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/scc9.jpg","cap":"Squamous cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/scc-104.jpg","cap":"High-risk cutaneous squamous cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/scc-105.jpg","cap":"High-risk cutaneous squamous cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/scc-106.jpg","cap":"High-risk cutaneous squamous cell carcinoma","c":"© Te Whatu Ora"}]},{"id":"keratoacanthoma","name":"Keratoacanthoma","cat":"mal","lvl":2,"alt":[],"dx":[{"id":"cutaneous-squamous-cell-carcinoma"},{"id":"viral-wart"},{"id":"molluscum-contagiosum"}],"pearl":"Rapidly growing dome-shaped nodule with a central keratin plug, regressing over months. Considered a well-differentiated SCC variant; treat as SCC. Multiple KAs: Ferguson–Smith (TGFBR1), Grzybowski, Muir–Torre; BRAF inhibitors (vemurafenib) induce KAs/SCC.","images":[{"u":"/assets/Uploads/lesions/keratoacanthoma/2991.jpg","cap":"Keratoacanthoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/keratoacanthoma/3003.jpg","cap":"Keratoacanthoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/keratoacanthoma/2997.jpg","cap":"Keratoacanthoma","c":"© DermNet"}]},{"id":"basal-cell-carcinoma","name":"Basal cell carcinoma","cat":"mal","lvl":1,"alt":["BCC"],"dx":[{"id":"sebaceous-hyperplasia"},{"id":"molluscum-contagiosum"},{"id":"melanoma"},{"id":"trichoepithelioma"}],"pearl":"Pearly papule with rolled borders and arborizing telangiectasias. Subtypes: nodular, superficial, morpheaform/infiltrative (high risk; scar-like), pigmented, micronodular, basosquamous. Dermoscopy: arborizing vessels, blue-gray ovoid nests, leaf-like areas, ulceration. Histology: peripheral palisading, retraction clefts, mucin. PTCH1/hedgehog pathway (vismodegib, sonidegib). Mohs for H-zone lesions.","images":[{"u":"/assets/Uploads/lesions/bcc1.jpg","cap":"Nodular basal cell carcinoma","c":"© DermNet"},{"u":"/assets/collection/Basal-cell-carcinoma/basal-cell-carcinoma-0019.jpg","cap":"Nodular basal cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/bcc-104.jpg","cap":"Nodular basal cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/bcc-105.jpg","cap":"Nodular basal cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/bcc3.jpg","cap":"Basal cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/bcc-100.jpg","cap":"Superficial basal cell carcinoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/bcc-101.jpg","cap":"Superficial basal cell carcinoma, face","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/bcc-102.jpg","cap":"Superficial basal cell carcinoma, back","c":"© Te Whatu Ora"}]},{"id":"merkel-cell-carcinoma","name":"Merkel cell carcinoma","cat":"mal","lvl":2,"alt":["MCC"],"dx":[{"id":"basal-cell-carcinoma"},{"id":"pyogenic-granuloma"},{"id":"epidermoid-cyst"},{"id":"cutaneous-squamous-cell-carcinoma"}],"pearl":"AEIOU: Asymptomatic, Expanding rapidly, Immune suppression, Older than 50, UV-exposed site; red-violet nodule. Merkel cell polyomavirus is found in ~80%. CK20 perinuclear dot-like staining, TTF-1 negative (vs small-cell lung cancer), neuroendocrine markers. Sentinel node biopsy; PD-1 (avelumab, pembrolizumab, retifanlimab).","images":[{"u":"/assets/Uploads/lesions/mcc.jpg","cap":"Image supplied by Bob Rossborough","c":"© DermNet"},{"u":"/assets/Uploads/lesions/mcc2.jpg","cap":"Image supplied by Catherine Skiens","c":"© DermNet"},{"u":"/assets/Uploads/lesions/eyelid-merkel-1.jpg","cap":"Merkel cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/mcc3.jpg","cap":"Merkel cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/mcc4.jpg","cap":"Image supplied by Dr Slavko Doslo","c":"© DermNet"},{"u":"/assets/Uploads/lesions/eyelid-merkel-2.jpg","cap":"Also, lower lid","c":"© DermNet"}]},{"id":"mycosis-fungoides","name":"Mycosis fungoides","cat":"mal","lvl":2,"alt":["MF","Cutaneous T-cell lymphoma"],"dx":[{"id":"chronic-plaque-psoriasis"},{"id":"discoid-eczema"},{"id":"atopic-dermatitis"},{"id":"tinea-corporis"}],"pearl":"Patch, plaque, tumor stages; \"bathing-trunk\" distribution with poikiloderma; CD4+ T cells. Histology: epidermotropism, Pautrier microabscesses, haloed lymphocytes. Folliculotropic MF has a worse prognosis. Treat with topical steroids, phototherapy, bexarotene, mechlorethamine. Large-cell transformation is a poor prognosticator.","images":[{"u":"/assets/Uploads/dermal-infiltrative/s/ctcl6.jpg","cap":"Patches and plaques of mycosis fungoides","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/mycosis-fungoides-plaque-05.jpg","cap":"Plaque stage mycosis fungoides","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/mycosis-fungoides-2.jpg","cap":"Patch stage mycosis fungoides","c":"© DermNet"},{"u":"/assets/Uploads/mycosis-fungoides-3.jpg","cap":"Patch stage mycosis fungoides","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ctcl8.jpg","cap":"Mycosis fungoides","c":"© DermNet"},{"u":"/assets/Uploads/mycosis-fungoides-plaque-19.jpg","cap":"Plaque stage mycosis fungoides","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/mycosis-fungoides-plaque-08.jpg","cap":"Plaque stage mycosis fungoides","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/mycosis-fungoides-12.jpg","cap":"Plaque stage mycosis fungoides","c":"© Te Whatu Ora"}]},{"id":"sezary-syndrome","name":"Sézary syndrome","cat":"mal","lvl":3,"alt":["Sezary syndrome"],"dx":[{"id":"erythroderma"},{"id":"mycosis-fungoides"},{"id":"pityriasis-rubra-pilaris"}],"pearl":"Erythroderma, lymphadenopathy and ≥1000/µL circulating Sézary cells (cerebriform nuclei); CD4+ and CD7−/CD26− T cells. Mogamulizumab (anti-CCR4) and extracorporeal photopheresis are used.","images":[{"u":"/assets/Uploads/dermal-infiltrative/sezary-1.jpg","cap":"Sézary syndrome","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ctcl10.jpg","cap":"Sézary syndrome","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/sezary-4.jpg","cap":"Sézary syndrome","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ctcl4.jpg","cap":"Erythroderma","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/sezary-3.jpg","cap":"Nail change","c":"© DermNet"},{"u":"/assets/Uploads/sezary-19.jpg","cap":"Plantar keratoderma","c":"© DermNet"}]},{"id":"extramammary-paget-disease","name":"Extramammary Paget disease","cat":"mal","lvl":3,"alt":[],"dx":[{"id":"tinea-cruris"},{"id":"candida"},{"id":"lichen-sclerosus"}],"pearl":"Persistent, red, eroded plaque on the vulva/perianal skin of an older patient, unresponsive to steroids or antifungals. Paget cells stain CK7+, CAM5.2, mucicarmine+ and CEA+. Evaluate for underlying GI/GU malignancy (colorectal for perianal; bladder for genital); mammary Paget disease is almost always associated with underlying breast carcinoma.","images":[{"u":"/assets/Uploads/extra-paget-12.jpg","cap":"Extramammary Paget disease of the skin of the vulva","c":"© DermNet"},{"u":"/assets/Uploads/extra-paget-28.jpg","cap":"Perianal extramammary Paget disease of the skin","c":"© DermNet"},{"u":"/assets/Uploads/extra-paget-04.jpg","cap":"Extramammary Paget disease of the skin of the axilla","c":"© DermNet"}]},{"id":"atypical-fibroxanthoma","name":"Atypical fibroxanthoma","cat":"mal","lvl":3,"alt":["AFX"],"dx":[{"id":"cutaneous-squamous-cell-carcinoma"},{"id":"pyogenic-granuloma"},{"id":"basal-cell-carcinoma"}],"pearl":"Rapidly growing eroded nodule on the sun-damaged head of an elderly man; pleomorphic spindle cells, CD10+, CD68+, negative for S100, CK, desmin. Considered a superficial variant of undifferentiated pleomorphic sarcoma. Mohs is the treatment.","images":[{"u":"/assets/Uploads/lesions/afx.jpg","cap":"Atypical fibroxanthoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/afx4.jpg","cap":"Atypical fibroxanthoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/atypical-fibroxanthoma.jpg","cap":"Atypical fibroxanthoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/atypical-fibroxanthoma.jpg","cap":"Atypical fibroxanthoma","c":"© DermNet"},{"u":"/assets/Uploads/atypical-fibroxanthoma-01-v3.jpg","cap":"Atypical fibroxanthoma","c":"© DermNet"},{"u":"/assets/Uploads/atypical-fibroxanthoma-dermoscopy-01-v3.jpg","cap":"Atypical fibroxanthoma","c":"© DermNet"}]},{"id":"dermatofibrosarcoma-protuberans","name":"Dermatofibrosarcoma protuberans","cat":"mal","lvl":2,"alt":["DFSP"],"dx":[{"id":"dermatofibroma"},{"id":"keloid-and-hypertrophic-scar"},{"id":"morphoea"}],"pearl":"Indurated plaque on the trunk of a young adult that slowly enlarges and becomes nodular. t(17;22) COL1A1–PDGFB; CD34+, factor XIIIa−; honeycomb/storiform infiltrate of subcutaneous fat. Local recurrence is common, so Mohs/WLE; imatinib for unresectable disease. Fibrosarcomatous transformation increases metastatic risk.","images":[{"u":"/assets/Uploads/dfsp-1.jpg","cap":"Lesion in 2014","c":"© DermNet"},{"u":"/assets/Uploads/dfsp-2.jpg","cap":"Same lesion in 2015","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/dfs.jpg","cap":"Another example","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/lesions/dfsp.jpg","cap":"Dermatofibrosarcoma protuberans","c":"© DermNet"},{"u":"/assets/Uploads/dfsp-001.jpg","cap":"Dermatofibrosarcoma protuberans","c":"© DermNet"}]},{"id":"sebaceous-carcinoma","name":"Sebaceous carcinoma","cat":"mal","lvl":3,"alt":[],"dx":[{"text":"Chalazion"},{"id":"basal-cell-carcinoma"},{"text":"Blepharitis"}],"pearl":"Firm yellowish nodule of the eyelid (Meibomian glands), mimicking recurrent chalazion or blepharitis; pagetoid spread. Muir–Torre syndrome (sebaceous neoplasms + visceral cancer, MSH2/MLH1 mismatch repair loss): check immunostains. Lymph node spread is common.","images":[{"u":"/assets/Uploads/lesions/sebaceous-ca-1.jpg","cap":"Sebaceous carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/sebaceous-ca-2.jpg","cap":"Sebaceous carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/lesions/sebaceous-ca-3.jpg","cap":"Sebaceous carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/sebaceous-carcinoma-01.jpg","cap":"Clinical view","c":"© DermNet"}]},{"id":"lymphomatoid-papulosis","name":"Lymphomatoid papulosis","cat":"mal","lvl":3,"alt":["LyP"],"dx":[{"id":"pityriasis-lichenoides"},{"text":"Insect bites"},{"id":"chickenpox"}],"pearl":"Recurrent self-healing papulonodules in crops; CD30+ T-cell proliferation. Histologic types A–F (type A: Reed–Sternberg–like cells). Excellent prognosis, but ~10–20% develop a second lymphoma (mycosis fungoides, primary cutaneous anaplastic large cell lymphoma, Hodgkin).","images":[{"u":"/assets/collection-O/Lymphomatoid-papulosis-Dr-J-Wells/lymphomatoid-papulosis-very-low-res-00011.jpg","cap":"Lymphomatoid papulosis","c":"© DermNet"},{"u":"/assets/Uploads/lymphomatoid-papulosis-typeE.jpg","cap":"Lymphomatoid papulosis type E","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/lymph-pap1.jpg","cap":"Lymphomatoid papulosis","c":"© DermNet"},{"u":"/assets/collection-O/Lymphomatoid-papulosis-Dr-J-Wells/lymphomatoid-papulosis-very-low-res-00008.jpg","cap":"Lymphomatoid papulosis","c":"© DermNet"},{"u":"/assets/collection-O/Lymphomatoid-papulosis-Dr-J-Wells/lymphomatoid-papulosis-very-low-res-00009.jpg","cap":"Lymphomatoid papulosis","c":"© DermNet"},{"u":"/assets/collection-O/Lymphomatoid-papulosis-Dr-J-Wells/lymphomatoid-papulosis-very-low-res-00010.jpg","cap":"Lymphomatoid papulosis","c":"© DermNet"}]},{"id":"langerhans-cell-histiocytosis","name":"Langerhans cell histiocytosis","cat":"neo","lvl":3,"alt":["LCH","Letterer–Siwe disease"],"dx":[{"id":"seborrhoeic-dermatitis"},{"id":"scabies"},{"id":"candida"}],"pearl":"Hemorrhagic, crusted seborrhea-like papules in skin folds and the scalp of infants; Langerhans cells are CD1a+, S100+, langerin (CD207)+ with Birbeck granules on EM; BRAF V600E in many. Lytic bone lesions, diabetes insipidus, and organ involvement (Letterer–Siwe).","images":[{"u":"/assets/Uploads/dermal-infiltrative/langerhans.jpg","cap":"Histiocytosis","c":"© DermNet"},{"u":"/assets/Uploads/langerhans-histiocytosis.jpg","cap":"Langerhans histiocytosis","c":"© DermNet"},{"u":"/assets/Uploads/LCH-2.jpg","cap":"Langerhans cell histiocytosis","c":"© DermNet"}]},{"id":"melanoma","name":"Melanoma","cat":"mel","lvl":1,"alt":["Superficial spreading melanoma","Malignant melanoma"],"dx":[{"id":"seborrhoeic-keratosis"},{"text":"Dysplastic naevus"},{"text":"Pigmented basal cell"},{"id":"blue-naevus"}],"pearl":"ABCDEs; \"ugly duckling\" sign. Superficial spreading is the most common; Breslow thickness is the most important prognostic factor; stage I-II surgery with margins (0.5 cm in situ, 1 cm ≤1 mm, 1–2 cm 1–2 mm, 2 cm >2 mm); sentinel node biopsy ≥0.8 mm or ulcerated. Adjuvant anti-PD-1 and BRAF/MEK inhibitors (BRAF V600E). Dermoscopy: atypical network, blue-white veil, irregular streaks, regression structures.","images":[{"u":"/assets/manualthumbnails/lesions/img/mel4-sm.jpg","cap":"Superficial spreading malignant melanoma - irregular border, variable pigmentation, and areas of clinical regression","c":"© DermNet"},{"u":"/assets/manualthumbnails/doctors/dermoscopy-course/images/mel-irreg2-sm.jpg","cap":"Superficial spreading malignant melanoma - an enlarging pigmented lesion with variable pigmentation, irregular edge, and asymmetry","c":"© DermNet"},{"u":"/assets/Uploads/melanoma-abcds-23.jpg","cap":"Nodular malignant melanoma in a vertical growth phase - rapidly enlarging scaly pigmented nodule","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/12-pubic-melanoma-m.jpg","cap":"A superficial malignant melanoma - irregular and notched margin, variable and irregular pigmentation in an itchy and enlarging pigmented lesion","c":"© DermNet"}]},{"id":"lentigo-maligna-and-lentigo-maligna-melanoma","name":"Lentigo maligna","cat":"mel","lvl":2,"alt":["Lentigo maligna melanoma","LMM","Hutchinson melanotic freckle"],"dx":[{"id":"solar-lentigo"},{"id":"seborrhoeic-keratosis"},{"id":"actinic-keratosis"}],"pearl":"Slowly growing, irregular brown macule on the chronically sun-damaged face of an older adult (melanoma in situ); becomes LMM when invasive. Dermoscopy: annular-granular pattern, rhomboidal structures, asymmetric pigmented follicular openings. Imiquimod is an option when surgery is not feasible.","images":[{"u":"/assets/Uploads/lesions/w/lm1.jpg","cap":"Lentigo maligna","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/lm3.jpg","cap":"Lentigo maligna","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/lm6.jpg","cap":"Lentigo maligna","c":"© DermNet"},{"u":"/assets/Uploads/lesions/w/lm2.jpg","cap":"Lentigo maligna","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/lm4.jpg","cap":"Lentigo maligna","c":"© DermNet"},{"u":"/assets/Uploads/lesions/lm5.jpg","cap":"Lentigo maligna","c":"© DermNet"}]},{"id":"acral-lentiginous-melanoma","name":"Acral lentiginous melanoma","cat":"mel","lvl":2,"alt":["Acral melanoma"],"dx":[{"id":"subungual-haemorrhage"},{"id":"viral-wart"},{"id":"melanonychia"},{"text":"Melanocytic naevus"}],"pearl":"Most common type in Black, Asian and Hispanic patients; palms, soles and nail unit. Dermoscopy: parallel ridge pattern (melanoma) vs parallel furrow (benign naevus). Hutchinson sign (periungual pigmentation) in subungual melanoma. KIT mutations more frequent; worse prognosis due to late diagnosis. Biopsy any longitudinal melanonychia >3 mm that is widening or with Hutchinson sign.","images":[{"u":"/assets/Uploads/acral-lentiginous-melanoma-3.jpg","cap":"Slowly enlarging irregularly pigmented lesion on the heel present for 3 years","c":"© DermNet"},{"u":"/assets/Uploads/melanoma-143.jpg","cap":"Slowly enlarging, irregularly pigmented, and marginated lesion showing central hypopigmentation and regression - an acral lentiginous melanoma","c":"© DermNet"},{"u":"/assets/Uploads/acral-lentiginous-melanoma-2-v2.jpg","cap":"acral lentiginous melanoma 2 v2","c":"© DermNet"},{"u":"/assets/Uploads/Acral-lentiginous-melanoma-3-v2.jpg","cap":"Irregular margin and pigmentation of an acral lentiginous melanoma","c":"© DermNet"},{"u":"/assets/Uploads/alm2.jpg","cap":"Irregular margin and pigmentation of an acral lentiginous melanoma","c":"© DermNet"}]},{"id":"nodular-melanoma","name":"Nodular melanoma","cat":"mel","lvl":2,"alt":[],"dx":[{"id":"pyogenic-granuloma"},{"id":"seborrhoeic-keratosis"},{"id":"basal-cell-carcinoma"}],"pearl":"Rapidly growing symmetric dark, blue-black or amelanotic papule/nodule with vertical growth phase from the start; accounts for a disproportionate share of melanoma deaths. Consider \"EFG\": Elevated, Firm, Growing for >1 month.","images":[{"u":"/assets/Uploads/lesions/w/nm1.jpg","cap":"Nodular melanoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/nm2.jpg","cap":"Nodular melanoma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/w/nm3.jpg","cap":"Nodular melanoma","c":"© Te Whatu Ora"}]},{"id":"amelanotic-melanoma","name":"Amelanotic melanoma","cat":"mel","lvl":3,"alt":[],"dx":[{"id":"pyogenic-granuloma"},{"id":"basal-cell-carcinoma"},{"id":"cutaneous-squamous-cell-carcinoma"}],"pearl":"Pink or red lesion lacking pigment; dermoscopy shows polymorphous vessels (dotted, linear irregular), milky-red areas. Frequently misdiagnosed and diagnosed late.","images":[{"u":"/assets/Uploads/amelanotic-melanoma.jpg","cap":"Nodular melanoma","c":"© DermNet"},{"u":"/assets/Uploads/amelanotic-nail-melanoma.jpg","cap":"Ungual melanoma","c":"© DermNet"},{"u":"/assets/Uploads/amelanotic-melanoma-3mm.jpg","cap":"Amelanotic melanoma 3mm","c":"© Torbay Skin"},{"u":"/assets/Uploads/amelanotic-melanoma-2m.jpg","cap":"Amelanotic superficial spreading melanoma in situ","c":"© DermNet"},{"u":"/assets/Uploads/12a-amelanotic-melanoma.jpg","cap":"Amelanotic nodular melanoma","c":"© DermNet"},{"u":"/assets/Uploads/amelanotic-melanoma-m.jpg","cap":"Amelanotic nodular melanoma","c":"© DermNet"},{"u":"/assets/Uploads/nodulocystic-bcc.jpg","cap":"Nodulocystic basal cell carcinoma","c":"© DermNet"},{"u":"/assets/Uploads/melanocytic-naevus-019.jpg","cap":"Spitz naevus","c":"© DermNet"}]},{"id":"spitz-naevus","name":"Spitz nevus","cat":"mel","lvl":2,"alt":["Spitz naevus"],"dx":[{"id":"melanoma"},{"id":"mastocytosis"},{"id":"juvenile-xanthogranuloma"},{"id":"pyogenic-granuloma"}],"pearl":"Rapidly growing pink to red-brown dome-shaped papule in a child; epithelioid and spindle melanocytes with Kamino bodies. Dermoscopy: starburst or globular pattern. Reed nevus is pigmented (black) and flat. HRAS mutations in some; atypical Spitz tumors are managed by excision; in adults treat as suspicious.","images":[{"u":"/assets/Uploads/classic-spitz1.jpg","cap":"Classic Spitz naevus","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/bml-s2.jpg","cap":"Pigmented Spitz naevus","c":"© DermNet"},{"u":"/assets/Uploads/doctors/lesions/images/bml-r2.jpg","cap":"Spindle cell tumour of Reed","c":"© DermNet"}]},{"id":"congenital-melanocytic-naevi","name":"Congenital melanocytic nevus","cat":"mel","lvl":2,"alt":["Congenital nevus","Giant congenital nevus"],"dx":[{"id":"sebaceous-naevus"},{"id":"becker-naevus"},{"id":"cafe-au-lait-macule"},{"id":"melanoma"}],"pearl":"Giant (>20 cm projected adult size) lesions carry melanoma risk (in the CNS, too) and neurocutaneous melanosis; MRI in infancy for lesions in a central distribution with satellites. NRAS mutation (BRAF V600E in small CMN). Satellite nevi number is key.","images":[{"u":"/assets/Uploads/hair-nails-sweat/naevoid-ht2.jpg","cap":"Congenital naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/cong-naevus1.jpg","cap":"Congenital naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/cong-naevus6.jpg","cap":"Congenital naevus","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/lesions/cong-naevus2.jpg","cap":"Congenital naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/calm.jpg","cap":"Congenital naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/speckled.jpg","cap":"Congenital naevus","c":"© DermNet"},{"u":"/assets/Uploads/kissing-naevus-1.jpg","cap":"Kissing naevus","c":"© DermNet"},{"u":"/assets/Uploads/kissing-naevus-2.jpg","cap":"Kissing naevus","c":"© DermNet"}]},{"id":"blue-naevus","name":"Blue nevus","cat":"mel","lvl":2,"alt":["Blue naevus"],"dx":[{"id":"melanoma"},{"id":"venous-lake"},{"id":"naevus-of-ota-ito-hori"}],"pearl":"Dermal melanocytes in a deep location cause a blue color (Tyndall effect); GNAQ/GNA11. Common type is a small dome-shaped blue-black papule; cellular type is on the buttocks/sacral area and is larger. Malignant blue nevus is rare.","images":[{"u":"/assets/Uploads/lesions/blue1.jpg","cap":"A blue naevus - the monochrome slate blue colour is typical","c":"© DermNet"},{"u":"/assets/Uploads/lesions/blue3.jpg","cap":"Blue naevi on the arm and nose","c":"© DermNet"},{"u":"/assets/collection/Blue-naevus/blue-naevus-0033.jpg","cap":"A blue naevus on the hand","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/lesions/blue5.jpg","cap":"Blue naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/blue6.jpg","cap":"Blue naevus","c":"© DermNet"}]},{"id":"halo-naevus","name":"Halo nevus","cat":"mel","lvl":1,"alt":["Sutton nevus","Halo naevus"],"dx":[{"id":"vitiligo"},{"id":"melanoma"},{"text":"Dysplastic naevus"}],"pearl":"Melanocytic nevus surrounded by a depigmented halo from a T-cell mediated attack; common in adolescents. Associated with vitiligo; the central naevus often regresses. Examine the rest of the skin (and the patient's eyes) for melanoma, especially if the central naevus is atypical.","images":[{"u":"/assets/Uploads/halo-naevus-02.jpg","cap":"Halo naevus","c":"© DermNet"},{"u":"/assets/Uploads/halo-naevus-06.jpg","cap":"Halo naevus","c":"© DermNet"},{"u":"/assets/Uploads/lesions/halo4.jpg","cap":"Stage 1","c":"© DermNet"},{"u":"/assets/Uploads/lesions/halo2.jpg","cap":"Stage 2","c":"© DermNet"},{"u":"/assets/Uploads/lesions/halo3.jpg","cap":"Stage 3","c":"© DermNet"},{"u":"/assets/Uploads/atypical-naevus-11.jpg","cap":"Atypical naevus with depigmentation","c":"© DermNet"},{"u":"/assets/Uploads/halo-melanoma-07.jpg","cap":"Melanoma with depigmentation","c":"© DermNet"}]},{"id":"lumbosacral-dermal-melanocytosis","name":"Mongolian spot","cat":"neo","lvl":1,"alt":["Dermal melanocytosis","Congenital dermal melanocytosis","Slate-gray macules"],"dx":[{"id":"blue-naevus"},{"id":"naevus-of-ota-ito-hori"},{"text":"Bruise"}],"pearl":"Blue-gray macule on the sacrum/buttocks of infants (more frequent in Asian, Black and Hispanic infants) that fades by age ~4–6. Document at the newborn visit to prevent confusion with abuse. Extensive or persistent patches may rarely be associated with lysosomal storage disorders.","images":[{"u":"/assets/Uploads/lesions/mong.jpg","cap":"Lumbosacral dermal melanocytosis. Mongolian spot","c":"© DermNet"},{"u":"/assets/Uploads/lesions/mong2.jpg","cap":"Mongolian spot Lumbosacral dermal melanocytosis. Mongolian spots. Lumbosacral dermal melanocytosis. Mongolian spots","c":"© DermNet"}]},{"id":"naevus-of-ota-ito-hori","name":"Nevus of Ota","cat":"mel","lvl":2,"alt":["Naevus of Ota","Oculodermal melanocytosis","Nevus of Ito"],"dx":[{"id":"blue-naevus"},{"id":"melasma"},{"id":"lumbosacral-dermal-melanocytosis"}],"pearl":"Blue-gray patch in the V1/V2 distribution with scleral involvement; GNAQ/GNA11. Risks: glaucoma and uveal melanoma — annual ophthalmology exam. Q-switched laser is first-line. Nevus of Ito: shoulder/supraclavicular.","images":[{"u":"/assets/Uploads/lesions/ota2.jpg","cap":"Naevus of Ota","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ota.jpg","cap":"Naevus of Ota","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ota3.jpg","cap":"Naevus of Ota","c":"© DermNet"},{"u":"/assets/Uploads/lesions/ito.jpg","cap":"Naevus of Ito","c":"© DermNet"},{"u":"/assets/Uploads/lesions/melanocytosis-ito.jpg","cap":"Naevus of Ito","c":"© DermNet"}]},{"id":"becker-naevus","name":"Becker nevus","cat":"mel","lvl":2,"alt":["Becker naevus"],"dx":[{"id":"congenital-melanocytic-naevi"},{"id":"cafe-au-lait-macule"},{"id":"melasma"}],"pearl":"Unilateral hyperpigmented patch with hypertrichosis on the shoulder/upper trunk of a young man after sun exposure; androgen receptor-dependent smooth-muscle hamartoma; may be part of Becker nevus syndrome (ipsilateral breast hypoplasia).","images":[{"u":"/assets/collection/Becker-naevus/becker-naevus-0001.jpg","cap":"Hyperpigmentation and hypertrichosis over the chest in Becker naevus","c":"© DermNet"},{"u":"/assets/collection/Becker-naevus/becker-naevus-0010.jpg","cap":"Pigmentation and hypertrichosis in Becker naevus","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Becker-naevus/becker-naevus-0018.jpg","cap":"Close-up of Becker naevus showing pigmentation and hypertrichosis","c":"© Te Whatu Ora"}]},{"id":"melanonychia","name":"Longitudinal melanonychia","cat":"nail","lvl":2,"alt":["Melanonychia"],"dx":[{"id":"acral-lentiginous-melanoma"},{"id":"subungual-haemorrhage"},{"id":"fungal-nail-infections"}],"pearl":"Brown-black band in the nail plate from melanocyte activation or hyperplasia. In children, usually benign naevus. Adult single-digit band, broad (>3 mm), pigment extending to the proximal nail fold (Hutchinson sign), or acquiring change → biopsy of nail matrix. Multiple bands in dark skin are physiologic.","images":[{"u":"/assets/Uploads/hair-nails-sweat/melanonychia-06.jpg","cap":"Melanonychia","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/hair-nails-sweat/melanonychia-09.jpg","cap":"Melanonychia","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/melanonychia-19.jpg","cap":"Melanonychia","c":"© DermNet"}]},{"id":"vitiligo","name":"Vitiligo","cat":"pig","lvl":1,"alt":[],"dx":[{"id":"pityriasis-alba"},{"id":"pityriasis-versicolor"},{"id":"piebaldism"},{"id":"idiopathic-guttate-hypomelanosis"}],"pearl":"Acquired, well-demarcated depigmented macules, chalk-white on Wood lamp; Koebner. Autoimmune with associations (thyroid disease, alopecia areata, pernicious anemia, Addison). Leukotrichia suggests refractory disease. Treatments: NB-UVB, topical calcineurin inhibitors/steroids, topical ruxolitinib (JAK), surgical grafting for stable disease.","images":[{"u":"/assets/collection/Vitiligo/vitiligo-0034.jpg","cap":"Vitiligo over the knuckles - keobnerisation due to trauma often localises vitiligo","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Vitiligo/vitiligo-0008.jpg","cap":"Symmetrical wrist vitiligo - a common location","c":"© DermNet"},{"u":"/assets/collection/Vitiligo/vitiligo-0003.jpg","cap":"Vitiligo over the back and elbows","c":"© DermNet"},{"u":"/assets/collection/Vitiligo/vitiligo-0001.jpg","cap":"Vitiligo on the lid with poliosis of the lashes","c":"© Raimo Suhonen"},{"u":"/assets/collection/Vitiligo/vitiligo-0019.jpg","cap":"Vitiligo on the lips","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Vitiligo/vitiligo-0002.jpg","cap":"Follicular repigmentation in a patch of vitiligo","c":"© Te Whatu Ora"},{"u":"/assets/collection/Vitiligo/vitiligo-0029.jpg","cap":"Extensive symmetrical facial vitiligo","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Vitiligo/vitiligo-0015.jpg","cap":"Vitiligo around the hairline of a Samoan woman","c":"© Te Whatu Ora"}]},{"id":"melasma","name":"Melasma","cat":"pig","lvl":1,"alt":["Chloasma"],"dx":[{"id":"postinflammatory-hyperpigmentation"},{"id":"naevus-of-ota-ito-hori"},{"id":"acanthosis-nigricans"}],"pearl":"Symmetric brown facial patches (malar, centrofacial, mandibular) in women of skin of color, driven by UV, visible light, hormones (pregnancy, OCPs). Wood lamp separates epidermal (accentuated) from dermal. Sun protection including visible light-blocking (iron oxides) is crucial; hydroquinone, tranexamic acid.","images":[{"u":"/assets/Uploads/colour/melasma/3144.jpg","cap":"Melasma","c":"© DermNet"},{"u":"/assets/Uploads/colour/melasma/3151.jpg","cap":"Melasma","c":"© DermNet"},{"u":"/assets/Uploads/colour/melasma/3140.jpg","cap":"Melasma","c":"© DermNet"},{"u":"/assets/Uploads/colour/melasma/3132.jpg","cap":"Melasma","c":"© DermNet"},{"u":"/assets/Uploads/colour/chloas1.jpg","cap":"Melasma","c":"© DermNet"},{"u":"/assets/Uploads/colour/chloas3.jpg","cap":"Melasma","c":"© DermNet"}]},{"id":"postinflammatory-hyperpigmentation","name":"Post-inflammatory hyperpigmentation","cat":"pig","lvl":1,"alt":["PIH"],"dx":[{"id":"melasma"},{"id":"fixed-drug-eruption"},{"id":"lichen-planus"}],"pearl":"Dark macules at sites of prior inflammation (acne, eczema, lichen planus), more severe in Fitzpatrick IV–VI. Treat the underlying disease, strictly protect from sun, and use hydroquinone, azelaic acid, retinoids. Lichen planus pigmentosus is a more persistent form.","images":[{"u":"/assets/Uploads/colour/postinflamm2.jpg","cap":"Lichen planus actinicus","c":"© DermNet"},{"u":"/assets/Uploads/colour/s/postinflamm4.jpg","cap":"Violin playing (friction)","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/colour/postinflamm5.jpg","cap":"Irritant dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/colour/hyperpig4.jpg","cap":"Postinflammatory hyperpigmentation (inflamed cyst)","c":"© DermNet"},{"u":"/assets/Uploads/colour/oven-burn.jpg","cap":"Oven burn","c":"© DermNet"},{"u":"/assets/Uploads/colour/postinflamm3.jpg","cap":"Photodynamic therapy","c":"© DermNet"},{"u":"/assets/Uploads/colour/postinflamm6.jpg","cap":"Flagellate reaction to bleomycin","c":"© DermNet"},{"u":"/assets/Uploads/colour/w/pih-eczema.jpg","cap":"Healed eczema","c":"© DermNet"}]},{"id":"solar-lentigo","name":"Solar lentigo","cat":"pig","lvl":1,"alt":["Age spot","Liver spot"],"dx":[{"id":"lentigo-maligna-and-lentigo-maligna-melanoma"},{"id":"seborrhoeic-keratosis"},{"id":"melasma"}],"pearl":"Well-demarcated uniform tan-brown macules on sun-exposed skin; elongated rete ridges with basal hyperpigmentation, no melanocytic hyperplasia. Can evolve into reticulated SK. PUVA lentigines are a marker of cumulative UV.","images":[{"u":"/assets/Uploads/lesions/s/lentigo02.jpg","cap":"A solar lentigo on the nose — it is regularly pigmented and macular, with a regular border","c":"© DermNet"},{"u":"/assets/Uploads/lesions/lentigo22.jpg","cap":"A solar lentigo on the cheek","c":"© DermNet"},{"u":"/assets/Uploads/lesions/s/solar-lentigo-01.jpg","cap":"Multiple solar lentigines on the back of the hand","c":"© DermNet"}]},{"id":"cafe-au-lait-macule","name":"Café-au-lait macule","cat":"pig","lvl":1,"alt":["Cafe au lait macule","CALM"],"dx":[{"id":"becker-naevus"},{"id":"mastocytosis"},{"text":"Melanocytic naevus"}],"pearl":"≥6 CALMs >5 mm (prepubertal) / >15 mm (postpubertal) is a criterion for NF1 (with axillary freckling [Crowe sign], neurofibromas, Lisch nodules, optic glioma, sphenoid dysplasia). \"Coast of California\" smooth border = NF1; \"coast of Maine\" irregular border = McCune–Albright.","images":[{"u":"/assets/Uploads/systemic/calm1.jpg","cap":"Café-au-lait macule","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calm2.jpg","cap":"Café-au-lait macule","c":"© DermNet"},{"u":"/assets/Uploads/systemic/calm3.jpg","cap":"Café-au-lait macule","c":"© DermNet"}]},{"id":"piebaldism","name":"Piebaldism","cat":"pig","lvl":2,"alt":[],"dx":[{"id":"vitiligo"},{"text":"Oculocutaneous albinism"},{"id":"halo-naevus"}],"pearl":"Congenital white forelock with symmetric hypomelanotic patches containing islands of normal and hyperpigmented skin; KIT mutation. Stable over time. Waardenburg syndrome (PAX3, MITF) adds deafness and heterochromia iridis.","images":[{"u":"/assets/Uploads/colour/piebald3.jpg","cap":"Piebaldism","c":"© DermNet"},{"u":"/assets/Uploads/colour/piebald4.jpg","cap":"Piebaldism","c":"© DermNet"},{"u":"/assets/Uploads/colour/piebald2.jpg","cap":"Piebaldism","c":"© DermNet"},{"u":"/assets/Uploads/colour/piebald5.jpg","cap":"Piebaldism","c":"© DermNet"},{"u":"/assets/Uploads/colour/piebald6.jpg","cap":"Piebaldism","c":"© DermNet"},{"u":"/assets/Uploads/colour/piebald7.jpg","cap":"Piebaldism: white forelock","c":"© DermNet"}]},{"id":"acanthosis-nigricans","name":"Acanthosis nigricans","cat":"pig","lvl":1,"alt":[],"dx":[{"id":"confluent-and-reticulated-papillomatosis"},{"id":"melasma"},{"id":"erythema-ab-igne"}],"pearl":"Velvety hyperpigmented plaques in the axillae, neck and groin. Associated with insulin resistance (type 2 diabetes, PCOS), obesity, medications (niacin, steroids), and (when abrupt and extensive with tripe palms) malignancy, especially gastric adenocarcinoma. Treat by weight loss/metformin.","images":[{"u":"/assets/collection/Acanthosis-nigricans/acanthosis-nigricans-0004.jpg","cap":"Acanthosis nigricans on the neck","c":"© Te Whatu Ora"},{"u":"/assets/collection/Acanthosis-nigricans/acanthosis-nigricans-0008.jpg","cap":"Axillary acanthosis nigricans","c":"© DermNet"},{"u":"/assets/collection/Acanthosis-nigricans/acanthosis-nigricans-0019.jpg","cap":"Acanthosis nigricans","c":"© DermNet"}]},{"id":"confluent-and-reticulated-papillomatosis","name":"Confluent and reticulated papillomatosis","cat":"pig","lvl":3,"alt":["Gougerot–Carteaud","CARP"],"dx":[{"id":"acanthosis-nigricans"},{"id":"pityriasis-versicolor"},{"id":"erythema-ab-igne"}],"pearl":"Brown, scaly papules coalescing centrally with a reticulated periphery on the upper trunk. Thought to reflect Malassezia/Dietzia colonization; minocycline is the treatment of choice (KOH negative for fungal elements).","images":[{"u":"/assets/Uploads/scaly/crp1.jpg","cap":"Confluent and reticulated papillomatosis","c":"© DermNet"},{"u":"/assets/Uploads/confluent-papillomatosis-02.jpg","cap":"Confluent and reticulated papillomatosis","c":"© DermNet"},{"u":"/assets/Uploads/confluent-papillomatosis-03.jpg","cap":"Confluent and reticulated papillomatosis","c":"© DermNet"}]},{"id":"idiopathic-guttate-hypomelanosis","name":"Idiopathic guttate hypomelanosis","cat":"pig","lvl":1,"alt":[],"dx":[{"id":"vitiligo"},{"id":"pityriasis-versicolor"},{"id":"progressive-macular-hypomelanosis"}],"pearl":"Small, discrete porcelain-white macules on the shins and forearms of sun-damaged older adults; cosmetically distressing but harmless. Cryotherapy or intralesional steroids may help.","images":[{"u":"/assets/Uploads/colour/igh2.jpg","cap":"Idiopathic guttate hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/colour/igh3.jpg","cap":"Guttate hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/guttate-hypomelanosis-3.jpg","cap":"Guttate hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/colour/igh1.jpg","cap":"Idiopathic guttate hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/guttate-hypomelanosis-2.jpg","cap":"Porcelain-white patch extending peripherally","c":"© DermNet"},{"u":"/assets/Uploads/figure-63-face4.jpg","cap":"Guttate hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/igh-ts-macro.jpg","cap":"Macroscopic view","c":"© DermNet"}]},{"id":"pityriasis-alba","name":"Pityriasis alba","cat":"pig","lvl":1,"alt":[],"dx":[{"id":"vitiligo"},{"id":"pityriasis-versicolor"},{"id":"idiopathic-guttate-hypomelanosis"}],"pearl":"Ill-defined, finely scaling hypopigmented patches on the cheeks of atopic children; most noticeable in summer on tanned skin. Treat with emollients and sun protection; low-potency topical steroids/calcineurin inhibitors.","images":[{"u":"/assets/collection/Pityriasis-alba/pityriasis-alba-0014.jpg","cap":"Pityriasis alba on the cheeks","c":"© DermNet"},{"u":"/assets/collection/Pityriasis-alba/pityriasis-alba-0015.jpg","cap":"Pityriasis alba on the cheeks","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/pitalba2.jpg","cap":"Pityriasis alba","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/s/pityriasis-alba-1.jpg","cap":"Pityriasis alba","c":"© DermNet"}]},{"id":"progressive-macular-hypomelanosis","name":"Progressive macular hypomelanosis","cat":"pig","lvl":3,"alt":[],"dx":[{"id":"pityriasis-versicolor"},{"id":"vitiligo"},{"id":"pityriasis-alba"}],"pearl":"Ill-defined hypopigmented macules on the trunk of young adults; red follicular fluorescence under Wood lamp (Cutibacterium acnes). Responds to benzoyl peroxide/clindamycin plus UV therapy.","images":[{"u":"/assets/Uploads/colour/w/progressive-hypomelanosis-1.jpg","cap":"Progressive macular hypomelanosis","c":"© DermNet"},{"u":"/assets/Uploads/colour/w/progressive-hypomelanosis-2.jpg","cap":"Progressive macular hypomelanosis","c":"© DermNet"}]},{"id":"alopecia-areata","name":"Alopecia areata","cat":"hair","lvl":1,"alt":[],"dx":[{"id":"tinea-capitis"},{"id":"trichotillomania"},{"id":"telogen-effluvium"},{"id":"lichen-planopilaris"}],"pearl":"Non-scarring patchy hair loss with exclamation-point hairs, yellow dots (dermoscopy), and nail pitting. Associated with atopy, thyroid disease and Down syndrome. Peribulbar \"swarm of bees\" lymphocytic infiltrate. Intralesional triamcinolone; JAK inhibitors (baricitinib, ritlecitinib, deuruxolitinib) for severe disease.","images":[{"u":"/assets/collection/Alopecia-areata/alopecia-areata-00004.jpg","cap":"A single patch of alopecia areata","c":"© DermNet"},{"u":"/assets/collection/Alopecia-areata/alopecia-areata-00001.jpg","cap":"Extensive patchy alopecia areata","c":"© Raimo Suhonen"},{"u":"/assets/collection/Alopecia-areata/alopecia-areata-00023.jpg","cap":"Alopecia totalis","c":"© Dr Mashihul Hossain"},{"u":"/assets/collection/Alopecia-areata/alopecia-areata-00028.jpg","cap":"Ophiasic pattern alopecia areata","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Alopecia-areata/alopecia-areata-00019.jpg","cap":"Extensive alopecia areata with retention of grey hairs","c":"© Dr Lawrence Meyerson"}]},{"id":"male-pattern-hair-loss","name":"Androgenetic alopecia","cat":"hair","lvl":1,"alt":["Male-pattern hair loss","Androgenic alopecia"],"dx":[{"id":"telogen-effluvium"},{"id":"alopecia-areata"},{"id":"lichen-planopilaris"}],"pearl":"Progressive miniaturization with variable hair shaft diameter (anisotrichosis). DHT-mediated (5α-reductase type 2): finasteride, dutasteride, minoxidil (low-dose oral too), PRP. Women: Ludwig pattern, check ferritin/thyroid/androgens; spironolactone.","images":[{"u":"/assets/Uploads/hair-nails-sweat/aga-mild.jpg","cap":"Pattern balding","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/s/pattern.jpg","cap":"Pattern balding","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/aga-severe.jpg","cap":"Pattern balding","c":"© DermNet"}]},{"id":"telogen-effluvium","name":"Telogen effluvium","cat":"hair","lvl":1,"alt":[],"dx":[{"id":"male-pattern-hair-loss"},{"id":"alopecia-areata"},{"id":"trichotillomania"}],"pearl":"Diffuse shedding 2–3 months after a trigger (fever, childbirth, surgery, crash diet, iron deficiency, drugs). Positive hair pull test, club hairs with telogen bulbs; self-limiting within 6 months. Anagen effluvium (chemotherapy) occurs within days to weeks.","images":[{"u":"/assets/Uploads/telogen-effluvium-regrowth-v3.jpg","cap":"Telogen effluvium","c":"© DermNet"},{"u":"/assets/Uploads/telogen-effluvium-1.jpg","cap":"Telogen effluvium","c":"© DermNet"},{"u":"/assets/Uploads/telogen-effluvium-2.jpg","cap":"Hair shedding","c":"© DermNet"}]},{"id":"trichotillomania","name":"Trichotillomania","cat":"hair","lvl":1,"alt":[],"dx":[{"id":"alopecia-areata"},{"id":"tinea-capitis"},{"id":"traction-alopecia"}],"pearl":"Irregular patches of broken hairs of varying lengths in a child or adult. Trichoscopy: broken hairs, V-sign, flame hairs, black dots, trichoptilosis. Biopsy: trichomalacia, empty follicles and pigment casts, and no inflammation. Treat with habit reversal and N-acetylcysteine.","images":[{"u":"/assets/Uploads/doctors/follicular/images/hairloss10.jpg","cap":"Trichotillomania","c":"© DermNet"},{"u":"/assets/Uploads/trichotillomania-03.jpg","cap":"trichotillomania 03","c":"© DermNet"},{"u":"/assets/Uploads/trichotillomania2.jpg","cap":"trichotillomania2","c":"© DermNet"}]},{"id":"traction-alopecia","name":"Traction alopecia","cat":"hair","lvl":1,"alt":[],"dx":[{"id":"trichotillomania"},{"id":"alopecia-areata"},{"id":"central-centrifugal-cicatricial-alopecia"}],"pearl":"Marginal hair loss from tight hairstyles (braids, weaves, ponytails). \"Fringe sign\" with preserved hairs at the very margin. Early: reversible; chronic traction → scarring.","images":[{"u":"/assets/Uploads/hair-nails-sweat/traction.jpg","cap":"Traction alopecia","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/traction2.jpg","cap":"Traction alopecia","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/traction-alopecia-2.jpg","cap":"Traction alopecia","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/traction-alopecia-3.jpg","cap":"Traction alopecia","c":"© DermNet"},{"u":"/assets/Uploads/traction-alopecia-5.jpg","cap":"Traction alopecia","c":"© DermNet"},{"u":"/assets/Uploads/traction-alopecia-4.jpg","cap":"Traction alopecia","c":"© DermNet"}]},{"id":"lichen-planopilaris","name":"Lichen planopilaris","cat":"hair","lvl":2,"alt":[],"dx":[{"id":"discoid-lupus-erythematosus"},{"id":"frontal-fibrosing-alopecia"},{"id":"folliculitis-decalvans"},{"id":"alopecia-areata"}],"pearl":"Scarring alopecia with perifollicular erythema and scale (peripilar casts). The Graham-Little–Piccardi–Lassueur syndrome has LPP, non-cicatricial axillary/pubic hair loss and follicular spinous papules. Treat with potent steroids, hydroxychloroquine, doxycycline, mycophenolate; pioglitazone.","images":[{"u":"/assets/Uploads/hair-loss-02.jpg","cap":"Lichen planopilaris","c":"© DermNet"},{"u":"/assets/collection/Lichen-planopilaris/lichen-planopilaris-0006.jpg","cap":"The atrophic scalp of a male patient with Graham-Little syndrome","c":"© DermNet"},{"u":"/assets/Uploads/madarosis-20.jpg","cap":"Madarosis due to lichen planopilaris","c":"© DermNet"},{"u":"/assets/collection/Lichen-planopilaris/lichen-planopilaris-0007.jpg","cap":"Clinical image of Graham-Little syndrome, presenting with alopecia of the forearm","c":"© DermNet"}]},{"id":"frontal-fibrosing-alopecia","name":"Frontal fibrosing alopecia","cat":"hair","lvl":2,"alt":["FFA"],"dx":[{"id":"lichen-planopilaris"},{"id":"male-pattern-hair-loss"},{"id":"alopecia-areata"}],"pearl":"Band-like recession of the frontotemporal hairline in postmenopausal women with loss of eyebrows and \"lonely hair\" sign; a variant of lichen planopilaris. Facial papules, sunscreen/cosmetic association. Treat with 5-ARIs (finasteride, dutasteride), topical steroids/calcineurin inhibitors, hydroxychloroquine.","images":[{"u":"/assets/Uploads/hair-nails-sweat/ffa3.jpg","cap":"Note the zone of unsundamaged skin","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/ffa2.jpg","cap":"Frontal fibrosing alopecia","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/ffa1.jpg","cap":"Note the perifollicular inflammation","c":"© DermNet"},{"u":"/assets/Uploads/madarosis-15.jpg","cap":"Madarosis in frontal fibrosing alopecia","c":"© DermNet"},{"u":"/assets/Uploads/madarosis-6.jpg","cap":"Madarosis due to frontal fibrosing alopecia","c":"© DermNet"},{"u":"/assets/Uploads/madarosis-17.jpg","cap":"Madarosis due to frontal fibrosing alopecia","c":"© DermNet"}]},{"id":"central-centrifugal-cicatricial-alopecia","name":"Central centrifugal cicatricial alopecia","cat":"hair","lvl":2,"alt":["CCCA"],"dx":[{"id":"traction-alopecia"},{"id":"male-pattern-hair-loss"},{"id":"lichen-planopilaris"}],"pearl":"Most common scarring alopecia in women of African descent; scarring begins at the vertex and expands centrifugally with premature desquamation of the inner root sheath. PADI3/PADI4 mutations. Treat with anti-inflammatory therapies, doxycycline, topical steroids, and minoxidil; avoid traction and heat.","images":[{"u":"/assets/Uploads/hair-nails-sweat/ccca-1.jpg","cap":"CCCA","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/ccca-2.jpg","cap":"CCCA","c":"© DermNet"}]},{"id":"nail-psoriasis","name":"Nail psoriasis","cat":"nail","lvl":1,"alt":[],"dx":[{"id":"fungal-nail-infections"},{"id":"lichen-planus"},{"id":"alopecia-areata"}],"pearl":"Nail pitting (matrix), oil-drop (salmon patch), onycholysis, subungual hyperkeratosis, splinter hemorrhages. A strong predictor of psoriatic arthritis (DIP involvement). Intralesional steroids, biologics.","images":[{"u":"/assets/Uploads/doctors/scaly-rashes/images/ps-nails2.jpg","cap":"Nail psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/nail-psoriasis/3247.jpg","cap":"Nail psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/nail-psoriasis/3260.jpg","cap":"Nail psoriasis","c":"© DermNet"},{"u":"/assets/Uploads/psoriasis-03.jpg","cap":"Pitting and onychorrhexis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/nail-psoriasis/3248.jpg","cap":"Leukonychia and Beau lines","c":"© DermNet"},{"u":"/assets/Uploads/scaly/nail-psoriasis/3218.jpg","cap":"Crumbling nails","c":"© DermNet"},{"u":"/assets/Uploads/nail-psoriasis.jpg","cap":"Onycholysis and salmon patch","c":"© DermNet"},{"u":"/assets/Uploads/scaly/nail-psoriasis/3261.jpg","cap":"Subungual hyperkeratosis","c":"© DermNet"}]},{"id":"yellow-nail-syndrome","name":"Yellow nail syndrome","cat":"nail","lvl":3,"alt":[],"dx":[{"id":"fungal-nail-infections"},{"id":"nail-psoriasis"},{"id":"paronychia"}],"pearl":"Triad: yellow thickened slow-growing, over-curved nails with absent lunulae and cuticles, lymphedema, and respiratory disease (pleural effusion, chronic sinusitis, bronchiectasis). Treat with vitamin E and pulsed antifungals.","images":[{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail1.jpg","cap":"Yellow nail syndrome","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail2.jpg","cap":"Yellow nail syndrome","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail3.jpg","cap":"Yellow nail syndrome","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail4.jpg","cap":"Yellow nail syndrome","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail5.jpg","cap":"Yellow nail syndrome","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/yellow-nail6.jpg","cap":"Yellow nail syndrome","c":"© DermNet"}]},{"id":"paronychia","name":"Chronic paronychia","cat":"nail","lvl":1,"alt":["Paronychia"],"dx":[{"id":"fungal-nail-infections"},{"id":"acrodermatitis-continua-of-hallopeau"},{"id":"herpes-simplex"}],"pearl":"Swollen, tender, erythematous proximal nail fold with loss of cuticle and nail ridging from wet work (Candida; irritant). Acute paronychia is typically S. aureus. Avoid moisture, use topical steroids; treat the Candida.","images":[{"u":"/assets/Uploads/fungal/paron1.jpg","cap":"Paronychia","c":"© DermNet"},{"u":"/assets/Uploads/fungal/s/paron2.jpg","cap":"Paronychia","c":"© DermNet"},{"u":"/assets/collection/Paronychia-SOC/paronychia-00019.jpg","cap":"Paronychia","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/fungal/paron3.jpg","cap":"Paronychia and ingrown toenail in an athlete","c":"© DermNet"},{"u":"/assets/Uploads/fungal/paron7.jpg","cap":"Acute staphylococcal paronychia","c":"© DermNet"},{"u":"/assets/Uploads/fungal/paron9.jpg","cap":"Acute herpetic paronychia","c":"© DermNet"},{"u":"/assets/Uploads/fungal/paron4.jpg","cap":"Nailfold swelling","c":"© DermNet"},{"u":"/assets/Uploads/fungal/paron5.jpg","cap":"Nail dystrophy","c":"© DermNet"}]},{"id":"white-nail","name":"Leukonychia","cat":"nail","lvl":2,"alt":["White nail"],"dx":[{"id":"fungal-nail-infections"},{"id":"yellow-nail-syndrome"},{"id":"nail-psoriasis"}],"pearl":"True leukonychia (matrix; punctate from trauma, total in hereditary form or hypoalbuminemia (Muehrcke lines, paired transverse bands that disappear with pressure), apparent leukonychia: Terry nails (liver disease, ground-glass, absent lunula), Lindsay half-and-half nails (renal disease).","images":[{"u":"/assets/Uploads/white-nail-5.jpg","cap":"Punctate leukonychia","c":"© DermNet"},{"u":"/assets/collection/Leukonychia/leukonychia-0001.jpg","cap":"Parallel bands of leukonychia due to cyclical chemotherapy","c":"© DermNet"},{"u":"/assets/collection/Leukonychia/leukonychia-0009.jpg","cap":"Congenital leukonychia","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Leukonychia/leukonychia-0006.jpg","cap":"'Half and half nail': leukonychia is affecting the proximal half of the nail","c":"© Te Whatu Ora"},{"u":"/assets/collection/Leukonychia/leukonychia-0008.jpg","cap":"Congenital leukonychia","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Leukonychia/leukonychia-0012.jpg","cap":"Leukonychia due to hypoalbuminaemia","c":"© Te Whatu Ora"}]},{"id":"hypertrophic-osteoarthropathy-and-digital-clubbing","name":"Digital clubbing","cat":"nail","lvl":1,"alt":["Clubbing","Hypertrophic osteoarthropathy"],"dx":[{"id":"yellow-nail-syndrome"},{"id":"paronychia"},{"text":"Terry nails"}],"pearl":"Loss of the Lovibond angle (>180°), bulbous fingertips and a floating nail. Associated with lung cancer, bronchiectasis, cystic fibrosis, congenital cyanotic heart disease, IBD, cirrhosis. Pachydermoperiostosis is the primary form.","images":[{"u":"/assets/Uploads/systemic/s/clubbing1.jpg","cap":"Clubbing","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/clubbing2.jpg","cap":"Clubbing","c":"© DermNet"},{"u":"/assets/Uploads/systemic/clubbing3.jpg","cap":"Clubbing","c":"© DermNet"},{"u":"/assets/Uploads/hair-nails-sweat/schamroth.jpg","cap":"Schamroth window","c":"© DermNet"}]},{"id":"subungual-haemorrhage","name":"Subungual hematoma","cat":"nail","lvl":1,"alt":["Subungual haemorrhage","Splinter haemorrhage"],"dx":[{"id":"acral-lentiginous-melanoma"},{"id":"melanonychia"},{"id":"glomus-tumour"}],"pearl":"Trauma-related blood under the nail; grows out with the nail (unlike melanoma, which stays fixed in position). Splinter hemorrhages: trauma, psoriasis, endocarditis, vasculitis, antiphospholipid syndrome.","images":[{"u":"/assets/Uploads/subungual-haematoma-2-v3.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haematoma-4-v2.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haematoma-5-v2.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haemorrhage-6.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haemorrhage-7.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haemorrhage-8.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/bleeding-03.jpg","cap":"Subungual haemorrhage","c":"© DermNet"},{"u":"/assets/Uploads/subungual-haematoma-surgery-1.jpg","cap":"Subungual haematoma","c":"© DermNet"}]},{"id":"neurofibromatosis","name":"Neurofibromatosis type 1","cat":"gen","lvl":1,"alt":["NF1","von Recklinghausen disease"],"dx":[{"id":"cafe-au-lait-macule"},{"id":"tuberous-sclerosis"},{"id":"solitary-neurofibroma"}],"pearl":"NF1 gene (17q11), autosomal dominant, 50% de novo. Criteria (2 of): ≥6 CALMs, ≥2 neurofibromas or 1 plexiform, axillary/inguinal freckling, optic glioma, ≥2 Lisch nodules, bony dysplasia, first-degree relative. Risks: MPNST, pheochromocytoma, juvenile myelomonocytic leukemia. NF2 = bilateral vestibular schwannomas.","images":[{"u":"/assets/collection/Neurofibromatosis/neurofibromatosis-0001.jpg","cap":"Neurofibromatosis","c":"© Dr Mashihul Hossain"},{"u":"/assets/Uploads/systemic/w/nf05.jpg","cap":"Neurofibromatosis","c":"© DermNet"},{"u":"/assets/Uploads/neurofibromatosis-02.jpg","cap":"Neurofibromas","c":"© DermNet"},{"u":"/assets/Uploads/Neurofibromatosis-Type-1.jpg","cap":"Neurofibromatosis Type 1","c":"Open access image"},{"u":"/assets/Uploads/doctors/systemic/images/nf1.jpg","cap":"Café-au-lait macule","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/nf6.jpg","cap":"Café-au-lait macule","c":"© DermNet"},{"u":"/assets/Uploads/systemic/nf3.jpg","cap":"Freckling in the armpit","c":"© DermNet"},{"u":"/assets/Uploads/systemic/nf5.jpg","cap":"Neurofibroma","c":"© DermNet"}]},{"id":"tuberous-sclerosis","name":"Tuberous sclerosis complex","cat":"gen","lvl":1,"alt":["TSC","Bourneville disease"],"dx":[{"id":"neurofibromatosis"},{"id":"trichoepithelioma"},{"id":"acne-vulgaris"}],"pearl":"TSC1 (hamartin) / TSC2 (tuberin) → mTOR activation. Ash-leaf macules (Wood lamp), angiofibromas (\"adenoma sebaceum\"), shagreen patch, ungual (Koenen) fibromas, confetti hypopigmentation. Seizures, cortical tubers, SEGA, cardiac rhabdomyomas, renal angiomyolipomas, LAM. Topical/oral sirolimus; everolimus for SEGA/AMLs.","images":[{"u":"/assets/Uploads/Tuberous-Sclerosis.jpg","cap":"Genetics of Tuberous sclerosis*","c":"Open access image"},{"u":"/assets/Uploads/systemic/tubscler2.jpg","cap":"Angiofibromas in tuberous sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/tubscler7.jpg","cap":"Angiofibromas in tuberous sclerosis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/systemic/tubscler1.jpg","cap":"Angiofibromas in tuberous sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/tubscler3.jpg","cap":"Periungual fibroma in tuberous sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/tubscler8.jpg","cap":"Periungual fibroma in tuberous sclerosis","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/koenentumor2b.jpg","cap":"Periungual fibroma in tuberous sclerosis","c":"© DermNet"},{"u":"/assets/Uploads/systemic/shagreen1.jpg","cap":"Shagreen patch in tuberous sclerosis","c":"© DermNet"}]},{"id":"ichthyosis-vulgaris","name":"Ichthyosis vulgaris","cat":"gen","lvl":1,"alt":[],"dx":[{"id":"recessive-x-linked-ichthyosis"},{"id":"asteatotic-eczema"},{"text":"Lamellar ichthyosis"}],"pearl":"Fine white scale sparing the flexures, hyperlinear palms and keratosis pilaris; semidominant FLG loss-of-function. Histology: decreased/absent granular layer. Associated with atopy.","images":[{"u":"/assets/Uploads/scaly/w/ichthyosis-vulgaris-1.jpg","cap":"Ichthyosis vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/ichthyosis-vulgaris-2.jpg","cap":"Ichthyosis vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/ichthyosis-vulgaris-3.jpg","cap":"Ichthyosis vulgaris","c":"© DermNet"},{"u":"/assets/Uploads/scaly/ichthyosis-vulgaris-4.jpg","cap":"Ichthyosis vulgaris","c":"© DermNet"}]},{"id":"recessive-x-linked-ichthyosis","name":"X-linked recessive ichthyosis","cat":"gen","lvl":2,"alt":["XLI"],"dx":[{"id":"ichthyosis-vulgaris"},{"text":"Lamellar ichthyosis"},{"id":"asteatotic-eczema"}],"pearl":"Steroid sulfatase (STS) deficiency: large dark \"dirty\" scale on the neck, trunk and flexures, sparing palms/soles, in a male. Associated with cryptorchidism, corneal opacities, and deletions causing Kallmann syndrome. Prolonged labor in mothers (low estrogen), placental sulfatase deficiency.","images":[{"u":"/assets/Uploads/X-linked-Ichthyosis.jpg","cap":"Genetics of X-linked ichthyosis*","c":"Open access image"},{"u":"/assets/Uploads/scaly/x-linked-ichthyosis-1.jpg","cap":"Recessive X-linked ichthysosis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/x-linked-ichthyosis-2.jpg","cap":"Recessive X-linked ichthysosis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/x-linked-ichthyosis-3.jpg","cap":"Recessive X-linked ichthysosis","c":"© DermNet"},{"u":"/assets/Uploads/scaly/w/x-linked-ichthyosis-4.jpg","cap":"Recessive X-linked ichthysosis","c":"© DermNet"},{"u":"/assets/Uploads/x-linked-ichthyosis-3.jpg","cap":"X linked ichthyosis","c":"© DermNet"},{"u":"/assets/Uploads/x-linked-ichthyosis-4.jpg","cap":"X linked ichthyosis","c":"© DermNet"}]},{"id":"harlequin-ichthyosis","name":"Harlequin ichthyosis","cat":"gen","lvl":3,"alt":[],"dx":[{"text":"Lamellar ichthyosis"},{"text":"Collodion baby"},{"id":"epidermolytic-ichthyosis"}],"pearl":"ABCA12 mutations (lipid transport; lamellar granules) causing thick plate-like scale with eclabium and ectropion; neonatal emergency. Oral retinoids are life-saving.","images":[{"u":"/assets/Uploads/Harlequin-fetus.JPG","cap":"Harlequin foetus","c":""}]},{"id":"epidermolytic-ichthyosis","name":"Epidermolytic ichthyosis","cat":"gen","lvl":3,"alt":["Bullous congenital ichthyosiform erythroderma","Epidermolytic hyperkeratosis"],"dx":[{"id":"epidermolysis-bullosa"},{"id":"ichthyosis-vulgaris"},{"text":"Lamellar ichthyosis"}],"pearl":"KRT1/KRT10 mutations: neonatal blistering and erythroderma evolving to corrugated hyperkeratosis in flexures. Histology: epidermolytic hyperkeratosis (vacuolization, clumped keratohyalin). Skin is malodorous and superinfected.","images":[{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0001.jpg","cap":"Denuded areas of skin on the back with erythroderma in a neonate with bullous ichthyosiform erythroderma","c":"© Te Whatu Ora"},{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0003.jpg","cap":"Denuded areas of skin on the legs and abdomen with erythroderma in a neonate with bullous ichthyosiform erythroderma","c":"© Te Whatu Ora"},{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0002.jpg","cap":"Denuded areas of skin on the abdomen and legs with erythroderma in a neonate with bullous ichthyosiform erythroderma","c":"© Te Whatu Ora"},{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0004.jpg","cap":"Severe palmar keratoderma and extensive scaling over the chest in a baby with bullous ichthyosifrom erythroderma","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/epidermolytic-hyperkeratosis-07.jpg","cap":"Epidermolytic hyperkeratosis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/epidermolytic-hyperkeratosis-06.jpg","cap":"Epidermolytic hyperkeratosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0007.jpg","cap":"Localised dry hyperkeratotic plaques on the wrists in an adult with bullous ichthyosiform erythroderma","c":"© DermNet"},{"u":"/assets/collection/Keratinopathic-ichthyosis/keratinopathic-ichthyosis-0009.jpg","cap":"Localised dry hyperkeratotic plaques in the popliteal fossae in an adult with bullous ichthyosiform erythroderma","c":"© DermNet"}]},{"id":"darier-disease","name":"Darier disease","cat":"gen","lvl":2,"alt":["Keratosis follicularis"],"dx":[{"id":"transient-acantholytic-dermatosis"},{"id":"benign-familial-pemphigus"},{"id":"seborrhoeic-dermatitis"}],"pearl":"ATP2A2 (SERCA2, endoplasmic reticulum calcium pump); greasy crusted keratotic papules in seborrheic areas, nail V-shaped nicking with red/white longitudinal bands, palmar pits, cobblestone mucosa. Histology: corps ronds and grains, suprabasal acantholysis. Triggered by heat, sun, lithium; oral retinoids help.","images":[{"u":"/assets/Uploads/doctors/scaly-rashes/images/darier1.jpg","cap":"Darier disease on the mid-back","c":"© DermNet"},{"u":"/assets/Uploads/scaly/darier5.jpg","cap":"Scalp disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/darier-cyst.jpg","cap":"Facial cysts","c":"© DermNet"},{"u":"/assets/Uploads/scaly/s/darier-nail.jpg","cap":"Nail disease","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/scaly/darier-nail2.jpg","cap":"V-nick and red streaks in fingernails","c":"© DermNet"},{"u":"/assets/Uploads/scaly/darier-pits.jpg","cap":"Palmar pits","c":"© DermNet"},{"u":"/assets/Uploads/scaly/darier-hs.jpg","cap":"Darier disease","c":"© DermNet"},{"u":"/assets/Uploads/scaly/darier-pre.jpg","cap":"Darier disease before acitretin","c":"© DermNet"}]},{"id":"benign-familial-pemphigus","name":"Hailey–Hailey disease","cat":"gen","lvl":2,"alt":["Benign familial pemphigus","Familial benign chronic pemphigus"],"dx":[{"id":"darier-disease"},{"id":"candida"},{"id":"pemphigus-vulgaris"},{"id":"tinea-cruris"}],"pearl":"ATP2C1 (SPCA1, Golgi calcium pump): macerated, malodorous, fissured plaques in the axillae and groin, with longitudinal white nail bands. Histology: \"dilapidated brick wall\" acantholysis. Triggers: friction, heat, infection. Treat with topical steroids/antibiotics, botulinum toxin, naltrexone.","images":[{"u":"/assets/Uploads/hailey-hailey-axilla2.jpg","cap":"Hailey-Hailey disease in axilla","c":"© DermNet"},{"u":"/assets/Uploads/hailey-hailey-chest.jpg","cap":"Hailey-Hailey disease of chest","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/systemic/w/hailey-hailey.jpg","cap":"Hailey-Hailey disease in axilla","c":"© Te Whatu Ora"},{"u":"/assets/collection-O/Hailey-Hailey-disease/benign-familial-pemphigus-00030.jpg","cap":"Hailey-Hailey disease","c":"© DermNet"},{"u":"/assets/Uploads/h-h-d-blisters.jpg","cap":"Hailey-Hailey disease blisters","c":"© DermNet"},{"u":"/assets/Uploads/hailey-hailey-close-up2.jpg","cap":"Hailey Hailey disease close up","c":"© Te Whatu Ora"}]},{"id":"pseudoxanthoma-elasticum","name":"Pseudoxanthoma elasticum","cat":"gen","lvl":2,"alt":["PXE"],"dx":[{"id":"xanthoma"},{"text":"Cutis laxa"},{"id":"ehlers-danlos-syndrome"}],"pearl":"ABCC6 mutation → yellow \"plucked chicken skin\" papules in the neck/axillae, angioid streaks of the retina, GI bleeding, and premature atherosclerosis. Histology: von Kossa calcification of fragmented elastic fibers. Monitor with ophthalmology; avoid NSAIDs/aspirin.","images":[{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0001.jpg","cap":"Yellow patches of pseudoxanthoma elasticum in the antecubital fossa","c":"© DermNet"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0002.jpg","cap":"Yellow patches of pseudoxanthoma elasticum in the antecubital fossa","c":"© DermNet"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0006.jpg","cap":"Yellow plaques and skin laxity in the axillae in PXE","c":"© Te Whatu Ora"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0005.jpg","cap":"Yellow papules of PXE on the neck producing a","c":"© DermNet"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0012.jpg","cap":"Longstanding neck pseudoxanthoma elasticum producing yellow plaques and skin laxity","c":"© DermNet"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0008.jpg","cap":"Yellow papules of PXE on the neck","c":"© Dr Lawrence Meyerson"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0013.jpg","cap":"Angioid streaks extending from the fundus at 6 and 10 o'clock","c":"© DermNet"},{"u":"/assets/collection/Pseudoxanthoma-elasticum/pseudoxanthoma-elasticum-0014.jpg","cap":"An angioid streak extending from the fundus at 5 o'clock","c":"© DermNet"}]},{"id":"ehlers-danlos-syndrome","name":"Ehlers–Danlos syndrome","cat":"gen","lvl":2,"alt":["EDS"],"dx":[{"text":"Cutis laxa"},{"id":"pseudoxanthoma-elasticum"},{"text":"Marfan"}],"pearl":"Hypermobility, hyperextensible skin, atrophic \"cigarette-paper\" scars and easy bruising. Classical (COL5A1/2, with molluscoid pseudotumors), vascular (COL3A1; arterial rupture, bowel perforation, translucent skin, \"Madonna\" facies), kyphoscoliotic (lysyl hydroxylase), hypermobile (most common).","images":[{"u":"/assets/Uploads/EDS-hyperelastic-03.jpg","cap":"Ehlers-Danlos syndrome","c":"© DermNet"},{"u":"/assets/Uploads/EDS-hypermobility-02.jpg","cap":"Ehlers-Danlos syndrome","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eds2.jpg","cap":"Bruises and scars","c":"© DermNet"},{"u":"/assets/Uploads/EDS-hyperelastic-02.jpg","cap":"Ehlers-Danlos syndrome","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/EDS-hyperelastic-01.jpg","cap":"Ehlers-Danlos syndrome","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/doctors/wound-healing/images/eds.jpg","cap":"Ehlers-Danlos syndrome","c":"© DermNet"},{"u":"/assets/Uploads/systemic/eds3.jpg","cap":"Ehlers-Danlos syndrome","c":"© DermNet"},{"u":"/assets/Uploads/EDS-bruises-03.jpg","cap":"Ehlers-Danlos syndrome","c":"© DermNet"}]},{"id":"incontinentia-pigmenti","name":"Incontinentia pigmenti","cat":"gen","lvl":3,"alt":["Bloch–Sulzberger syndrome"],"dx":[{"id":"epidermolysis-bullosa"},{"id":"epidermal-naevi"},{"id":"lichen-striatus"}],"pearl":"X-linked dominant IKBKG/NEMO (lethal in males). Four stages along Blaschko lines: vesicobullous → verrucous → hyperpigmented swirls → hypopigmented atrophic. Eosinophilic spongiosis, peripheral eosinophilia; retinal, CNS and dental anomalies.","images":[{"u":"/assets/Uploads/Incontinentia-pigmenti.jpg","cap":"Genetics of Incontinentia pigmenti*","c":"Open access image"},{"u":"/assets/Uploads/incontinentia-pigmenti-5.jpg","cap":"Vesicular stage of incontinentia pigmenti","c":"© DermNet"},{"u":"/assets/Uploads/incontinentia-pigmenti-6.jpg","cap":"Vesicular stage of incontinentia pigmenti","c":"© DermNet"},{"u":"/assets/Uploads/incontinentia-pigmenti-7.jpg","cap":"Verrucous stage of incontinentia pigmenti","c":"© DermNet"},{"u":"/assets/Uploads/incontinentia-pigmenti-8.jpg","cap":"Hyperpigmented stage of incontinentia pigmenti","c":"© DermNet"},{"u":"/assets/Uploads/incontinentia-pigmenti-9.jpg","cap":"Hyperpigmented stage of incontinentia pigmenti","c":"© DermNet"}]},{"id":"xeroderma-pigmentosum","name":"Xeroderma pigmentosum","cat":"gen","lvl":2,"alt":["XP"],"dx":[{"text":"Oculocutaneous albinism"},{"id":"polymorphic-light-eruption"},{"id":"basal-cell-naevus-syndrome"}],"pearl":"Defective nucleotide excision repair (XPA–XPG) → extreme UV sensitivity and a 1000-fold risk of skin cancer under age 20; neurologic degeneration in XP-A/D. Strict photoprotection; oral retinoids for chemoprevention. XP-V (POLH) is the variant: normal NER and later onset.","images":[{"u":"/assets/Uploads/xeroderma-pigmentosum-07.jpg","cap":"Dry scaly skin","c":"© RDTC, Tanzania"},{"u":"/assets/Uploads/xeroderma-pigmentosum-10.jpg","cap":"Tumour on tongue","c":"© RDTC, Tanzania"},{"u":"/assets/Uploads/xeroderma-pigmentosum-11.jpg","cap":"Squamous cell carcinoma on upper lip","c":"© RDTC, Tanzania"}]},{"id":"basal-cell-naevus-syndrome","name":"Basal cell nevus (Gorlin) syndrome","cat":"gen","lvl":2,"alt":["Gorlin syndrome","Basal cell naevus syndrome"],"dx":[{"id":"basal-cell-carcinoma"},{"id":"xeroderma-pigmentosum"},{"id":"epidermoid-cyst"}],"pearl":"PTCH1; multiple early-onset BCCs, odontogenic keratocysts (jaw), palmar/plantar pits, bifid ribs, falx cerebri calcification, medulloblastoma (SUFU). Avoid radiation. Vismodegib/sonidegib are treatment options; they cause muscle spasm and alopecia.","images":[{"u":"/assets/Uploads/systemic/gorlin1.jpg","cap":"Multiple BCCs and scars","c":"© DermNet"},{"u":"/assets/Uploads/systemic/gorlin2.jpg","cap":"Palmar pits","c":"© DermNet"},{"u":"/assets/Non-clinical-images/Basal-cell-naevus-syndrome.jpg","cap":"Genetics of Basal cell naevus syndrome (Image courtesy Genetics 4 Medics)","c":"Open access image"},{"u":"/assets/Uploads/systemic/gorlin3.jpg","cap":"Multiple BCCs and scars","c":"© DermNet"},{"u":"/assets/Uploads/advanced-bcc-26.jpg","cap":"Scarring from surgeries to many basal cell carcinomas in basal cell naevus syndrome","c":"© Te Whatu Ora"},{"u":"/assets/collection/Basal-cell-naevus-syndrome/basal-cell-naevus-syndrome-00001.jpg","cap":"Basal cell naevus syndrome: palmar pits","c":"© Poladian K, Dermatology Online Journal"}]},{"id":"peutz-jeghers-syndrome","name":"Peutz–Jeghers syndrome","cat":"gen","lvl":2,"alt":[],"dx":[{"text":"Lentigo"},{"id":"cafe-au-lait-macule"},{"id":"cowden-disease"}],"pearl":"STK11/LKB1: perioral and buccal mucosa lentigines with GI hamartomatous polyps (small bowel; intussusception) and risk of GI, pancreatic, breast, ovarian (SCTAT) and cervical (adenoma malignum) cancer.","images":[{"u":"/assets/Uploads/Peutz-Jeghers-syndrome.jpg","cap":"Genetics of Peutz-Jeghers syndrome*","c":"Open access image"}]},{"id":"sturgeweber-syndrome","name":"Sturge–Weber syndrome","cat":"gen","lvl":2,"alt":["Sturge-Weber syndrome"],"dx":[{"id":"capillary-vascular-malformation"},{"id":"infantile-haemangioma-complications-and-treatment"},{"text":"Nevus simplex"}],"pearl":"GNAQ mosaicism: V1 port-wine stain with leptomeningeal angiomatosis, seizures, glaucoma, and hemiparesis. \"Tram-track\" calcifications on imaging. MRI with gadolinium; monitor intraocular pressure.","images":[{"u":"/assets/Uploads/sturge-weber-01.jpg","cap":"Sturge-Weber syndrome","c":"© DermNet"}]},{"id":"acrodermatitis-enteropathica","name":"Acrodermatitis enteropathica","cat":"gen","lvl":2,"alt":["Zinc deficiency"],"dx":[{"id":"candida"},{"id":"napkin-dermatitis"},{"id":"seborrhoeic-dermatitis"},{"id":"necrolytic-migratory-erythema"}],"pearl":"Periorificial and acral erosive dermatitis, alopecia and diarrhea from zinc deficiency (SLC39A4/ZIP4 hereditary; or acquired — malnutrition, parenteral nutrition, breastfed infants with low maternal milk zinc). Responds to zinc supplementation.","images":[{"u":"/assets/Uploads/systemic/acrfac.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acrgr.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acrhand.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acrfoot.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acroderm1.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acroderm2.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acroderm3.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/acroderm4.jpg","cap":"Acrodermatitis enteropathica","c":"© DermNet"}]},{"id":"cowden-disease","name":"Cowden syndrome","cat":"gen","lvl":3,"alt":["PTEN hamartoma tumor syndrome"],"dx":[{"id":"peutz-jeghers-syndrome"},{"id":"neurofibromatosis"},{"id":"tuberous-sclerosis"}],"pearl":"PTEN: facial trichilemmomas, acral keratoses, oral cobblestone papillomatosis, macrocephaly, breast/thyroid/endometrial cancer, Lhermitte–Duclos. Screen for malignancy early.","images":[{"u":"/assets/collection/Cowden-syndrome/cowden-syndrome-0008.jpg","cap":"Cobblestone appearence of the gingivae in Cowden syndrome","c":"© DermNet"},{"u":"/assets/collection/Cowden-syndrome/cowden-syndrome-0004.jpg","cap":"Warty papules on the hand in Cowden syndrome","c":"© DermNet"},{"u":"/assets/collection/Cowden-syndrome/cowden-syndrome-0007.jpg","cap":"Trichilemmomas in Cowden syndrome","c":"© DermNet"}]},{"id":"birt-hogg-dube-syndrome","name":"Birt–Hogg–Dubé syndrome","cat":"gen","lvl":3,"alt":["BHD"],"dx":[{"id":"trichoepithelioma"},{"id":"skin-tag"},{"text":"Angiofibroma"}],"pearl":"FLCN: fibrofolliculomas (small dome-shaped papules on the face/neck), acrochordons, lung cysts with spontaneous pneumothorax, and renal cell carcinoma (chromophobe/oncocytic hybrid).","images":[{"u":"/assets/Uploads/lesions/fibrofollic2.jpg","cap":"Fibrofolliculomas","c":"© DermNet"},{"u":"/assets/Uploads/birt-hogg-dube-06.jpg","cap":"Birt–Hogg–Dubé syndrome","c":"© DermNet"},{"u":"/assets/Uploads/birt-hogg-dube-09.jpg","cap":"Fibrofolliculomas in Birt–Hogg–Dubé syndrome","c":"© DermNet"}]},{"id":"morbilliform-drug-reaction","name":"Morbilliform drug eruption","cat":"drug","lvl":1,"alt":["Exanthematous drug eruption","Maculopapular drug eruption","Drug eruptions"],"dx":[{"id":"measles"},{"id":"erythema-infectiosum"},{"id":"drug-hypersensitivity-syndrome"},{"id":"syphilis"}],"pearl":"Most common cutaneous drug reaction: pink macules and papules, 4–14 days after starting the drug, spreading from trunk to extremities. Ampicillin/amoxicillin in the setting of EBV mononucleosis. Warning signs of DRESS/SJS: facial edema, mucosal erosions, blisters, fever, eosinophilia.","images":[{"u":"/assets/Uploads/reactions/morbilliform1.jpg","cap":"Morbilliform drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/morbilliform2.jpg","cap":"Morbilliform drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/morbilliform3.jpg","cap":"Purpuric morbilliform eruption due to thrombocytopenia","c":"© DermNet"}]},{"id":"drug-hypersensitivity-syndrome","name":"DRESS syndrome","cat":"drug","lvl":2,"alt":["Drug hypersensitivity syndrome","DRESS"],"dx":[{"id":"morbilliform-drug-reaction"},{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"},{"id":"erythroderma"}],"pearl":"Latency of 2–8 weeks after starting a drug (anticonvulsants, allopurinol, sulfonamides, minocycline, vancomycin); fever, facial edema, morbilliform eruption, eosinophilia, atypical lymphocytes, hepatitis, nephritis. HHV-6 reactivation; relapses and autoimmune sequelae (thyroiditis). Treat with drug withdrawal and systemic steroids.","images":[{"u":"/assets/Uploads/reactions/drug-rash1.jpg","cap":"Drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/drug-rash2.jpg","cap":"Drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/drug-rash3.jpg","cap":"Drug eruption","c":"© DermNet"}]},{"id":"fixed-drug-eruption","name":"Fixed drug eruption","cat":"drug","lvl":1,"alt":["FDE"],"dx":[{"id":"erythema-multiforme"},{"id":"postinflammatory-hyperpigmentation"},{"id":"herpes-simplex"},{"id":"allergic-contact-dermatitis"}],"pearl":"Recurrent round, dusky plaques or bullae at the same sites on re-exposure, healing with hyperpigmentation; lips, genitals. Culprits: NSAIDs, tetracyclines, sulfonamides, barbiturates, pseudoephedrine, fluconazole. CD8+ T cells persist in the epidermis of lesions.","images":[{"u":"/assets/Uploads/doctors/emergencies/images/drug3.jpg","cap":"Fixed drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/w/targetoid-08.jpg","cap":"Targetoid fixed drug eruption","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/s/fde1.jpg","cap":"Blistering fixed drug eruption","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/reactions/fde-nsaid.jpg","cap":"Fixed drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/fixed-drug-eruption-016.jpg","cap":"Fixed drug eruption","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/targetoid-07.jpg","cap":"Targetoid lesion in fixed drug eruption","c":"© DermNet"},{"u":"/assets/Uploads/reactions/fde-lips.jpg","cap":"Pigmented fixed drug eruption on the lip","c":"© DermNet"},{"u":"/assets/Uploads/doctors/emergencies/images/fde2.jpg","cap":"Ulcerated fixed drug eruption, oral mucosa","c":"© DermNet"}]},{"id":"acute-generalised-exanthematous-pustulosis","name":"AGEP","cat":"drug","lvl":2,"alt":["Acute generalized exanthematous pustulosis"],"dx":[{"id":"generalised-pustular-psoriasis"},{"id":"stevens-johnson-syndrome-toxic-epidermal-necrolysis"},{"id":"drug-hypersensitivity-syndrome"}],"pearl":"Fever with rapid-onset, non-follicular pustules on erythematous skin within 1–2 days of the culprit (aminopenicillins, macrolides, diltiazem, terbinafine, hydroxychloroquine); neutrophilia. Resolves in <15 days with desquamation; contrast with GPP.","images":[{"u":"/assets/Uploads/reactions/agep4.jpg","cap":"Acute generalised exanthematous pustulosis (AGEP)","c":"© DermNet"},{"u":"/assets/Uploads/agep-06.jpg","cap":"Acute generalised exanthematous pustulosis","c":"© DermNet"},{"u":"/assets/Uploads/reactions/agep5.jpg","cap":"Acute generalised exanthematous pustulosis (AGEP)","c":"© DermNet"},{"u":"/assets/Uploads/reactions/agep7.jpg","cap":"Acute generalised exanthematous pustulosis (AGEP)","c":"© DermNet"},{"u":"/assets/Uploads/agep-04.jpg","cap":"Acute generalised exanthematous pustulosis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/AGEP-mouth.jpg","cap":"Acute generalised exanthematous pustulosis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/agep-07.jpg","cap":"Acute generalised exanthematous pustulosis","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/agep9.jpg","cap":"Acute generalised exanthematous pustulosis (AGEP)","c":"© DermNet"}]},{"id":"phytophotodermatitis","name":"Phytophotodermatitis","cat":"photo","lvl":1,"alt":["Margarita dermatitis","Lime disease"],"dx":[{"id":"allergic-contact-dermatitis"},{"text":"Child abuse"},{"id":"sunburn"}],"pearl":"Streaky or bizarre-shaped erythema/blisters with hyperpigmentation after contact with furocoumarins (lime, celery, parsnip, fig, giant hogweed) and UVA. Not an allergy; sparing of skin without UV exposure. Can mimic abuse.","images":[{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00022.jpg","cap":"Streaky erythema on the arm","c":"© DermNet"},{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00025.jpg","cap":"Linear redness and blisters from strimming","c":"© DermNet"},{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00024.jpg","cap":"Erythema after sun exposure from eating celery seeds","c":"© DermNet"},{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00014.jpg","cap":"Postinflammatory pigmentation after resolution of phytophotodermatitis","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00020.jpg","cap":"Acute bullous phytophotodermatitis on the ankle","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Phytophotodermatitis/phytophotodermatitis-00015.jpg","cap":"Postinflammatory pigmentation from lime juice phytophotoderatitis on the chest","c":"© Te Whatu Ora"}]},{"id":"hand-foot-syndrome","name":"Hand–foot syndrome (palmar-plantar erythrodysesthesia)","cat":"drug","lvl":2,"alt":["Palmar-plantar erythrodysesthesia"],"dx":[{"id":"hand-foot-and-mouth-disease"},{"text":"Kawasaki disease"},{"text":"Acral erythema"}],"pearl":"Painful, symmetrical erythema and bullae over pressure points on palms and soles from chemotherapy (capecitabine, 5-FU, liposomal doxorubicin, docetaxel) or kinase inhibitors (sorafenib; hyperkeratotic type). Dose-reduce, emollient, urea cream.","images":[{"u":"/assets/Uploads/reactions/w/hand-foot-syndrome-1.jpg","cap":"Hand-foot syndrome due to chemotherapy","c":"© DermNet"},{"u":"/assets/Uploads/reactions/w/hand-foot-syndrome-2.jpg","cap":"Dorsal hand-foot syndrome due to chemotherapy","c":"© DermNet"},{"u":"/assets/Uploads/reactions/w/hand-foot-syndrome-3.jpg","cap":"Hand-foot syndrome due to chemotherapy","c":"© DermNet"}]},{"id":"sunburn","name":"Sunburn","cat":"photo","lvl":1,"alt":[],"dx":[{"id":"phytophotodermatitis"},{"id":"polymorphic-light-eruption"},{"id":"drug-induced-photosensitivity"}],"pearl":"UVB-induced erythema peaks at 12–24 hours. Sunburn cells (apoptotic keratinocytes) on histology. Blistering sunburns in childhood increase melanoma risk.","images":[{"u":"/assets/Uploads/reactions/sunburn1.jpg","cap":"Sunburn from a day at the pool - the skin below the straps is spared","c":"© DermNet"},{"u":"/assets/Uploads/sunburn-15.jpg","cap":"Sunburn after a day hiking - the socks have spared the ankles","c":"© DermNet"},{"u":"/assets/Uploads/sunburn1.jpg","cap":"Peeling 4 days after the acute event","c":"© DermNet"},{"u":"/assets/Uploads/treatments/sunburn2.jpg","cap":"Redness, oedema and crusting on day 3 after the acute event","c":"© DermNet"},{"u":"/assets/Uploads/melanoma/sunburn.jpg","cap":"Blistering on the lower leg due to sunburn","c":"© DermNet"}]},{"id":"polymorphic-light-eruption","name":"Polymorphic light eruption","cat":"photo","lvl":1,"alt":["PMLE"],"dx":[{"id":"subacute-cutaneous-lupus-erythematosus"},{"text":"Actinic prurigo"},{"id":"solar-urticaria"},{"id":"sunburn"}],"pearl":"Most common photodermatosis; pruritic papules/plaques appear hours–days after the first strong spring sun exposure and spares the face. UVA and UVB; delayed-type response. Prevent with sunscreens or \"hardening\" with NB-UVB/PUVA. Check ANA/Ro/La when the diagnosis is uncertain.","images":[{"u":"/assets/collection/Polymorphic-light-eruption/polymorphic-light-eruption-0005.jpg","cap":"Extensive papular and plaque polymorphic light eruption","c":"© DermNet"},{"u":"/assets/collection/Polymorphic-light-eruption/polymorphic-light-eruption-0004.jpg","cap":"Targetoid polymorphic light eruption on recently exposed arm skin","c":"© DermNet"}]},{"id":"drug-induced-photosensitivity","name":"Drug-induced photosensitivity","cat":"photo","lvl":2,"alt":["Phototoxic drug reaction"],"dx":[{"id":"sunburn"},{"id":"polymorphic-light-eruption"},{"text":"Photocontact dermatitis"}],"pearl":"Phototoxic (common, dose-dependent, exaggerated sunburn): doxycycline, amiodarone, thiazides, fluoroquinolones, voriconazole, vemurafenib. Photoallergic (delayed type IV): NSAIDs (ketoprofen), sunscreen ingredients, chlorpromazine. Amiodarone also causes a slate-gray pigmentation. Voriconazole use increases SCC risk.","images":[{"u":"/assets/Uploads/reactions/photosensitive3.jpg","cap":"A photosensitive drug eruption showing sparing under the watch and strap","c":"© DermNet"},{"u":"/assets/Uploads/reactions/photosensitive1.jpg","cap":"A phototoxic drug eruption due to an oral non-steroidal anti-inflammatory drug","c":"© DermNet"}]},{"id":"chronic-actinic-dermatitis","name":"Chronic actinic dermatitis","cat":"photo","lvl":3,"alt":["Actinic reticuloid"],"dx":[{"id":"atopic-dermatitis"},{"id":"allergic-contact-dermatitis"},{"id":"polymorphic-light-eruption"}],"pearl":"Eczematous eruption on sun-exposed skin of older men; sensitive to UVB, UVA and sometimes visible light; persistent. Check for contact/photocontact allergy to plants (sesquiterpene lactones) and fragrances.","images":[{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0006.jpg","cap":"Dermatitis on the hands with a cut off at the wrists in CAD","c":"© DermNet"},{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0007.jpg","cap":"Sparing of light-shielded skin under the ear lobe","c":"© DermNet"},{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0022.jpg","cap":"CAD affecting the face and neck","c":"© DermNet"},{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0023.jpg","cap":"Severe CAD with sparing in a light-shielded skin crease","c":"© DermNet"},{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0026.jpg","cap":"Plaques of CAD on the neck - note the cut off at the top of the collar","c":"© Te Whatu Ora"},{"u":"/assets/collection/Chronic-actinic-dermatitis/chronic-actinic-dermatitis-0027.jpg","cap":"CAD in a younger Asian man - the retroauricular sparing is marked","c":"© DermNet"}]},{"id":"erythropoietic-protoporphyria","name":"Erythropoietic protoporphyria","cat":"photo","lvl":2,"alt":["EPP"],"dx":[{"id":"porphyria-cutanea-tarda"},{"id":"polymorphic-light-eruption"},{"id":"solar-urticaria"}],"pearl":"Ferrochelatase deficiency → painful burning within minutes of sun exposure (including through window glass), with no blistering; later waxy scarring of the nose and knuckles. Gallstones and liver disease. Afamelanotide implant; beta-carotene.","images":[{"u":"/assets/Uploads/systemic/epp2.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp4.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp1.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp5.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp6.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp3.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp8.jpg","cap":"Erythropoietic protoporphyria","c":"© DermNet"},{"u":"/assets/Uploads/systemic/epp7.jpg","cap":"Erythropoietic protoporphyria","c":"© Te Whatu Ora"}]},{"id":"solar-urticaria","name":"Solar urticaria","cat":"photo","lvl":3,"alt":[],"dx":[{"id":"polymorphic-light-eruption"},{"id":"erythropoietic-protoporphyria"},{"id":"chronic-urticaria"}],"pearl":"Wheals within minutes of sun exposure (UVA, visible light) that clear within hours; type I hypersensitivity. Treat with antihistamines, omalizumab, and photoprotection.","images":[{"u":"/assets/Uploads/reactions/solar-urticaria.jpg","cap":"Solar urticaria","c":"© DermNet"},{"u":"/assets/Uploads/reactions/solar-urticaria1.jpg","cap":"Solar urticaria","c":"© DermNet"}]},{"id":"granuloma-annulare","name":"Granuloma annulare","cat":"gran","lvl":1,"alt":["GA"],"dx":[{"id":"tinea-corporis"},{"id":"necrobiosis-lipoidica"},{"id":"sarcoidosis"},{"id":"porokeratosis"}],"pearl":"Skin-colored to pink annular plaques with a beaded border on the hands/feet of children and young adults; self-limited. Generalized GA is associated with diabetes; histology: palisading granuloma around mucin (\"necrobiotic\" collagen) with interstitial pattern. Treat localized disease with potent steroids.","images":[{"u":"/assets/Uploads/dermal-infiltrative/ga1.jpg","cap":"Granuloma annulare","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/s/ga8.jpg","cap":"Granuloma annulare","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/dermal-infiltrative/ga11.jpg","cap":"Granuloma annulare","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ga3.jpg","cap":"Granuloma annulare","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ga6.jpg","cap":"Granuloma annulare","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/ga4.jpg","cap":"Granuloma annulare","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/s/deep-ga.jpg","cap":"Granuloma annulare","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/dermal-infiltrative/s/deep-ga2.jpg","cap":"Granuloma annulare","c":"© Raimo Suhonen"}]},{"id":"necrobiosis-lipoidica","name":"Necrobiosis lipoidica","cat":"gran","lvl":1,"alt":[],"dx":[{"id":"granuloma-annulare"},{"id":"sarcoidosis"},{"id":"stasis-ulcer"},{"id":"morphoea"}],"pearl":"Yellow-brown atrophic plaque with telangiectasias and a violaceous border on the shin, strongly associated with diabetes (but poor glycemic control does not predict it). Histology: layered (\"sandwich\") necrobiosis with plasma cells. Can ulcerate; treat with topical/intralesional steroids.","images":[{"u":"/assets/Uploads/systemic/nld1.jpg","cap":"Necrobiosis lipoidica","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/nld2.jpg","cap":"Necrobiosis lipoidica","c":"© DermNet"},{"u":"/assets/Uploads/nld3.jpg","cap":"Necrobiosis lipoidica","c":"© DermNet"},{"u":"/assets/Uploads/doctors/wound-healing/images/nld.jpg","cap":"Necrobiosis lipoidica","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/ulcer-32.jpg","cap":"Ulcerated necrobiosis lipoidica","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/ulcer-34.jpg","cap":"Ulcerated necrobiosis lipoidica","c":"© DermNet"}]},{"id":"sarcoidosis","name":"Cutaneous sarcoidosis","cat":"gran","lvl":1,"alt":["Sarcoidosis","Lupus pernio"],"dx":[{"id":"granuloma-annulare"},{"id":"cutaneous-tuberculosis"},{"id":"leprosy"},{"text":"Lupus pernio"}],"pearl":"The great imitator: red-brown papules/plaques with \"apple-jelly\" color on diascopy; lupus pernio (nose, cheeks; chronic, with upper airway/lung disease), scar sarcoidosis, subcutaneous nodules. Histology: non-caseating \"naked\" granulomas. Löfgren syndrome (erythema nodosum, hilar adenopathy, arthritis, fever) carries a good prognosis. Check ACE, calcium, CXR, ophthalmology and ECG.","images":[{"u":"/assets/collection/Sarcoidosis/sarcoidosis-0048.jpg","cap":"Plaque sarcoid on the cheek and nose","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/sarc-face.jpg","cap":"Sarcoidosis","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/lupus-pernio.jpg","cap":"Lupus pernio in cutaneous sarcoidosis","c":"© DermNet"},{"u":"/assets/collection/Sarcoidosis/sarcoidosis-0002.jpg","cap":"Scar sarcoid mimicing a keloid on a pierced ear lobe","c":"© DermNet"},{"u":"/assets/collection/Sarcoidosis/sarcoidosis-0003.jpg","cap":"Plaque sarcoid on the dorsal hand","c":"© DermNet"},{"u":"/assets/Uploads/doctors/systemic/images/sarc3.jpg","cap":"Extensive cutaneous sarcoidosis","c":"© DermNet"},{"u":"/assets/collection/Sarcoidosis/sarcoidosis-0013.jpg","cap":"Plaques of sarcoid on the cheeks mimicing basal cell carcinomas","c":"© DermNet"},{"u":"/assets/collection/Sarcoidosis/sarcoidosis-0044.jpg","cap":"Nasal rim sarcoid papules","c":"© Dr Lawrence Meyerson"}]},{"id":"erythema-nodosum","name":"Erythema nodosum","cat":"gran","lvl":1,"alt":[],"dx":[{"id":"cutaneous-polyarteritis-nodosa"},{"text":"Nodular vasculitis"},{"id":"cellulitis"},{"id":"sarcoidosis"}],"pearl":"Painful red nodules on the shins (septal panniculitis without vasculitis). Causes: streptococcal infection (most common), sarcoidosis, TB, IBD, pregnancy/OCP, drugs (sulfonamides), Behçet, coccidioidomycosis, Yersinia. Treat the cause; NSAIDs, potassium iodide. Bruise-like evolution.","images":[{"u":"/assets/Uploads/vascular/en1.jpg","cap":"Erythema nodosum","c":"© DermNet"},{"u":"/assets/Uploads/doctors/systemic/images/en2.jpg","cap":"Erythema nodosum","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/s/pannic3.jpg","cap":"Erythema nodosum","c":"© Raimo Suhonen"}]},{"id":"pyoderma-gangrenosum","name":"Pyoderma gangrenosum","cat":"gran","lvl":1,"alt":["PG"],"dx":[{"id":"stasis-ulcer"},{"id":"cutaneous-polyarteritis-nodosa"},{"id":"granulomatosis-with-polyangiitis"},{"id":"calciphylaxis"}],"pearl":"Painful ulcer with a violaceous undermined border that arises after minimal trauma (pathergy). Diagnosis of exclusion. Associations: IBD, rheumatoid arthritis, hematologic malignancy (AML), PAPA/PASH syndromes. Avoid surgical debridement; treat with steroids, cyclosporine, infliximab.","images":[{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0004.jpg","cap":"Early haemorrhagic pyoderma gangrenosum","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0003.jpg","cap":"Ulceration, pustulation and the violaceos edge of pyoderma gangrenosum on the shin associated with ulcerative colitis","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0005.jpg","cap":"Bullous pyoderma gangrenosum with underlying ulcerative colitis","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0006.jpg","cap":"The erythematous and violaceous border typical of pyoderma gangrenosum above the knee","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0001.jpg","cap":"Multiple ulcers on the shin - the superior edge of the proximal ulcer showing the characterisitc purple edge","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0007.jpg","cap":"Severe pathergic pyoderma gangrenosum after breast cancer reconstructive surgery (TRAM procedure)","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0008.jpg","cap":"Healed post operative pyoderma gangrenosum after pulse intravenous methylprednisolone and ciclosporin","c":"© DermNet"},{"u":"/assets/collection/Pyoderma-gangrenosum/pyoderma-gangrenosum-0051.jpg","cap":"Multiple ulcers on the buttocks - note the violaceous oedematous ulcer edges","c":"© DermNet"}]},{"id":"acute-febrile-neutrophilic-dermatosis","name":"Sweet syndrome","cat":"gran","lvl":2,"alt":["Acute febrile neutrophilic dermatosis"],"dx":[{"id":"erythema-multiforme"},{"id":"pyoderma-gangrenosum"},{"id":"cellulitis"},{"id":"erythema-nodosum"}],"pearl":"Fever, neutrophilia and tender juicy red plaques with a pseudovesicular appearance after infection (URI/GI), in AML or other malignancy, or drugs (G-CSF, azacitidine, bortezomib). Histology: dense dermal neutrophilic infiltrate without vasculitis. Rapid response to systemic steroids.","images":[{"u":"/assets/collection/Acute-febrile-neutrophilic-dermatosis/acute-febrile-neutrophilic-dermatosis-0006.jpg","cap":"Annular plaque on the neck due to acute febrile neutrophilic dermatosis - there is a pseudovesicular edge","c":"© DermNet"},{"u":"/assets/collection/Acute-febrile-neutrophilic-dermatosis/acute-febrile-neutrophilic-dermatosis-0017.jpg","cap":"Acute febrile neutrophilic dermatosis on the neck","c":"© DermNet"},{"u":"/assets/Uploads/reactions/sweet09.jpg","cap":"Plaques of tender acute febrile neutrophilic dermatosis on the neck","c":"© DermNet"},{"u":"/assets/Uploads/figure-5-blistering.jpg","cap":"Annular lesions of acute febrile neutrophilic dermatosis","c":"© DermNet"},{"u":"/assets/collection/Acute-febrile-neutrophilic-dermatosis/acute-febrile-neutrophilic-dermatosis-0010.jpg","cap":"Oedematous lesions on the fingers due to acute febrile neutrophilic dermatosis of the dorsal hands","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/w/sweet15.jpg","cap":"Sweet syndrome","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/reactions/w/sweet16.jpg","cap":"Sweet syndrome","c":"© Te Whatu Ora"},{"u":"/assets/Uploads/sweet-lip-1.jpg","cap":"Sweet syndrome affecting lip","c":"© DermNet"}]},{"id":"behcet-disease","name":"Behçet disease","cat":"vas","lvl":2,"alt":["Behcet disease"],"dx":[{"id":"aphthous-ulcer"},{"id":"herpes-simplex"},{"id":"erythema-nodosum"},{"id":"pyoderma-gangrenosum"}],"pearl":"Recurrent oral aphthae plus two of: genital ulcers, uveitis, skin lesions (EN, pustulosis), or positive pathergy test. HLA-B51, Silk Road distribution. Variable-vessel vasculitis with venous thrombosis; treat with colchicine, apremilast (oral ulcers), and anti-TNFs for severe disease.","images":[{"u":"/assets/collection/Behcet-disease/behcet-disease-0012.jpg","cap":"Behçet disease - eye","c":"© Dr Richard Ashton"},{"u":"/assets/collection/Behcet-disease/behcet-disease-0027.jpg","cap":"Behçet disease - tongue","c":"© DermNet"},{"u":"/assets/collection/Behcet-disease/behcet-disease-0036.jpg","cap":"Behçet disease - pustular lesion on arm","c":"© DermNet"}]},{"id":"cutaneous-amyloidosis","name":"Cutaneous amyloidosis","cat":"gran","lvl":3,"alt":["Lichen amyloidosis","Macular amyloidosis","Primary cutaneous amyloidosis"],"dx":[{"id":"lichen-simplex"},{"id":"lichen-planus"},{"text":"Notalgia paraesthetica"}],"pearl":"Pruritic, rippled hyperpigmented papules on the shins; macular amyloidosis (upper back; rippled pigmentation). Keratin-derived amyloid; Congo red. Systemic AL amyloidosis: periorbital purpura (\"raccoon eyes\"), macroglossia, pinch purpura, waxy papules; check for monoclonal gammopathy.","images":[{"u":"/assets/collection/Amyloidosis/amyloidosis-0013.jpg","cap":"Rippled pigmentation on the upper chest due to macular amyloidosis","c":"© DermNet"},{"u":"/assets/collection/Amyloidosis/amyloidosis-0003.jpg","cap":"Scaly tan brown papules, some arranged lineraly in lichen amyloidosis on the leg","c":"© DermNet"},{"u":"/assets/collection/Amyloidosis/amyloidosis-0004.jpg","cap":"Extensive and confluent lesions of lichen amyloidosis on the shin","c":"© DermNet"},{"u":"/assets/collection/Amyloidosis/amyloidosis-0005.jpg","cap":"Macular amyloidosis showing rippled pigmentation over the upper back","c":"© DermNet"},{"u":"/assets/collection/Amyloidosis/amyloidosis-0011.jpg","cap":"Yellow waxy nodules of amyloidosis on the thigh","c":"© DermNet"},{"u":"/assets/collection/Amyloidosis/amyloidosis-0014.jpg","cap":"Repetitive scratching of an area of notalgia paraesthetica resulting in macular amyloidosis on the back","c":"© DermNet"}]},{"id":"pretibial-myxoedema","name":"Pretibial myxedema","cat":"gran","lvl":2,"alt":["Thyroid dermopathy"],"dx":[{"id":"lipodermatosclerosis"},{"id":"necrobiosis-lipoidica"},{"id":"stasis-ulcer"}],"pearl":"Waxy, non-pitting, peau-d'orange plaques on the shins in Graves disease (with thyroid acropachy and exophthalmos) from TSH-receptor stimulating antibody; hyaluronic acid deposition. Treat with potent topical steroids.","images":[{"u":"/assets/Uploads/dermal-infiltrative/w/pretibial-myxoedema-01.jpg","cap":"Pretibial myxoedema","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/w/pretibial-myxoedema-04.jpg","cap":"Pretibial myxoedema in Graves disease","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/pretibial-myxoedema-13.jpg","cap":"Pretibial myxoedema in Graves disease","c":"© DermNet"},{"u":"/assets/Uploads/dermal-infiltrative/pretibial-myxoedema-15.jpg","cap":"Pretibial myxoedema in Graves disease","c":"© DermNet"}]},{"id":"gout","name":"Gout (tophi)","cat":"gran","lvl":2,"alt":["Gouty tophi","Tophaceous gout"],"dx":[{"id":"calcinosis-cutis"},{"text":"Rheumatoid nodules"},{"id":"epidermoid-cyst"}],"pearl":"Chalky white-yellow subcutaneous nodules on the ear helix, fingers and elbows containing monosodium urate crystals, which are needle-shaped, negatively birefringent; best preserved in alcohol-fixed tissue because formalin dissolves urate. Treat with allopurinol (HLA-B*58:01 risk) or febuxostat.","images":[{"u":"/assets/Uploads/systemic/gout4.jpg","cap":"Acute gout","c":"© DermNet"},{"u":"/assets/Uploads/systemic/gout0.jpg","cap":"Gouty tophi","c":"© DermNet"},{"u":"/assets/Uploads/systemic/gout10.jpg","cap":"Gouty tophi","c":"© DermNet"},{"u":"/assets/Uploads/systemic/gout7.jpg","cap":"Gouty tophi","c":"© DermNet"}]},{"id":"pellagra","name":"Pellagra","cat":"gran","lvl":2,"alt":["Niacin deficiency"],"dx":[{"id":"phytophotodermatitis"},{"id":"sunburn"},{"id":"acrodermatitis-enteropathica"}],"pearl":"Photosensitive dermatitis (Casal necklace around the neck), diarrhea, dementia (and death); niacin/tryptophan deficiency from malnutrition, alcoholism, carcinoid syndrome, isoniazid or Hartnup disease. Treat with nicotinamide.","images":[{"u":"/assets/Uploads/doctors/systemic/images/pell3.jpg","cap":"Pellagra","c":"© DermNet"},{"u":"/assets/Uploads/doctors/systemic/images/pell2.jpg","cap":"Pellagra","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pellagra2.jpg","cap":"Casal necklace","c":"© DermNet"},{"u":"/assets/Uploads/doctors/dermatitis/images/photo10.jpg","cap":"Pellagrous boot","c":"© DermNet"},{"u":"/assets/Uploads/systemic/pellagra1.jpg","cap":"Pellagra dermatitis on forearms","c":"© DermNet"}]},{"id":"scurvy","name":"Scurvy","cat":"gran","lvl":2,"alt":["Vitamin C deficiency"],"dx":[{"id":"keratosis-pilaris"},{"id":"cutaneous-small-vessel-vasculitis"},{"text":"Senile purpura"}],"pearl":"Perifollicular hemorrhage, corkscrew hairs, swollen bleeding gums, and poor wound healing from vitamin C deficiency (impaired hydroxylation of proline/lysine in collagen). Seen in the malnourished, elderly, and in patients with restrictive diets.","images":[{"u":"/assets/Uploads/systemic/scleg.jpg","cap":"Ecchymoses","c":"© DermNet"},{"u":"/assets/Uploads/systemic/scpap.jpg","cap":"Perifollicular haemorrhage and ecchymoses","c":"© DermNet"},{"u":"/assets/Uploads/systemic/schair.jpg","cap":"Corkscrew hairs and purpura","c":"© DermNet"},{"u":"/assets/Uploads/systemic/scclu.jpg","cap":"Purpura","c":"© DermNet"},{"u":"/assets/collection-O/Scurvy/scurvy-00002.jpg","cap":"Ecchymoses","c":"© Esteves A, Cureus"},{"u":"/assets/collection-O/Scurvy/scurvy-00003.jpg","cap":"Corkscrew hairs","c":"© Esteves A, Cureus"},{"u":"/assets/collection-O/Scurvy/scurvy-00001.jpg","cap":"Frankel sign (green arrow), Trummerfeld zone (red arrow)","c":"© Gallizzi R, Journal of Medical Case Reports"}]},{"id":"necrolytic-migratory-erythema","name":"Necrolytic migratory erythema","cat":"gran","lvl":3,"alt":["Glucagonoma syndrome"],"dx":[{"id":"acrodermatitis-enteropathica"},{"id":"pellagra"},{"id":"candida"}],"pearl":"Annular erythema with erosions, crusting and peripheral scale in the groin/perineum and acral sites with glucagonoma (pancreatic α-cell tumor), weight loss, diabetes, glossitis, and anemia. Histology: upper epidermal pallor and necrosis. Responds to tumor resection or octreotide, and amino acid/zinc supplementation.","images":[{"u":"/assets/Uploads/systemic/s/glucagon1.jpg","cap":"Necrolytic migratory erythema","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/glucagon2.jpg","cap":"Necrolytic migratory erythema","c":"© DermNet"},{"u":"/assets/Uploads/systemic/s/glucagon3.jpg","cap":"Necrolytic migratory erythema","c":"© DermNet"},{"u":"/assets/Uploads/systemic/glucagonoma1.jpg","cap":"Necrolytic migratory erythema","c":"© DermNet"},{"u":"/assets/Uploads/systemic/glucagonoma2.jpg","cap":"Necrolytic migratory erythema","c":"© DermNet"}]},{"id":"reactive-perforating-collagenosis","name":"Acquired perforating dermatosis","cat":"gran","lvl":3,"alt":["Kyrle disease","Reactive perforating collagenosis"],"dx":[{"text":"Prurigo nodularis"},{"id":"molluscum-contagiosum"},{"id":"viral-wart"}],"pearl":"Umbilicated, keratotic papules with a central plug in patients with diabetes or end-stage renal disease; transepidermal elimination of collagen, elastic fibers or keratin; Koebner. Treat the underlying disease; phototherapy.","images":[{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00002.jpg","cap":"Reactive perforating collagenosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00014.jpg","cap":"Reactive perforating collagenosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00009.jpg","cap":"Reactive perforating collagenosis","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00005.jpg","cap":"Nodules with keratotic crust","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00008.jpg","cap":"Nodule with keratotic plug and erythematous halo","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00019.jpg","cap":"Keratotic papules with koebnerisation","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00011.jpg","cap":"Hyperpigmented scratch marks","c":"© Te Whatu Ora"},{"u":"/assets/collection/Reactive-perforating-collagenosis/reactive-perforating-collagenosis-00023.jpg","cap":"Hyperpigmented keratotic papules","c":"© DermNet"}]},{"id":"lipodermatosclerosis","name":"Lipodermatosclerosis","cat":"vas","lvl":2,"alt":[],"dx":[{"id":"venous-eczema"},{"id":"cellulitis"},{"id":"morphoea"},{"id":"erythema-nodosum"}],"pearl":"\"Inverted champagne bottle\" leg: indurated, hyperpigmented skin from chronic venous insufficiency with fat necrosis. Acute phase mimics cellulitis. Compression therapy; stanozolol and pentoxifylline in refractory disease.","images":[{"u":"/assets/Uploads/acute-lipodermatosclerosis-18.jpg","cap":"Acute lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/acute-lipodermatosclerosis-10.jpg","cap":"Acute lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/acute-lipodermatosclerosis-06.jpg","cap":"Acute lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/vascular/s/lds2.jpg","cap":"Lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/vascular/lds4.jpg","cap":"Lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/vascular/lds6.jpg","cap":"Lipodermatosclerosis","c":"© DermNet"}]},{"id":"stasis-ulcer","name":"Venous stasis ulcer","cat":"vas","lvl":1,"alt":["Venous ulcer"],"dx":[{"id":"pyoderma-gangrenosum"},{"id":"livedoid-vasculopathy"},{"id":"necrobiosis-lipoidica"}],"pearl":"Irregular, shallow ulcers on the medial malleolus with surrounding hemosiderin, lipodermatosclerosis and edema. Compression therapy after excluding arterial disease with ABI. Differential: arterial (punched-out, painful, distal), neuropathic (plantar).","images":[{"u":"/assets/Uploads/venous-ulcer-01.jpg","cap":"Venous leg ulcer","c":"© DermNet"},{"u":"/assets/Uploads/venous-ulcer-03.jpg","cap":"Venous leg ulcer","c":"© DermNet"},{"u":"/assets/Uploads/venous-ulcer-02.jpg","cap":"Venous leg ulcer","c":"© DermNet"},{"u":"/assets/Uploads/venous-disease-04.jpg","cap":"Venous dermatitis and ulceration","c":"© DermNet"},{"u":"/assets/Uploads/venous-disease-05-v2.jpg","cap":"Lipodermatosclerosis","c":"© DermNet"},{"u":"/assets/Uploads/venous-disease-06.jpg","cap":"Venous eczema","c":"© DermNet"},{"u":"/assets/Uploads/infected-venous-disease-07.jpg","cap":"Infected venous ulcer","c":"© DermNet"}]},{"id":"transient-neonatal-pustular-melanosis","name":"Transient neonatal pustular melanosis","cat":"neo","lvl":2,"alt":[],"dx":[{"text":"Erythema toxicum"},{"id":"impetigo"},{"id":"miliaria"},{"id":"herpes-simplex"}],"pearl":"Present at birth: superficial pustules that rupture to leave collarettes and hyperpigmented macules; more frequent in infants with darker skin. Smear shows neutrophils (vs eosinophils in erythema toxicum). Benign; resolves in weeks.","images":[{"u":"/assets/Uploads/neonatal-pustular-melanosis-1.jpg","cap":"Neonatal pustular melanosis","c":"© DermNet"},{"u":"/assets/Uploads/neonatal-pustular-melanosis-2.jpg","cap":"Neonatal pustular melanosis","c":"© DermNet"},{"u":"/assets/Uploads/neonatal-pustular-melanosis-v3.jpg","cap":"Transient neonatal pustular melanosis","c":"© DermNet"}]},{"id":"napkin-dermatitis","name":"Diaper dermatitis","cat":"neo","lvl":1,"alt":["Napkin dermatitis"],"dx":[{"id":"candida"},{"id":"langerhans-cell-histiocytosis"},{"id":"acrodermatitis-enteropathica"},{"text":"Psoriasis"}],"pearl":"Irritant dermatitis of convex surfaces that spares the folds (jacquet if erosive), versus candidal dermatitis with satellite pustules and fold involvement. Persistent, punched-out erosions: Jacquet erosive dermatitis. Barrier creams; Candida: nystatin/azole; consider LCH or zinc deficiency if it is refractory.","images":[{"u":"/assets/Uploads/dermatitis/nrash.jpg","cap":"Napkin dermatitis","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/napkin-thrush-s.jpg","cap":"Napkin dermatitis thrush","c":"© DermNet"},{"u":"/assets/Uploads/dermatitis/napkin-dermatitis19-s.jpg","cap":"Napkin dermatitis","c":"© DermNet"}]},{"id":"aplasia-cutis","name":"Aplasia cutis congenita","cat":"neo","lvl":2,"alt":[],"dx":[{"id":"sebaceous-naevus"},{"id":"epidermolysis-bullosa"},{"id":"folliculitis-decalvans"}],"pearl":"Localized absence of skin on the scalp vertex at birth; \"hair collar sign\" suggests an underlying neural tube defect (MRI). Associated with methimazole in pregnancy, Adams–Oliver syndrome and trisomy 13.","images":[{"u":"/assets/Uploads/lesions/aplasia-cutis.jpg","cap":"Aplasia cutis","c":"© DermNet"},{"u":"/assets/Uploads/lesions/aplasia-cutis2.jpg","cap":"Aplasia cutis","c":"© DermNet"}]},{"id":"aphthous-ulcer","name":"Aphthous ulcer","cat":"oral","lvl":1,"alt":["Aphthous stomatitis","Canker sore"],"dx":[{"id":"herpes-simplex"},{"id":"behcet-disease"},{"id":"oral-lichen-planus"}],"pearl":"Painful round ulcers with a yellow-gray base and an erythematous halo on non-keratinized mucosa. Minor (<1 cm), major (Sutton), herpetiform. Recurrent aphthae: check for B12, folate, iron, celiac disease, IBD, Behçet, and PFAPA. Topical steroids; colchicine; apremilast.","images":[{"u":"/assets/Uploads/site-age-specific/aphth.jpg","cap":"Aphthous ulcer","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/s/aphth1.jpg","cap":"Aphthous ulceration","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/site-age-specific/s/aphth2.jpg","cap":"Aphthous ulceration","c":"© Raimo Suhonen"}]},{"id":"oral-lichen-planus","name":"Oral lichen planus","cat":"oral","lvl":1,"alt":[],"dx":[{"id":"oral-candidiasis"},{"text":"Oral leukoplakia"},{"id":"mucous-membrane-pemphigoid"},{"id":"pemphigus-vulgaris"}],"pearl":"Reticular white Wickham striae of the buccal mucosa; erosive form is painful with SCC risk (~1–2%). Check for hepatitis C and contact allergy to dental amalgam. Treat with clobetasol gel/rinses and tacrolimus.","images":[{"u":"/assets/Uploads/scaly/olp2.jpg","cap":"Reticular lichen planus","c":"© DermNet"},{"u":"/assets/Uploads/scaly/olp3.jpg","cap":"Erosive lichen planus","c":"© DermNet"},{"u":"/assets/Uploads/scaly/olp1.jpg","cap":"Plaque lichen planus","c":"© DermNet"},{"u":"/assets/Uploads/lichen-planus-reticular.jpg","cap":"Reticular pattern","c":"© DermNet"},{"u":"/assets/Uploads/scaly/olp7.jpg","cap":"Erosive pattern","c":"© DermNet"},{"u":"/assets/Uploads/lichentong1.jpg","cap":"Plaque pattern","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/w/oral-cancer.jpg","cap":"Alveolar cancer","c":"© DermNet"}]},{"id":"oral-hairy-leukoplakia","name":"Oral hairy leukoplakia","cat":"oral","lvl":2,"alt":[],"dx":[{"id":"oral-candidiasis"},{"id":"oral-lichen-planus"},{"text":"Oral leukoplakia"}],"pearl":"Corrugated white plaques on the lateral tongue that do not rub off; caused by EBV replication in immunosuppressed (HIV; CD4 <300). No malignant potential; treated with antiretroviral therapy, valacyclovir or podophyllin.","images":[{"u":"/assets/collection-O/Oral-hairy-leukoplakia/oral-hairy-leukoplakia-00001.jpg","cap":"oral hairy leukoplakia 00001","c":"© Dr Mashihul Hossain"},{"u":"/assets/collection-O/Oral-hairy-leukoplakia/oral-hairy-leukoplakia-00003.jpg","cap":"oral hairy leukoplakia 00003","c":"© DermNet"},{"u":"/assets/collection-O/Oral-hairy-leukoplakia/oral-hairy-leukoplakia-00005.jpg","cap":"oral hairy leukoplakia 00005","c":"© DermNet"},{"u":"/assets/collection-O/Oral-hairy-leukoplakia/oral-hairy-leukoplakia-00008.jpg","cap":"oral hairy leukoplakia 00008","c":"© DermNet"}]},{"id":"geographic-tongue","name":"Geographic tongue","cat":"oral","lvl":1,"alt":["Benign migratory glossitis","Erythema migrans"],"dx":[{"id":"oral-candidiasis"},{"id":"oral-lichen-planus"},{"text":"Oral leukoplakia"}],"pearl":"Migrating erythematous, depapillated patches with a white serpiginous border; more common in atopic patients and in psoriasis (as the oral analogue of pustular psoriasis). Benign; no treatment required.","images":[{"u":"/assets/Uploads/site-age-specific/geog-tongue1.jpg","cap":"Geographic tongue","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/geog-tongue2.jpg","cap":"Geographic tongue","c":"© DermNet"},{"u":"/assets/Uploads/site-age-specific/s/geog-tongue4.jpg","cap":"Geographic tongue","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/site-age-specific/s/geog-tongue3.jpg","cap":"Geographic tongue","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/site-age-specific/s/geog-tongue6.jpg","cap":"Geographic tongue","c":"© Raimo Suhonen"},{"u":"/assets/Uploads/site-age-specific/s/geog-tongue5.jpg","cap":"Geographic tongue","c":"© Raimo Suhonen"}]}]};
